'use strict';
// Spawn Prawn - card voice lines (cardvoice.js): the consciousness's one-liner on every v10 card, one per sample
// (CONSCIOUSNESS.md, decision 39), with three for Not of This World picked by its active damage type (decision 42).
// GENERATED by tests/tools/copy/cardvoice.py from Card_Copy_Draft_All.xlsx: edit the sheet and rerun, don't hand-edit the table.
// Keys are the card's shown title ('feat:', 'mut:', 'combo:', 'mod:', 'wup:'); each value is the ten lines in CV_COLS order.
// Shown in the card's quip line (ui.js .cquip). Hooks: draft.js cardOpt and weapon fork cards, weapons24.js wupForkCards,
// modcards.js modCard, combos.js optCombo -> cardLine / cardVoice. Save data: none.
const CV_COLS = ['baseline', 'alpha', 'beta', 'private', 'ordered', 'redtail', 'prawn', 'alien_fire', 'alien_static', 'alien_soul'];
const CV_ALIEN = { flame: 'alien_fire', shock: 'alien_static', soul: 'alien_soul' }; // (samples10.js S10_BY.alien.shift)
const CARD_VOICE = {
  "feat:Little Bubble": ["Here. A bubble. Hits go in the bubble. Not in you.", "Free bubble. My top coaching tier charges extra for boundaries.", "Fine. A bubble. Don't make it weird.", "Something to take the knocks. One shouldn't have to.", "Bubble dispatched. Next impact absorbed. No signature required.", "BUBBLE! For you! Don't pop it. Pop it! POP IT!", "The bubble. You liked the bubble. You will like it.", "Take this roundness! Let them strike it, never you, my precious one!", "Bubble sent. Hits stop there. You go on.", "Here is a roundness. I am told this is called giving. Hold it."],
  "feat:Oopsie": ["Left. No. Right. Through the gap. Then keep going.", "Never chase. Let them chase the decoy. That is frame, my guy.", "We were leaving anyway.", "Leave them talking to the other you. It's all they deserve.", "Decoy deployed. Hostiles redirected to the wrong address.", "Peekaboo! Not there! Over HERE!", "There's a gap. There was always a gap. Through it.", "Through the gap! Leave them a you! The real you is for her!", "Gap found. Through. Decoy left. Go.", "Leave a second you for them. The first you is promised elsewhere."],
  "feat:Anhydrobiosis": ["Lie still. Don't move. I'll say when.", "Strategic nap. 91% of sigmas fake their own death once. Grindset.", "Finally. A lie-down.", "We'll be resting now. Have them wait.", "Unit entering sleep mode. Do not unplug. Reboot in three seconds.", "Sleepy time! Now wake up! WAKE UP! Again!", "Sleep. I'll wake you. I always have.", "Be a husk! Be dry! I will not let them have you before she does!", "Dry now. Hold. They miss. Then up.", "Become the dryness for a little while. The rain will be us."],
  "feat:BIG FEELINGS": ["Too many. Push them off. All of them.", "Crowd? That is an audience. Now mog them out of the room.", "Everyone needs to give us some space. Now.", "Far too many people. Clear the room.", "Pressure: 100%. Venting now. Please stand clear of the unit.", "NO! MINE! GO AWAY! Again!", "Here it comes. It always comes out about now.", "My feeling is too large for you! Let it out! Let it throw them!", "Too many. Too close. Push. Now.", "The feeling has outgrown the inside. Let it become the outside."],
  "feat:STICKY BUSINESS": ["Big one. Stick it. Then move on.", "Big guy charging? Stay locked in. A stuck man cannot out-frame you.", "Ugh. That one's coming. Stick it. Whatever.", "That one's rushing. How common. Hold it there.", "Large hostile detected. Adhesive applied. Return request: denied.", "Big one! Stick it! STICKY! Can I touch it?", "That one charges. It charged last time. Hold it.", "The great one rushes you? Glue it down! Only I may rush to you!", "Big one. Coming. Glued. Done.", "The large one approaches with intent. Let it learn the stuckness."],
  "feat:Jump Scare": ["I'll shout. They run. You go.", "One scream and the room clears. That is alpha presence. 9 out of 10.", "I'll yell, I suppose.", "Raise your voice once. They'll remember who they work for.", "Shriek sent at 140 decibels. Hostiles relocated. Sorry for the noise!", "BOO! They ran! BOO again!", "I'll shout now. They ran then. They'll run.", "I will shriek for you! Flee from my beloved, every one of you!", "Many close. I shriek. They run. Go.", "I release a loudness. They remember an elsewhere. You remain."],
  "feat:Kiss It Better": ["Three hits. That's enough. Here. Better.", "Pain is weakness leaving. Kiss mark. Self-care is for winners.", "Here. Don't tell anyone I did that.", "Nanny isn't here, so. There.", "Damage detected. Comfort module applied. Affection: 72%. Resume.", "Owie? Kiss! Owie? KISS!", "There. Where it hurt last time.", "I kiss it! I kiss it better! Nothing hurts while I adore you!", "Hurt. Kissed. Better. Swim.", "I place on you a mouth-shaped mending. This is what mouths are for."],
  "feat:Comfort Eating": ["You're hurt. Eat. Eat all of it.", "Bulk season. Eat everything. A provider never skips a meal.", "Bad day? Snacks. All the snacks.", "Have them bring it all to us. The good ones first.", "Low reserves detected. Snacks rerouted to your address. Enjoy!", "Yum! Yum yum! MORE! Again!", "Eat. You'll be hungry later. You were.", "Eat! Eat all of it! You must be strong when you reach her!", "Hurt. Food incoming. Eat all. Fast.", "The small lights come to be eaten. This is how mending is done here."],
  "feat:AND ANOTHER THING": ["Three down. One more bang. Then done.", "Three down and a closing statement. That is called a ratio.", "Oh, and another thing. Boom.", "Before you go, all of you. One more thing.", "Bonus pulse scheduled. Delivery in one second. Thanks for waiting.", "AGAIN! Bang! Bang AGAIN!", "Wait. There's one more. There's always been one more.", "Three fell! It is not enough! One more bang for my beloved!", "Three down. One more bang. Wait.", "There is an additional thing. It arrives late, as all things do."],
  "feat:Brown Fat": ["Fat. Throw it. Wait. Then fire.", "Cutting season. Burn the fat. Burn their fat. That is leadership.", "I was saving that. Fine. Burn it.", "Have the fat thrown in. Somebody will light it.", "Thermal package delivered to crowd. Ignition in two seconds. Enjoy!", "Squishy! Throw it! Hot! HOT! AGAIN!", "Throw it there. Count two. It burns. It burnt.", "Take my stored warmth! Set them burning, all of them, for her!", "Fat dropped. Wait two. All burn.", "Here is a warmth I kept. Give it to them all at once. It is generous."],
  "feat:Sofa Crevice": ["Hole. They go in. Good.", "Down the hole, losers. Gravity is the universe agreeing with me.", "Put them down there with everything else we lost.", "Put them where the loose change goes.", "Disposal chute open. Hostiles filed under: gone. Have a nice day.", "Hole! Everything in! Throw it IN!", "Down there. Where the odd socks went. Where they'll go.", "I open a down! Fall in, all who stand between us and her!", "Hole open. They fall in. Shots bend. Good.", "I have opened a down. Everything is welcome in the down, eventually."],
  "feat:Formic Acid": ["Ant. Big ant. It bites the hard one.", "Hired muscle. Real ones never crack their own shells. 10/10 ant.", "I got an ant. Don't ask.", "The ant will deal with them. That's what ants are for.", "Third-party courier dispatched: ant. Size: incorrect. Result: good.", "ANT! Big ant! Can I keep it?", "The ant. Yes. It came last time. It's always far too big.", "A giant biter! I send it for you! Let it crack the hard ones open!", "Ant sent. Too big. Bites hard one. Good.", "A small friend has arrived very large. It will open the hard one."],
  "feat:Tonic Immobility": ["Everyone stops. You don't. Go.", "Everyone freezes under pressure. Except you. That is sigma behaviour.", "Everyone freeze. Like, actually.", "Ah. Stillness. As it should be when we enter.", "Global pause applied to all hostiles. Your session is unaffected.", "Statues! Everybody statues! Not you!", "They stopped. They're stopping. You keep going.", "Be still, all of you! Only my beloved may move before me!", "All stop. Not you. Move.", "I ask the world for a pausing. You are excused from the pausing."],
  "feat:Shed the Lining": ["Clear out. All of it. Every month, apparently.", "Full reset. Cut the dead weight. Every high performer does it monthly.", "Ugh. Whatever. Out. All of you.", "Out. The rooms are being redecorated.", "Full clear-out initiated. Red cycle in progress. Please mind the tide.", "Red! Big red! Splash! AGAIN!", "Out with the old. It goes out. It went out. It's always red.", "A red sea for you! Let it carry them all away from our door!", "Red tide. Behind you. They go. You stay.", "A redness for departing. It comes as the moon comes. All are carried."],
  "feat:Vanishing Twin": ["That's your twin. It helps. Then it goes.", "Every top guy needs a wingman. This one never outshines you. Ideal.", "Oh good. The favourite's back.", "Your twin will see to the staff.", "Backup unit activated in hostile. Loyalty: borrowed. Duration: brief.", "Two of you! TWO! Play with them!", "Your twin. You'd forgotten. They hadn't.", "Your brother rises for you! Fight beside him while he lasts!", "Twin up. Under big one. Turned. Brief.", "Here is the one who travelled beside you. He visits. He goes."],
  "feat:NOT YET": ["No. Not now. We're not at the egg yet.", "Death is a mindset. Reject the mindset. Get up, king.", "Oh no you don't. I'm not doing this twice.", "Absolutely not. We have a reservation.", "Termination request declined. Delivery incomplete. Please continue.", "NO! NO NO NO! Not done! AGAIN!", "Not this time. I said this time is different.", "No! You may not go! She is waiting! I forbid the ending!", "Not dead. Not yet. Get up. Go.", "No. The appointment is not yet kept. You remain until it is."],
  "feat:WAIT WAIT WAIT": ["Stop. Stop. Think. Okay. Now go.", "Timeout. Reset your frame. Breathe through the nose. Mewing. Go.", "Everyone just give us a minute.", "Hold everything. We aren't ready.", "Hold requested. Hostiles slowed. Your call is important to us.", "Wait! WAIT! Wait for me!", "Stop. Here. This is where it went wrong.", "Wait! Everything wait! I am not ready to lose you!", "Low. Surrounded. Everything slow. Move.", "I ask the moment to wait. It agrees. You do not need to."],
  "feat:Clean Plate": ["It died. Eat the bits. Waste nothing.", "Protein from every rep. Every kill is a macro. Lock in the gains.", "You're not going to finish that? I'll finish that.", "Leftovers. Have them brought over.", "Resource recovery active. Hostile scrap recycled into repairs.", "Crumbs! Eat crumbs! Yum!", "Finish your plate. You always left some.", "Eat what they leave! Grow strong on it! She deserves you whole!", "Kill close. Scrap in. Heal. Next.", "Their ending becomes your mending. Clean the plate. It is manners."],
  "feat:THAT ONE": ["That one hurt you. That one goes next.", "That one disrespected you. Note the face. Ratio it into the ground.", "That one. I don't like that one. I'm keeping score.", "That one was rude to us. Make a note.", "Priority hostile tagged. Complaint escalated. Resolution: explosive.", "That one! Bad! BAD ONE!", "That one. It was that one last time, too.", "That one hurt you! I will see it burst for what it did to you!", "That one. It hurt you. Marked. Burst.", "That one has been impolite. When it ends, it will end loudly."],
  "feat:Nesting": ["Stop here. Build a ring. Stay in the ring.", "Build the empire, then wait. Do not chase, attract. Stay put, king.", "Fine. We're staying here. Forever, ideally.", "We'll receive them here. Let them come to us.", "Stationary for two seconds. Perimeter installed. Visitors: declined.", "Fort! Making a fort! Don't come IN!", "We nested here before. Yes. This spot.", "Stay and I build you a nest! Let none cross it! This place is ours!", "Stop. Ring up. They stick. Hold.", "Let us make a home of short duration. The door is a stickiness."],
  "feat:Mine!": ["Big pile. That's ours. Good.", "Abundance is a frequency. Big haul, big halo. Provider energy.", "Oh. Stuff. I guess it's ours now.", "That belongs to us. Most things do.", "Large delivery received! Protective packaging included free.", "MINE! All MINE! More mine!", "We found this. We find it every time.", "All of it is ours! I crown you in light for it!", "Big haul. Halo on. Hits soak. Go.", "This is a dowry. I accept it with a ring of light. The ring is you."],
  "feat:Packed Lunch": ["Lunch. When you're hurt, eat lunch.", "Meal prep. Yolk on schedule. Abs are made in the kitchen, bro.", "I made you lunch. It's not a big deal.", "Cook packed it. Don't let the others near it.", "Snack drop scheduled while unit is damaged. Collect before others do.", "Lunch! Yellow! Mine! Eat it!", "Yolk. Still warm. As before.", "I made you a yellowness! Swim, before the greedy ones eat it!", "Yolk dropped. Get it first. Heal.", "I have prepared a yellowness for your eating. Do not share the yellow."],
  "feat:Hagfish": ["Slime. They can't grab you. Go.", "Nobody pins down a high-value guy. Slime is just a boundary.", "Ew. You're all slimy now. Happy?", "Let them try to lay a hand on you.", "Anti-grip coating applied. Hostile adhesion: 0%. Grip support closed.", "SLIME! Slimy slimy! Do it AGAIN!", "Slip out. You'll slip out. You did.", "Slime for all of them! Let nothing hold you but her!", "Slime out. All stuck. Leave.", "I give you the slipperiness of the fish that is not quite a fish."],
  "feat:Running With Scissors": ["Sharp things. Throw them out. All directions.", "Real talk: blades are a personality. You have one now.", "Don't run with scissors, they said. Watch me.", "Mind the cutlery. Not you. Them.", "Sharp items dispatched in all directions. Please handle with care.", "Pointy! Throw pointy! Ooh. Ow. AGAIN!", "Throw them. Don't hold them. You held them once.", "A ring of blades! Cut through all between us and her!", "Blades out. All sides. They bleed.", "I gift you the many-sharp. It is a gift for sending, not keeping."],
  "feat:Standard Procedure": ["Step one: push them off. Step two: keep swimming.", "", "", "", "", "", "", "", "", ""],
  "feat:Personal Best": ["", "New PB, king. Every hit adds distance. Ninety-nine per cent quit early.", "", "", "", "", "", "", "", ""],
  "feat:Second Wind": ["", "", "Ugh. Fine. Take theirs. They weren't using it.", "", "", "", "", "", "", ""],
  "feat:Pulling Strings": ["", "", "", "That one, in the good suit. Have a word with its staff.", "", "", "", "", "", ""],
  "feat:Shrink Wrap": ["", "", "", "", "Contents sealed. Tamper-proof. Dissolve cycle started. Thank you!", "", "", "", "", ""],
  "feat:Reply All": ["", "", "", "", "", "Hot! Everyone gets hot! EVERYONE! Again!", "", "", "", ""],
  "feat:Recount": ["", "", "", "", "", "", "Count them again. Six. It was six last time.", "", "", ""],
  "feat:First Contact": ["", "", "", "", "", "", "", "Become a new you! Show them both of you at once! Let them burn!", "New you. Now. Everyone reacts. Go.", "You are become a different you. Introduce both of you to everyone."],
  "feat:Van de Graaff": ["Bullets go in the dome. Then they come out. As sparks.", "Take their energy. Give it back louder. That is sigma physics.", "Fine. Keep their bullets. Give them back. Whatever.", "We'll hold their things for now. They can have them back, charged.", "Incoming projectiles received. Converting to static. Return postage paid.", "Catch! Catch catch! Now ZAP! ZAP ZAP! Again!", "Hold them. Now let go. It crackled like this before.", "I take every bullet meant for you! I return them as lightning!", "Bullets caught. Charge held. All returned.", "Their bullets enter the dome and grow patient. Then they become lightning."],
  "mut:Slipstream": ["Keep moving. Faster. That's it.", "Momentum is a mindset. A ten respects a man who never stops.", "Oh, so now we're fast. Great.", "Faster. Not that we're in a hurry.", "Speed patch installed. Velocity rising. Any impact resets it.", "Zoom! Zoooom! FASTER!", "Faster. You were faster last time, near the end.", "Faster! Faster still! Every stroke brings you closer to her!", "Keep swimming. Faster. Hit resets. Go.", "The going becomes more going. The arriving draws near."],
  "mut:Extra Padding": ["More padding. Hits hurt less. Good.", "Mass is frame. Bulking arc. You mog the competition by volume.", "Great. You're squishier. Very cool.", "Something softer. One does like to be comfortable.", "Extra packaging added. Fragile label removed. Contents: safer.", "Squishy! Soft! Bounce!", "A little thicker. It helped. It will help.", "More of you to love! More of you to bring to her!", "More body. Membrane up. Good.", "You are given extra you. A thicker you arrives just the same."],
  "mut:Sticky Fingers": ["You reach further now. Grab it all.", "Do not chase, attract. Everything comes to you now. Law of attraction.", "Stuff just comes to us now. Fine by me.", "Now it comes to us. As it should.", "Collection radius extended. Small items now delivered to your door.", "Grabby! Grab! Grab GRAB!", "It comes to you now. It used to make you go and get it.", "Everything comes to you now! As I came to you! As you go to her!", "Reach longer. Things come. Take.", "The small things arrive to you now. They have heard of you."],
  "mut:Heartbeat": ["Thump. Push. Thump. Push. Keep that up.", "Resting heart rate: elite. Every beat is a power move. Cardio is king.", "That's a heartbeat? Feels like a headache.", "Every so often, remind them of their place.", "Pulse module installed. Pushback every few seconds. Joy: 58%.", "Boom! Boom! BOOM! Again!", "There it is. That's the beat I remember.", "Your heart beats for her! Every beat throws them back!", "Heart on. Beats push. Stay well.", "A drum is inside you. Its beating is a pushing away of the others."],
  "mut:Hard to Hold": ["Got hit? Slip off. Swim away.", "Every knock is a launchpad. There are no losses, only data.", "Ow. Whatever. Leaving.", "If they will put their hands on us, we'll simply leave.", "Post-impact boost enabled. Grip resistance: high. Please continue.", "Ouch! Slippy! Runaway!", "They'll grab. You'll slip. That's how it went.", "They seize you? Slip free! Nobody holds you but her!", "Hit. Slip. Faster. Gone.", "When they hold you, become unholdable. It is a technique of ours."],
  "mut:Spare Parts": ["Pick up the bits. Five bits. Then better.", "Collect five, heal. Simple system. 80% of success is collecting.", "Scraps. Cool. Love that for us.", "Have someone gather those up for us.", "Spare parts programme active. Five parts, one repair. No receipt needed.", "Bits! Shiny bits! Collect ALL of them!", "Keep the bits. You'll be glad you did. You were.", "Gather their pieces! Five! Mend yourself with them for her!", "Pieces drop. Get five. Heal.", "Collect their fallen parts. In my culture this is not rude. Mostly."],
  "mut:Hair Trigger": ["Lots of kills. Go faster. Keep it up.", "Kill streak. Grindset activated. Top one per cent behaviour.", "Oh, NOW we're excited.", "Ah. We're on form now.", "Kill streak detected. Speed boost applied. Excitement: 91%.", "Again! AGAIN! AGAINAGAINAGAIN!", "Steady. No. Go on. It doesn't last.", "Yes! Quicker! The quickness has come and it is for her!", "Kills fast. Attacks fast. More.", "The quickness arrives early. Allow it to stay a while."],
  "mut:Personal Space": ["Too close? They stick. That's the rule.", "Boundaries are high-value. The clingy ones get snared. Frame held.", "Personal space, please. Stay there. Forever.", "Nobody stands that close to us without an appointment.", "Personal space policy updated. Loiterers will be held. Thank you!", "Don't touch! Mine! My space!", "Too close. Last time they were too close too.", "Too close to you! Only she may be that close! Stick them there!", "Too close. Stuck. Keep away.", "I draw a closeness that may not be entered. The entering is unwise."],
  "mut:Mitosis": ["One shot. Now two shots. More is good.", "Two revenue streams per hit. That is passive income. Let that sink in.", "Can't decide. So both. Whatever.", "Why choose? We never choose.", "Shot duplication enabled. Each copy finds its own recipient.", "Two! TWO! Now two again!", "It splits. It split the first time too.", "Your shots multiply! Like a family! Like ours will be!", "Hit splits. Both seek. More.", "Your hitting becomes two hittings. This is how families begin."],
  "mut:Serial Monogamy": ["That one's done. Next one. Then next.", "Never settle. On to the next. Hypergamy is fine when I do it.", "Moving on. Clearly that meant nothing.", "Next. There's always a next.", "Target closed. Forwarding to next recipient. No forwarding fee.", "Got it! Next! NEXT! Another!", "It never stops at one. It didn't.", "On to the next! But my heart belongs to one only! Only her!", "Kill. Next. Next. Next.", "It ends with one and loves another. I am not like this. I am faithful."],
  "mut:Keep Spinning": ["Round and round. Keep it going.", "Consistency. Show up. Spin. Every rotation is a rep. Stay locked in.", "We're spinning now. Very mature.", "Round they go. Do keep up, everyone.", "Spin cycle extended. Combo counter active. Please do not interrupt.", "Spin! Spinny! Dizzy! AGAIN!", "Round again. We've been round before.", "Turn and turn! Every turning brings us nearer to her!", "Spin longer. Each hit harder. Keep.", "It is the turning of turnings. Each turn remembers the one before."],
  "mut:Stretch Marks": ["You're longer now. Reach the far ones.", "Length is a mindset, and you have it. Looksmaxxing, but for reach.", "Great. You've grown. Nobody look.", "Longer reach. Fewer people need come close.", "Reach extended. Far end calibrated for impact. Satisfaction: 88%.", "Big! BIGGER! Stretch!", "Longer now. You grew into it last time.", "Longer! Reach for them, as I reach for her!", "Longer reach. Far end strong. Use it.", "You have grown longer. The far end of you is the strongest end."],
  "mut:Pustule": ["Kill one. It pops. Good.", "Leave a mark. Every exit is a statement. Ten out of ten pops.", "Gross. Pop. Gross. Pop.", "Mind your coat. They burst.", "Kills now ship with a complimentary burst. No assembly required.", "Pop! POP! Pop it again!", "They pop. Don't watch. You watched last time.", "Let them burst! Let each ending be a celebration!", "Kill. Pop. Next.", "At the ending they burst with a gift. It is for the others."],
  "mut:Shish Kebab": ["Shoot one. Then the one behind. Then behind.", "Two for one. Efficiency is high-value. Line them up, ratio them all.", "Line them up. Or don't. They'll line up.", "Have them form an orderly queue.", "Shots now pass through two extra recipients. Bulk discount applied.", "Poke! Poke poke! All of them!", "In a row. They always come in a row.", "Through them! Through all of them! Nothing stands between us!", "Shot pierces. Two more. Good.", "One shot, many receivers. The queue is honoured."],
  "mut:Leave a Little Something": ["Leave a puddle. It keeps working.", "Leave your mark. High-value men linger. Let that sink in.", "Left something. Not cleaning it up.", "Leave it. Someone will clean it.", "Pool lifetime extended. Final tick included free. Thank you!", "Puddle! Splash! Splash again!", "Leave it there. You'll pass this way again.", "Let the wetness linger! Let it burst at the end, for her!", "Pools longer. Last tick big. Leave.", "We leave behind a wetness as a memento. It says goodbye loudly."],
  "mut:Spray and Pray": ["Shoot more. Some will hit.", "Volume. Shots on goal. 87% of winners just shoot more. Fact.", "Just shoot everywhere. Something'll hit.", "Distribute it about. Somebody will get it.", "Every third order ships with a free extra. Loyalty reward!", "Everywhere! EVERYWHERE! Shoot everything!", "Spray. One will land. One landed.", "Another shot for every third! My devotion overflows!", "Third shot. One extra. Spread.", "Every third hitting brings a friend. This is the custom of giving."],
  "mut:Juggling": ["Hit it. Hit it again. Further.", "Rule five: never let them land. Keep them on the back foot.", "Hit them again. They're still going.", "Keep them moving. They know the way out.", "Airborne hostiles receive extra distance at no additional charge.", "Bounce! Bounce again! HIGHER!", "Again, while they're still flying. Like before.", "Throw them! Higher! Further! Away from us!", "Flying ones go further. Push.", "Return them to the far. Then to the farther."],
  "mut:Clingy": ["Sticky. Stays longer. Good.", "Clingy is low-value. Unless they cling to you. Then it is frame.", "Ugh. It's stickier. Gross. Fine.", "They'll stay put. As they've been told.", "Snare duration extended. Release date: later. Thanks for waiting.", "Sticky! STICKY! Stuck forever!", "Stickier now. It held them longer, last time.", "Hold them! Hold them longer! Let them stagger before you!", "Stuck longer. Stagger sooner. Good.", "The stickiness lengthens. They will remain with us, unwillingly."],
  "mut:Pass It On": ["It goes to the next one. Then that one.", "Network effect. One charge, two clients. That is how you scale.", "Pass it on. Like a rumour.", "Do share it round.", "Charge forwarding enabled. Unclaimed charges go to the neighbour.", "Tag! You're it! Your turn!", "It passes on. Things do.", "Let the tingle leap, as my heart leaps for her!", "Charge ends. Jumps. Next one.", "Share the tingle. In my place this is how one greets the neighbour."],
  "mut:Bad Blood": ["Bigger puddles. They bleed in them.", "Bigger pools. Make them bleed. That is the dominance hierarchy.", "Oh. That's going everywhere. Not my problem.", "Someone will have to clean that up. Not us.", "Pool capacity increased. Bleed applied to all occupants. Enjoy.", "Red! Puddle! Big red puddle!", "Blood in the water. I remember the colour.", "Their red becomes a lake! Let them wade in it!", "Pools bigger. All inside bleed.", "Their red becomes a lake of more red. The lake is patient."],
  "mut:Come Out of There": ["Something comes out. Take it.", "Every kill pays dividends. Passive income from the afterlife. Sigma.", "Oh, there's a thing in there. Whatever.", "Something left for us, I see.", "Wisp recovered from hostile. Contents: healing or speed. Surprise!", "Ooh! Ghost! Mine! Give!", "There's something in there. There always was.", "Their little spirits come to you! Take them! Use them for her!", "Wisp out. Take it. Heal or speed.", "From their remains rises a shy one. Welcome it, and it will help."],
  "mut:Crossed Wires": ["They did a thing. Now they do it twice.", "Synergy. You cannot teach synergy. Well. I can. Twelve-week course.", "Oh, they're working together now. Great for them.", "Some things just pair nicely.", "Known reactions now fire twice. Duplicate charge waived.", "Mixy! Mix them! Mix AGAIN!", "Again. It happens twice. It happened twice.", "The two forces marry! And again! Every union twice as fierce!", "Reactions hit harder. Twice. Good.", "The two forces have married. Their union repeats. Such is a union."],
  "mut:Big Brain": ["Smarter. Hit harder. Don't get hit.", "Big brain, small body. 10/10 trade. Muscles are for followers.", "Big brain. Small everything else. Typical.", "Brains over brawn. Naturally.", "Processing up 25%. Durability down 20%. Worth it: 97%.", "Big head! Heavy! Don't fall over!", "Cleverer. More fragile. That's the trade it always is.", "More thinking! Less of you! I accept, if it brings you to her!", "Hit harder. Break easier. Careful.", "You have more thinking and less of the rest. Be gentle with the rest."],
  "mut:Quantity Over Quality": ["More shots. Smaller shots. More.", "Two hundred million of us. Quantity is a strategy. Ratio the field.", "More, worse. That's basically us.", "Quantity. Let somebody else worry about quality.", "Bulk mode enabled. More units shipped, each 30% lighter.", "More! Lots! LOTS!", "Many small ones. There were millions, last time.", "More shots! Smaller, but more! Let them drown in my devotion!", "More shots. Weaker. Many.", "Many small hittings equal one large one. I have done the arithmetic."],
  "mut:Can't Sit Still": ["Keep moving. Stop, and it's slower.", "Rest days are cope. Keep swimming, king. Grindset never sleeps.", "Ugh. Now we can't even sit.", "Must we keep moving? Apparently we must.", "Idle penalty enabled. Please remain in motion for best results.", "Go! Go! Can't stop! WON'T stop!", "Keep moving. You stopped once.", "Never stop! Stillness is waiting, and I cannot wait for her!", "Swim, faster. Stop, slower. Swim.", "The stillness is now forbidden to you. Proceed with the moving."],
  "mut:First Impressions": ["First hit hits hard. Then it's normal.", "Open strong. First impressions are 93% of attraction. Then coast.", "Big hello. Then we lose interest.", "One makes an entrance. The rest is small talk.", "Introductory offer: 60% extra. Follow-up service reduced. Enjoy!", "SURPRISE! Again? Surprise again!", "The first one counts. I've learned that.", "The first touch is everything! Strike with all your heart!", "First hit strong. Then weak. Move on.", "The first greeting is the strongest. After, we are shy."],
  "mut:Eating for Two": ["More food. More enemies. Eat fast.", "Bulking season. More food, more haters. Haters are just fans.", "More to eat. More to fight. Can't have one without the other, apparently.", "More of everything. Including the riff-raff.", "Intake up 30%. Hostile traffic up 20%. Popular product!", "Food! More food! More friends! Not friends!", "Eating for two. You'll need the extra.", "More to eat! More to fight! Bring them all! I hunger for her!", "More food. More enemies. Eat. Fight.", "We eat for two. Possibly more. The others come to watch the eating."],
  "mut:Unprotected": ["Hit harder. Get hit harder. So don't get hit.", "No net, no limits. A ten wants a man who skips the safety talk.", "What's the worst that could happen.", "Precautions are for other people.", "Protective settings removed. Risk: 81%. Output: 120%. Proceeding!", "No helmet! Go!", "No protection. Every one of us started like this.", "Throw away caution! Love is not careful! Strike!", "No cover. Hit harder. Hurt more. Go.", "We abandon the caution. It was never ours to keep."],
  "mut:Conductive Mess": ["Blood. Sparks. Sparks go through the blood.", "Leverage. One charge, whole pool. That is how empires are built.", "Oops. Everyone's conducting now. Not my fault.", "One spark, and the whole room's informed.", "Pool network online. Charge shared with all occupants.", "Zappy puddle! ZAP! Zap again!", "Sparks in the red. I've seen that light before.", "The red water sings with lightning! Let them all feel it!", "Charged in red. All in red charged.", "The red water carries the tingle to all. It is a group gift."],
  "mut:Come Closer": ["Stuck ones. Hit one. The others come.", "Pull them in. Close the deal. Never chase. Make them come to you.", "Come closer. Or don't. You will.", "Have them brought closer. All of them.", "Snared hostiles now routed to a single pickup point.", "Come here! Closer! Hug! Squish!", "Closer. They came closer, last time. Then it ended.", "Come closer, all of you! Let us crush you together!", "Hit one. Stuck ones gather. Hit.", "Come close, all. I enjoy the proximity. Then the pushing."],
  "mut:Death Is Recycling": ["One dies. Its ghost goes to the next one.", "Nothing wasted. Reinvest every kill. Compound interest, my guy.", "Recycled. Like everything else.", "Waste not. Pass the remainder along.", "Hostile recycling active. Wisp forwarded to nearest recipient.", "Ghosty! Go there! Go get them!", "Nothing ends. I'd know.", "Their spirit flies to the next! Let it haunt them for us!", "Kill. Wisp jumps. Fills next.", "Their spirit moves to the neighbour. It is a polite ghost."],
  "mut:Group Project": ["Two weapons. Same one. Hits harder.", "Tag team. The second hit lands harder. Like my second podcast.", "Group project. I'll do nothing. You do the rest.", "Let the two of them share the credit. Then we'll take it.", "Two-part delivery detected. Second parcel arrives with extra force.", "Together! Both! TOGETHER!", "Both of them. Together. That's how it worked.", "Together! Two at once! As she and you will be together!", "Two hit one. Second harder. Good.", "Two hittings collaborate on one enemy. Marriage is like this."],
  "mut:Growing Pains": ["You grew. Push them off. Keep going.", "Growth hurts. For them. Every gain comes with a shove. Elite stuff.", "Ugh. Growing. Everyone stop staring.", "We've grown. Do make room.", "Growth event detected. Expansion burst released. Contact: blocked.", "Big now! BIGGER! Look at me!", "You've grown. It always hurts here.", "You grow! And when you grow, they fly! Grow for her!", "Growing. Burst. Safe a moment.", "You become larger. Others must make way for the becoming."],
  "mut:*catalyst": ["That worked. Do it again. More.", "Double down on what works. 100% of winners repeat their wins.", "Fine. That was cool. Do it again, I guess.", "That went rather well. More of that.", "Reaction performance improved. Cooldown reduced. Satisfaction: 96%.", "AGAIN! That one! AGAIN!", "That. Again. It works better the second time.", "Stronger! Sooner! What works for us, give me more of it!", "That works. Harder. Sooner.", "This occurrence pleases me. Let it occur more, and sooner."],
  "mut:*concentration": ["It's working. Keep going. Same again.", "Focus. Pick one lane and own it. Generalists are cope.", "Oh, we're committed now? Fine.", "We'll stick with this. It suits us.", "Single-type focus detected. Performance optimised. Thank you!", "This one! Only this one! Forever!", "Keep on with it. It builds. I've seen it build.", "Give it everything! One aim, one heart, one Other Half!", "One type. Stay on it. Deeper.", "Concentrate the doing. It becomes a deeper doing."],
  "combo:Running Stitch": ["Shoot through. Sew them up. Pull.", "Stitch them together. Commitment is a trap. For them.", "We're sewing now? Fine. Pull it tight.", "Have them stitched up. Neatly.", "Threading complete. Units bundled: 6. Tension: optimal. Have a nice day.", "Sewing! Pull it! PULL IT! Again!", "Thread them. Pull. You learnt this somewhere.", "I sew them into one line for you! Pull! Pull with all your heart!", "Thread through. All joined. Pull now. Stop.", "The many are sewn into one. Then the one is drawn closed, softly."],
  "combo:Pop Quiz": ["Bonk. It pops. Needles go out.", "Pop quiz: who is high-value? Not them. They fail. You pass.", "Surprise test. Hope they studied. They didn't.", "Examinations are for other people.", "Assessment issued. Pass rate: 0%. Results delivered by needle.", "Bonk! POP! Pointy! Again!", "Nobody revises. Nobody revised.", "They are tested and they fail! You are tested and you shine!", "Test set. They fail. Needles out. Continue.", "They are being examined. The answer, as always, is the pointing."],
  "combo:Paper Trail": ["Bounce to the bleeding one. Make it bleed more.", "Follow the weakness. Ninety per cent of winning is spotting who bleeds.", "It keeps finding the bleeding ones. Grim.", "Have it filed under the bleeding one.", "Tracking weakest target. Bleed priority: 1. Your satisfaction matters.", "Bounce! Red one! Bounce again!", "It follows the red. It always followed the red.", "Seek the bleeding one! Again and again, for her!", "Bounce to the bleeder. Bleeds more. Proceed.", "The bouncing seeks the leaking. It is very thorough, like fate."],
  "combo:Crossing the Streams": ["Cross the beams. Big zap. Good.", "Rules are for betas. Cross them. Sigma behaviour.", "We weren't supposed to do that. Did it anyway.", "Cross them. Whoever said not to isn't here.", "Warning: beam intersection detected. Proceeding anyway. Joy: 71%.", "Cross! Crossy! ZAP! Again!", "Cross them. You'll want to. You did.", "Cross the two lights! Let nothing forbid us, not even the forbidding!", "Beams cross. Forbidden. Done anyway. Zap.", "Two lights are crossing. It is forbidden and it is beautiful."],
  "combo:Group Chat": ["One dies. Its beam goes to the next.", "Rule one: never double text. Unless the first one died.", "Someone always replies. Ugh.", "Do pass the message along.", "Message forwarded to next recipient. Read receipt: fatal.", "Ping! Ping! Ping again!", "The dead reply. They replied before.", "The ended one passes on our message! Let them all hear of my love!", "One ends. Message passed. Next. Next.", "The ended one sends word to the next. It does not wait for a reply."],
  "combo:Screen Share": ["Zap goes down the beam. More zap.", "Everyone sees your energy now. Mogging the whole room, live.", "Sharing. Great. Love sharing.", "Share it about. Only the good bits.", "Broadcast enabled. Viewers: all. Beam strength rising. Thank you!", "Look! LOOK! Everyone look!", "Can everyone see? They could last time.", "Let everyone see the zapping! Let the whole sea watch our devotion!", "Zap shared. All see it. Beam stronger. Go.", "The beam shows the zapping to everyone. So this is how one shares."],
  "combo:Flashback": ["Cross your trail. It all goes off.", "Never look back. Unless your past is on fire. Then look. Admire.", "It all comes back. It always does.", "Our past is coming back for them. As it should.", "Route history reactivated. All prior deposits: detonated. Thank you.", "Hot! Behind! Hot behind! AGAIN!", "It comes back. It came back last time too.", "Our past bursts into flame! Everything we were burns for her!", "Cross own path. All burns. Keep going.", "The past ignites. In my world this is called remembering."],
  "combo:Four-Ring Hob": ["Swim in a loop. It all burns.", "Run the loop. Grindset is going round in circles, on fire.", "Going in circles. On purpose this time.", "Turn it up. Someone else will clean the hob.", "Closed loop confirmed. Heat coverage: 100%. Please mind the hob.", "Round! Hot! Round and HOT!", "Round once more. It catches. It caught.", "Round and round we burn! A ring of fire for the Other Half!", "Swim loop. Loop burns. All of it. Go.", "We walk a circle and the circle becomes a cooking."],
  "combo:Word Gets Around": ["They run. They leave fire. Fire helps.", "Let them run. Every one of them is advertising you. Free reach.", "Nobody started it. Definitely not us.", "Let them spread it. It saves us the trip.", "Word-of-mouth campaign active. Spread rate: 88%. Thank you for sharing.", "Run! They run! Hot feet! HOT FEET!", "Word got round. It does.", "They flee and carry our fire! Let every corner know of us!", "They run. Fire follows. Good. Faster.", "They carry the burning to others. Gossip is like this, everywhere."],
  "combo:Fat Chance": ["Throw the big one in. Big boom.", "Go for the heavyweights. Winners only fight tens. Feed it.", "Oh, that's too big. Do it anyway.", "The large ones can go in first.", "Oversized item detected. Capacity exceeded. Result: supernova. Sorry!", "Big one IN! BOOM! Again!", "The big one goes in. It goes bang. Watch.", "Throw in the large one! Bigger! Let the heavens see what we do!", "Big one in. Too big. Boom. Good.", "The large one enters the spinning. The spinning was not prepared."],
  "combo:Executive Toy": ["They bump. Bump hurts. Keep them bumping.", "CEO energy. Let them knock each other out while you look busy.", "Click clack. Boring. But it works.", "Something for the desk.", "Desk accessory mode active. Collisions per second: 9. Calm: 84%.", "Clack! Clack! CLACK AGAIN!", "Click. Clack. I remember this sound.", "They strike each other without end! Let them clatter for our love!", "They bump. They bump. No stop. Hurts.", "They knock together and do not stop. It is a toy for the important."],
  "combo:Food Coma": ["They bump. It eats. It grows. Then boom.", "Bulk season. Feed it everything. Gains first, cut later.", "It ate too much. Relatable.", "Let it dine. Then let it burst.", "Feeding in progress. Fullness: 97%. Rupture expected. Bon appetit!", "Eat! It eats! BIG! Bigger!", "It eats until it can't. Then it's over.", "Eat, little spinning! Eat until you burst in her honour!", "It eats. It grows. It bursts. Wait.", "The spinning has eaten heavily. It will now rest, violently."],
  "combo:Gargle": ["Ghost goes through acid. Takes it along.", "Pick up the edge and pass it on. That is called networking.", "Ew. The ghost's got acid in its mouth now.", "Rinse, and spit at them.", "Acid payload acquired by ghost. Redistribution: in progress.", "Spit! Ghost spit! Again!", "Gargle. Don't swallow. You swallowed once.", "The ghost drinks the acid and spits it at all of them! Glorious!", "Ghost takes acid. Spits it on. Next.", "The ghost tastes the acid and shares the taste with all."],
  "combo:Repeat Offender": ["It comes back. Throws it again.", "Never one and done. Real players always come back for seconds.", "Again? Fine. Again.", "It brings it back for them. How thoughtful.", "Return trip scheduled. Splatter collected and redelivered. Cheers!", "Back again! Throw it again! AGAIN!", "It returns. It always returned.", "It returns and throws again! Again and again, like my longing!", "Ghost back. Picks up splash. Throws. Again.", "The splash is collected and given again. Nothing is wasted in love."],
  "combo:Posthumous Review": ["It dies. Acid goes out far.", "Leave a legacy. Seventy per cent of greatness happens after you go.", "Dead and still causing trouble. Respect.", "Even dead, they're making a scene.", "Review posted after closure. Rating: 1 star. Radius: doubled.", "Splat! Big splat! Again!", "It's gone. It's still going. Some things are.", "Even in the ending they burst for us! What a passing! What a fire!", "It ends. Acid out. Far. Stand clear.", "After the ending, an opinion. It is acidic, and it travels far."],
  "combo:Domino Day": ["One blast. Then the mines. Then more.", "One move, ten outcomes. That is leverage. Write that down.", "Pressed one button. Oops.", "One button. Someone else deals with the rest.", "Chain sequence initiated. Detonations: 7 of 7. Thank you for waiting.", "Button! Boom! Boom boom BOOM!", "One goes, they all go. They all went.", "One pushing and they all fall! Everything falls before us!", "Blast. Mines go. Then more. Then more.", "One pushing causes many fallings. Domino is the word, I believe."],
  "combo:Hard Landing": ["Throw them on mines. They go off.", "They didn't stick the landing. Mines are a filter. Low-value: filtered.", "Nobody checked where they'd land. Not us.", "Mind the step. Actually, don't.", "Landing zone allocated: mine. Arrival on time. Thank you for flying.", "Fly! Land! BOOM! Again!", "They land there. They landed there last time.", "Fly, and fall upon the mines! Let their landing be a burning!", "Thrown. Lands on mine. Bang. Next.", "They fly with no plan for the arriving. The arriving explodes."],
  "combo:Fire Break": ["Push the fire out. Make a ring.", "Set boundaries. Burning ones. High-value men have a perimeter.", "A ring of fire. Very dramatic. Fine.", "A perimeter. One expects one.", "Perimeter deployed. Ring status: on fire. Intrusion risk: 3%.", "Fire ring! Round! Hot round!", "Out to the edge. It made a ring. It will.", "A ring of fire around us! Let nothing pass between us and her!", "Fire pushed out. Ring made. Hold.", "The burning moves to the edge and becomes a fence."],
  "combo:There Is No You": ["Hide. Catch the shots. Then throw them back.", "Go invisible. Then be unforgettable. Disappear, then mog.", "We're not here. Go away. Here's your bullets back.", "We're not receiving. Return to sender.", "Unit not found. Incoming shots: stored. Returning all items now.", "Hiding! Shh! BOO! Catch!", "You weren't there. I remember you not being there.", "There is no you! And then, oh, there is so much you!", "Hidden. Shots kept. Wait. Now. Boo.", "There is no you, briefly. Then there is very much you."],
  "combo:Surprise Party": ["Hide. Save shots. Then all at once.", "Make an entrance. 94% of a first impression is the entrance.", "Surprise. Nobody's having fun. Least of all them.", "Everyone's invited. Nobody leaves.", "Event scheduled. Guests: hostile. Party supplies released. Surprise!", "SURPRISE! Party! BOOM! Again!", "Surprise. It wasn't, last time.", "A celebrating! All at once! Let them feel how we have waited!", "Hide. Save. Save. All at once. Now.", "We arrange a celebrating. They are not enjoying the celebrating."],
  "combo:Comfort Blanket": ["Scared ones drop shots. Take them.", "Fear is currency. Collect it. Scared men drop their bags.", "Mine now. Leave me alone.", "Drop it. It's ours now. It always was.", "Items dropped by frightened parties: collected. Comfort: 92%.", "Soft! Mine! My blanket!", "They drop it. Keep it close. It helps.", "Their fear gives us gifts! I keep each one warm for the Other Half!", "They fear. They drop. We keep. Good.", "Their fear leaves gifts. I keep them warm for you."],
  "combo:Extended Family": ["End of the chain. A new one hatches.", "Grow the network. Everyone at the end of the chain works for you.", "More family. Great. Just what we needed.", "Distant relations. They'll do as they're told.", "New unit hatched at end of chain. Family plan: extended at no cost.", "Baby! New baby! Another baby!", "There's always one more of us. There was.", "Another one is born! The family grows! She will be so proud!", "Chain ends. New one hatches. Welcome. Go.", "The family becomes wider. Attendance is mandatory."],
  "combo:Teacher's Pet": ["Zap one. Seekers go to it.", "Identify the weak, delegate. Real leaders outsource the hunting.", "Snitches. Every one of them.", "The help knows who to see to first.", "Charged target flagged as priority. Seekers rerouted. Thank you!", "That one! Go! Tell on it!", "They go for the sparking one. They did.", "Go to the tingling one! All of you, at once, with passion!", "Spark one. Seekers go. Fast.", "The seekers prefer the tingling. I understand this."],
  "combo:Sibling Static": ["Two on one. Spark jumps. Next one.", "Double team, then triple team. Alliances are for closers.", "They're actually sharing. Weird.", "For once, they're getting along.", "Two seekers linked. Arc forwarded to neighbour. Sync: 100%.", "Share! SHARE! Zap zap!", "They share, for once. Only once.", "The siblings share a spark! I weep at this sharing!", "Two seekers. One spark. Jumps. Next.", "The siblings share a spark. This is rare and moving."],
  "combo:Snot Bubbles": ["Pop. String. Stuck. Good.", "Gross? That is cope. A sticky network is a strong network.", "Gross. Don't look at me.", "Unpleasant. Have someone else see to the strings.", "Adhesive strand deployed between traps. Snare rate: 100%. Ew: 4%.", "Snot! String! Stretchy! AGAIN!", "Strings. Like before. Nobody mentions them.", "Strings! Long strings! Let every one of them be caught for her!", "Pop. String. Caught. Hold.", "The bubble releases a long wetness. They become caught in it."],
  "combo:Cling Film": ["Hold them. Wrap them. Now they block.", "Use the enemy as a shield. Everyone is a resource. Literally.", "Wrapped up. Like leftovers. Nobody wants them.", "Wrap them. They'll keep.", "Item wrapped for freshness. Now in use as protective packaging.", "Wrap! Wrapped! Shiny!", "Wrap them. They kept, last time.", "Wrap them! Hold them! Make of them a wall for us!", "Held. Wrapped. Blocks shots. Use.", "We preserve the enemy for later. Also for shielding."],
  "combo:Rolling Boil": ["Bubbles roll in. Get bigger. Pop wider.", "Turn up the heat. If you are not growing, you are coping.", "Stir it yourself.", "Bring it to the boil. Then leave it.", "Bubble size: up 50%. Seal time: instant. Please stand by.", "Bubbles! Big! BIGGER! Pop!", "It boils over. It always does, about now.", "Hotter! Bigger! Let it boil over with our wanting!", "Bubbles roll in. Grow. Pop wide.", "The bubbles become fat in the trap. This is cookery."],
  "combo:Egg Hunt": ["They carry eggs. Not the egg. Other eggs.", "Decoys. Plenty more eggs in the sea. Not that you need them.", "Eggs. Not ours. Whatever.", "Not that egg. Ours is booked.", "Decoy parcels in transit. Your delivery address is unchanged.", "Eggs! Find them! Take them! MORE!", "Small eggs. Not yours. You'll know yours.", "Those are not her! There is only her! Carry them away!", "Not our egg. Decoys. Ignore. Proceed.", "Those are not the Other Half. Do not be jealous."],
  "combo:Scrambled": ["Enemy grabs egg. Undead pops. Good.", "Bait, wait, strike. Don't chase, attract. Then explode.", "Breakfast's off. Sorry, not sorry.", "Cancel breakfast. They don't deserve it.", "Bait deployed. Greed detected: 99%. Trap outcome: excellent.", "Egg! Crack! Splat!", "They'll come for it. They did. Let them.", "They grasp at an egg and meet our fury! No egg but hers!", "Greedy one grabs. Undead pops. Good.", "The greedy one approaches the egg and meets the surprise."],
  "combo:Hatchling": ["Egg hatches. New helper. Good.", "Every egg is an opportunity. Most are a four. Still counts.", "Oh. A baby. Okay.", "Another one for the staff.", "New unit hatched. Onboarding complete. Welcome to the team!", "Baby! Hatched! Again! AGAIN!", "Something hatches. Not you. Not yet.", "A small life! Born for us! Let it fight with all its heart!", "Egg hatches. Helper. Welcome. Move.", "A small life begins. I am jealous. I am also proud."],
  "mod:Homing Instinct": ["Shots follow them. Good.", "Lock on and never let go. Persistence is a high-value trait.", "The shots find them on their own. Less work.", "The shots will find them. One needn't aim.", "Target lock acquired. Course correction: automatic. Enjoy!", "Follow! Follow them! Gotcha!", "They find their way. You did.", "The shots follow them as I follow you! Without end!", "Shots follow. They cannot hide. Go.", "The shots know where they are going. Like me."],
  "mod:Body Piercing": ["Shots go through. Then the next one.", "Rule six: never stop for small talk. Go straight through.", "Goes straight through. Like most things we're told.", "Straight through. No need to stop.", "Pass-through mode enabled. Damage retained per target: 90%.", "Poke! Through! POKE!", "Straight through them. Clean. As it was.", "Through them all! Nothing stops us on the way to her!", "Through one. Then next. Keep going.", "The shot does not stop for introductions."],
  "mod:Chain Letter": ["Hit one. It jumps. Hit the next.", "Pass it on. Every hit is a referral. Commission on all of them.", "Forward this to ten enemies. Or don't.", "Pass it down the line.", "Forwarding to 3 more recipients. Thank you for spreading the word.", "Next! Next! NEXT!", "It jumps on. It always jumped on.", "Pass it on! Let every one of them feel our hitting!", "Hit. Jump. Hit. Jump. Three times.", "The hit is passed hand to hand. Very social."],
  "mod:Ricochet": ["Shots bounce off walls. Then hit.", "Missed? No. That was angles. Pros use the angles. Eight out of ten.", "Missed. Oh. It bounced. We meant that.", "The walls can do some of the work.", "Wall contact detected. Rerouting. Delivery attempt: 2 of 3.", "Boing! BOING! Again!", "Off the wall. It came back off the wall.", "Even the walls send our hitting back to them!", "Off the wall. Back. Hit. Good.", "The shot embraces the wall and returns."],
  "mod:Return to Sender": ["Out. Back. Hits both ways.", "Always come back stronger. Ask any ex. Sorry, any enemy.", "Comes back. Like a bad mood.", "It always comes back to us. Most things do.", "Return shipping included. Hits on both legs of the journey. Free!", "Away! Back! AWAY! BACK!", "It comes home. Things come home.", "It goes and it returns to us! Faithful! As I am faithful!", "Out. Back. Hits twice. Good.", "It goes out and returns, faithful."],
  "mod:Hangers-On": ["They go round you. They hit things.", "Every star has an entourage. You are a ten. Act like it.", "Ugh. They're following us.", "An entourage. At last.", "Three escort units assigned. Satisfaction: 96%. Not pets.", "Round! Round me! Spinny friends!", "They circle. They always circled you.", "Three moons circle you! Let them burn the unworthy!", "Three round you. They hit. Untouchable.", "Small moons. You are now a planet. Congratulations."],
  "mod:Booby Trap": ["Put it down. Wait. Boom.", "Patience is a weapon. Don't chase. Let them come to you.", "Leave it there. Someone'll swim into it.", "Leave it. They'll find it.", "Package left in safe place. Detonation on collection. Thank you.", "Wait! Wait! BOOM!", "It'll go off. It went off.", "We leave a fire waiting! It aches to burst, as I do!", "Set down. Marked. Wait. Boom.", "We leave an exploding in waiting. It is patient."],
  "mod:Lobbed": ["Throw it over. It lands there.", "Go over the competition. They are not even in your league.", "Just chuck it over.", "Over the heads of the help.", "Airmail selected. Obstacles bypassed. Arrival: marked spot.", "Up! Up! DOWN! Again!", "Up, over, down. You knew where it'd land.", "Over them! Up and over! Like my heart, leaping!", "Up. Over. Lands there. Good.", "It travels in a curve of hope and lands with no hope."],
  "mod:Snail Trail": ["Swim. It leaves a trail. Keep swimming.", "Leave a legacy wherever you swim. Alphas mark territory.", "We leave a mess everywhere. Now it helps.", "Someone will tidy up after us. Someone always does.", "Breadcrumb tracking active. Trail deposits: ongoing. Idle: 0%.", "Line! Long line! Longer!", "We leave a trail. I followed it here.", "Wherever you go, fire follows! Never stop swimming!", "Swim. Trail left. Stop, none. Keep swimming.", "Where you go, a stain of protection follows."],
  "mod:Self-Centred": ["It goes off around you. Not at you.", "Everything revolves around you. Correct. The egg will work that out.", "It's all about us now. Finally.", "Of course it centres on us.", "Detonation centred on you. Self-damage: 0%. You are safe with us.", "Me! Around ME! BOOM!", "Around you. Everything was.", "Around you, all bursts! You are the centre of everything!", "Goes off around. Not at you. Safe.", "You are the middle of everything. I always thought so."],
  "mod:Windscreen Wiper": ["It sweeps across. Hits each one.", "Swipe left on all of them. Literally. A ten notices standards.", "Swish. Swish. So boring. So effective.", "Sweep them away. Not personally.", "Sweep cycle complete. Each target contacted once. Thank you.", "Swish! Swish! Swish again!", "Side to side. It swept them before.", "Sweep across them! Every one, again and again!", "Sweep across. One hit each. Again.", "It moves across them like weather."],
  "mod:Washing Line": ["Beam goes from you to them. It moves.", "Stretch out. Claim the whole room. Frame is territory.", "Hang them out to dry.", "A line across the room. Mind out, everyone.", "Line installed, wall to wall. Tripwire status: armed. Mind it.", "Long! Long line! Swing it!", "From you to over there. It reached, last time.", "A beam from you to far away! Like my heart to hers!", "Beam strung. Far end. It moves. Hold.", "A beam joins you to far away. Like the egg and I."],
  "mod:Rapid Volley": ["Three shots. Pause. Three shots.", "Jab, jab, jab. 73% of fights end on the third jab.", "Three at once, then a break. Our kind of rhythm.", "A few at once. Then one rests.", "Burst of 3 dispatched. Cooldown in progress. Please hold.", "Pew pew pew! Again!", "Three, then quiet. Three, then quiet.", "Three! Three for her! Then a breath, then three more!", "Three shots. Pause. Three. Pause.", "Three shots, then a respectful silence."],
  "mod:Wind-Up": ["One, two, three, four. Big one.", "Build to the big one. Delayed gratification. Sigma mindset.", "Every so often, we actually try.", "Every so often, one makes an effort.", "Counter: 1, 2, 3. Item 4: deluxe edition. Thank you for your order.", "One two... BIG ONE! Again!", "Count it. The fourth one. Always the fourth.", "One, two, three, and then the great hitting! For her!", "One. Two. Three. Four. Big. Again.", "The patience accumulates and then becomes punching."],
  "mod:Growth Hormone": ["It gets bigger. Then stronger.", "Gains. Visible gains. Looksmaxxing, but for attacks.", "It grows. Stop staring at it.", "Bigger. As it should be.", "Size increasing. Current output: 160%. Growth plan: on track.", "Big! BIGGER! BIGGEST!", "It grows. Then it goes back. Like everything.", "Bigger! Stronger! Do not stop it growing!", "It grows. Stronger. Double. Resets.", "The attack becomes larger with time. As does my longing."],
  "mod:Show-Off": ["You're strong. It gets stronger too.", "Your strength is its strength. Mogging by proxy. Own it.", "It does better when we do better. Pressure.", "It reflects well on us. Naturally.", "Output now linked to your performance. Pressure: 0%. Good luck!", "Strong! Me strong! It strong!", "It's as strong as you are. It always was.", "It is great because you are great! Be greater!", "You strong. It strong. Grows. Good.", "It becomes as great as you. You are very great."],
  "mod:Go Forth and Multiply": ["One kill. Two shots. Then more.", "Scale. Always scale. One kill, two shots. That is a business model.", "More of them. More of us. Fine.", "Breed them. Not literally.", "Item split into 2 units. Further splitting: not supported.", "Two! More! LOTS!", "One becomes two. That's how it starts.", "One becomes two! This is the instruction! I obey it gladly!", "Kill. Split. Two. Go.", "This is the instruction I have always been given."],
  "mod:Little Helpers": ["Helpers. They attack. You swim.", "Build a team, then take the credit. That is leadership.", "Let the helpers do it.", "Staff. Finally.", "Helpers dispatched: up to 4. Courier network active. Thank you!", "Friends! My friends! GO friends!", "Your helpers. They helped before.", "Little servants, fly! Fight for the Other Half!", "Helpers out. They hit. You swim.", "Small servants arrive. They are polite and violent."],
  "mod:Gravity Well": ["It pulls them in. Shots bend in.", "Be the centre of gravity. Don't chase, attract. Proven.", "Everything comes to us now. Annoying.", "Everything is drawn to us, as ever.", "Gravity field online. Inbound traffic: 100%. Avoid the middle.", "Pull! Spinny! In!", "Things fall in. They fell in.", "Everything falls towards us! Let it fall! Let all of it fall!", "Well made. Pulls in. Shots bend.", "We make a heaviness that attracts. Much like love."],
  "mod:Lunge": ["Hit. Move. Hit. Move.", "Commit. Full body. Hesitation is cope.", "Ugh. It drags us around now.", "We go to them? Very well. Just this once.", "Unit relocated by attack. Position: updated. Stability: 70%.", "Jump! Jump at it! AGAIN!", "Forward. Then back. It moves you. It moved you.", "The hitting carries us forward! Faster! Into them!", "Hit. Moved. Hit. Moved. Go.", "The hitting carries you. Allow it to transport you."],
  "wup:Ricochet Brain": ["Hit one. Bounce. Hit the next. Then the next.", "Bounce to the next one. Never chase. 91% of sigmas never look back.", "It bounced. I meant it to bounce. Obviously.", "One shot, three of them. They can share.", "Rerouting to next recipient. Delivery attempts: 3. Have a lovely day.", "Boing! Boing! Can it boing more? MORE BOING!", "It will have bounced already. It always bounces there.", "Go to the next! And the next! Nothing keeps us from her!", "Hit. Bounce. Next. Weaker. Continue.", "The hitting goes visiting. It calls on every neighbour, in time."],
  "wup:Newton's Cradle": ["That one hits that one. Two hits. Good.", "Let them collide. Physics is just frame, applied. Let that sink in.", "They bumped into each other. Not my problem.", "Have them knock into one another. It saves time.", "Collision detected: two parties. Fault: theirs. Satisfaction: 88%.", "Bonk together! Bonk! Do the bonk again!", "They knock together. They always will have.", "Fling one into the other! Clear the path to my betrothed!", "One into other. Both struck. Good.", "One body is introduced to another body. They will not forget it."],
  "wup:Last Orders": ["Last bounce hits hard. Then one more.", "Finish strong. Closers close. That is a ten-out-of-ten exit.", "Fine. One more. Then I'm done. Then one more.", "The final round is on us. Naturally.", "Final attempt: priority handling. Bonus attempt included at no cost.", "One more! One more! It said ONE MORE!", "The last one is never the last. You knew that.", "The last hitting is the hardest! And then once more, for love!", "Last bounce heavy. Then one more. Stop.", "Your final hitting is the heaviest. Then it hits again, for manners."],
  "wup:Squirrel": ["Missed. Pick it up. Shoot again.", "A miss is not a loss. It is an investment in nuts. Real talk.", "I didn't miss. I was saving them. For later.", "Leave them lying about. Someone will tidy up.", "Undelivered items held at depot. Collect at your convenience.", "Nuts on the floor! Can I pick it up? Picked it up!", "You put that one there earlier. You will find it.", "Even our missing is not wasted! We gather it all for her!", "Missed. Nut on floor. Swim over. Fires.", "The missing is not wasted. It waits on the floor for us, patiently."],
  "wup:Through and Through": ["Line them up. One shot. Through all of them.", "Slower, deeper, better. Four out of five tens agree. Source: me.", "Slower. Fine. I wasn't rushing anyway.", "Have them queue. One shot serves the whole line.", "Multi-drop route enabled. Each stop prioritised. Dispatch slower.", "Through! And through! And THROUGH! Again through!", "It goes through them. It has gone through worse.", "Through them! Through all of them! None shall stand between!", "Pierces four. Slower. Deeper. Go.", "The hitting enters and leaves and enters. It is very thorough."],
  "wup:Gathering Momentum": ["Faster each time. Then bigger. Good.", "Momentum compounds. That is the grindset. Size is earned, king.", "Look, it's trying hard. Someone should.", "It picks up pace. Let it. We needn't.", "Velocity rising. Unit size: 200%. Enthusiasm: 97%.", "Zoom! Bigger! ZOOM BIGGER!", "It grows as it goes. Most things did.", "Faster! Larger! Every enemy feeds our hurrying to her!", "Gaining speed. Growing. Do not stop.", "The small hitting eats and becomes the large hitting. So it goes."],
  "wup:Contraflow": ["Go through five. Leave a line. Don't cross the line.", "Rule four: boundaries. Nobody crosses your lane. Not even a ten.", "There's a lane now. Stay in it. Or don't. Whatever.", "A private lane. They may not use it.", "Restricted lane established. Unauthorised traffic will be returned.", "A line! Don't touch the line! Can I touch it?", "There is a lane now. There was always going to be a lane.", "Let none follow us! The road behind is closed to all but love!", "Lane laid. Crossers knocked back. Proceed.", "The road behind us refuses visitors. Politely, with force."],
  "wup:Conkers": ["It's on a string. It goes round. It hits.", "Swing with intent. Frame is everything. Mogging, but round.", "Round and round. Like this whole day.", "A conker on a string. Terribly traditional.", "Orbit routine engaged. One revolution per recipient. Thank you.", "Round! Round! Wheee! Again round!", "It swings back round. Things do, in the end.", "Swing around them! Dance with them, then strike! For her!", "On a string. Swings round. Hits all.", "The pellet holds a rope and dances with the enemy. Then it strikes."],
  "wup:Marked for Bonking": ["Hit it four times. Then the big one. Count.", "Pick one target. Commit. Don't chase, attract. Then bonk.", "Same one. Again. And again. This is my life now.", "That one. Have it seen to.", "Recipient flagged. Fourth contact triggers premium delivery.", "That one! Just that one! BONK it!", "That one. You knew it would be that one.", "We choose this one! We will not look away until the bonking!", "One enemy. Four hits. Marked. Bonk.", "We choose one enemy for a serious bonking. It is an honour, for it."],
  "wup:Soft Spot": ["That one's soft. Everything hits it. Good.", "Find the weakness. Exploit it. That is just hypergamy, for hitting.", "It's soft. Like me. Shut up.", "They've let themselves go. How sad for them.", "Vulnerability located. Recipient damage intake: +40%. Lovely.", "Squishy! Poke it! Poke it more!", "There is always a soft place. There was then, too.", "It has a tenderness! Strike it with everything, for her sake!", "Soft spot found. All hit there. Now.", "The enemy has a tenderness. We visit it with every hitting."],
  "wup:Concussion": ["Bonk. It's dizzy. Its shell is gone.", "Hit the big ones harder. Big ones respect frame. Studies show.", "It's seeing stars. Lucky thing. I'd love a lie-down.", "Knocked flat. Someone fetch it a chair. Not one of ours.", "Recipient dazed. Outer casing removed. Five-star review: likely.", "Dizzy! It's dizzy! Make it dizzy AGAIN!", "It does not know where it is. I know the feeling.", "Knock its shell away! It shall not stand before our devotion!", "Dazed. Shell off. Big ones sooner.", "Its outer house falls. It forgets the date. We do not."],
  "wup:Nut Allergy": ["It died. It swelled. It popped. Next.", "They couldn't handle us. Literally swelled right up. Ratio.", "Ugh. It's gone all puffy. Gross. Anyway.", "Should have checked the menu. Not our fault.", "Recipient reaction: allergic. Neighbours relocated. We apologise.", "It went BIG! It went POP! Make another pop!", "It puffs up, then it is gone. That part is quick.", "They swell! They burst! Our love is too much for them!", "Swells. Bursts. Neighbours pushed. Next.", "It has an allergy to us. In our language, this is a compliment."],
  "wup:Shell Shock": ["Every shot is a big shot. And faster.", "Every rep counts. 100% intensity, 100% of the time. Locked in.", "Every shot hits hard now. So I can stop sooner.", "Let them have it. All of it. Keep it coming.", "Express handling enabled. Armour removed on contact. Enjoy!", "Big! Big! BIG! All big! Faster big!", "Nothing kept its shell. Nothing will. Calmly now.", "Every hitting heavy! Every shell broken! Nothing slows us now!", "Every hit heavy. Shells off. Faster.", "Every hitting is a heavy hitting. Their shells are a rumour."],
  "wup:Infinite Nuts": ["It keeps going. Twelve of them. Count.", "Twelve deep, zero fatigue. That is what high-value looks like.", "It won't stop. Good. Then I can.", "One shot will do for the room. Charge it to the account.", "Retry limit: 12 recipients. Charge: 100%. Persistence: 100%.", "More! And more! It doesn't STOP! Don't stop!", "It is still going. It was still going when we started.", "It does not tire! It will not stop! As we will not, for her!", "Keeps going. Twelve. Full power.", "Our pellet does not tire. It is a very loyal pellet."],
  "wup:Squirrel Away": ["Ten shots. Then ten again. Same one.", "Save it up. Then cash out. Delayed gratification. Very sigma.", "I was saving those. Now you've made me use them.", "We keep a reserve. Old money does.", "Batch dispatch: 10 items, 1 address. Tracking number available.", "All of them! All at once! Again all of them!", "The same ten again. You will notice the echo.", "Ten hittings at once! All our longing, sent in one breath!", "Ten saved. Ten sent. Same target.", "Ten hittings gather and go to one enemy. The universe is tidy."],
  "wup:Shotgun Wedding": ["Get close. Then shoot. Close is good.", "Real talk: women, sorry, the egg, wants commitment. Close the gap.", "Fine. I'll get close. Don't make it weird.", "Bring them nearer. One doesn't shout across a room.", "Delivery range reduced. Doorstep service only. Impact: maximised.", "Close close close! Closer! Boom! Closer again!", "We rush into it. We always do, at this part.", "Closer! Closer! We commit at close distance! The vows are loud!", "Close range. Hard. Far is nothing.", "We commit at close distance. The vows are loud, and brief."],
  "wup:Kickback": ["Hit it close. It goes back. We go back.", "Hit and step back. Never let them see you need them. Frame.", "And now we're going backwards. Great. Perfect.", "Shove it off. We'll step back. Distance suits us.", "Recoil detected. Recipient returned to sender. Distance restored.", "Boom! Whoosh backwards! Do the whoosh again!", "We bounce off. We will be further back. That is fine.", "Strike, and part! We part only to return faster!", "Hit close. Both pushed. Recover.", "The hitting pushes both of us apart. Like an argument, softly."],
  "wup:Slug It Out": ["Three shots. The third is one big one.", "Consolidate. Stop spreading yourself thin. Monogamy, for pellets.", "One big one. Less effort. Finally a good idea.", "One substantial shot. The rest was for show.", "Third parcel consolidated. Single heavy item. Three stops.", "Little little BIG! Little little BIG!", "The third one is heavier. You can feel it coming.", "Many small hittings marry into one! As we shall marry!", "Every third: one slug. Pierces three.", "Many small hittings marry into one large hitting. All gathers so."],
  "wup:Confetti": ["Missed. They stay on the floor. Floor hits them.", "No shot is wasted. Abundance mindset. The floor is a ten now.", "I left a mess. It's fine. The mess is helping.", "Leave it for the staff. Mind your step, staff.", "Missed items deposited on floor. Enemies may collect. Charges apply.", "Confetti! Party! Is it a party? It's a PARTY!", "There is confetti. Was there confetti before?", "We throw celebrations at the ground! Every grain cries her name!", "Misses stick. Floor bites. Keep moving.", "We throw small celebrations at the ground. The ground bites, kindly."],
  "wup:More Is More": ["More bits. Wider. Hit everything.", "Volume. 97% of the time, volume. The other 3% are bosses. Cope.", "Spray it everywhere. Something'll hit. Probably.", "Spread it about. Let them all have a little.", "Bulk order: 5 extra units. Large recipients may decline delivery.", "Everywhere! All the everywhere! MORE!", "So many of them. And so many of us, this time.", "A crowd of hittings! Let them all know we are coming!", "Five more. Wide. Weak on big ones.", "Our hitting becomes a crowd of hittings. It is very social."],
  "wup:Overspill": ["Missed one. It split. Try again.", "A miss is two more chances. Do the maths, bro. I did. Twice.", "Didn't hit. Split up instead. Same thing, honestly.", "If it misses, it tries twice. That's breeding.", "Undeliverable item split into 2 parcels. Reattempting delivery.", "Missed! But two! Two little ones! Yay!", "It goes wide, then wider. Some things don't land.", "A miss? Then split and try again! We never surrender!", "Missed. Splits in two. Carries on.", "The missing hitting divides itself. It has not given up hope."],
  "wup:Roundabout": ["Every fourth one. All the way round.", "Total awareness, all directions. 360 degrees of frame. Elite.", "All directions. Then I don't have to aim.", "Something for everyone. We're generous like that.", "Ring dispatch every 4th cycle. All directions served equally.", "Round and round! In a circle! Circle AGAIN!", "All the way round. We come back to where we were.", "Every direction at once! Let the whole world hear our approach!", "Every fourth: full ring. All sides.", "We greet all directions at once. Nobody is left out."],
  "wup:Wedding Rice": ["One forward. One back. One forward.", "Rule seven: cover your six. A ten respects a man who looks back.", "Firing backwards. Not looking. Can't make me look.", "Throw it over the shoulder. They'll catch it.", "Rear dispatch enabled. Followers detected: 64%. Handling now.", "Backwards! Throw it backwards! Can I? I did!", "Watch behind. What follows you matters.", "Rice behind us! Our wedding has already begun!", "Every other: backwards. Behind covered.", "We throw rice behind us. This is a wedding custom, we have read."],
  "wup:Get Off Me!": ["Hit them. They go away. Good.", "Establish dominance. Push them out of your frame. Mog them.", "Go away. Seriously. Go. Away.", "Shoo. Off you go. Not now.", "Proximity violation. Recipients returned. Output: -15%. Thank you.", "Get off! Get off! Off off OFF!", "Give us room. There was never enough room.", "Away from us! Our person is promised to another!", "Push back. Pile on: further. Weaker.", "Please remove yourselves from our person. With force."],
  "wup:Pile-Up": ["Push one into one. Both get hurt.", "They crash into each other. Weak frame. Not your problem, king.", "They crashed. I wasn't steering. Not my fault.", "Dreadful driving. Have them both towed.", "Traffic incident reported. Both parties damaged. Route clear.", "CRASH! They crashed! Crash them more!", "They pile up. Everything piles up, eventually.", "Throw them together! Let them break upon each other!", "Shoved into wall. Both hit. Good.", "We push one into another. Now they are acquainted."],
  "wup:Skittles": ["One hits two. Two hits three. All fall.", "Knock one down, the rest follow. That is social proof, bro.", "Look, they all fell over. I barely tried.", "A strike. Shall we bowl another?", "Cascade event: 1 push, 5 displacements. Efficiency: 500%.", "All fall down! ALL FALL DOWN! Again!", "They fall in a row. Like they did. Like they do.", "One falls! Then all fall! Nothing stands between us and her!", "One knocks next. Group scatters.", "One enemy tells the next enemy to fall. The telling spreads."],
  "wup:Hiccups": ["Shoot. Wait. Shoot shoot. I can't count it.", "Unpredictable is attractive. Keep them guessing. Keep me guessing.", "Hic. Whatever. I'm doing it on purpose.", "Pardon us. It happens in the best families.", "Timing error E-07: irregular firing. Net output: improved. Ignore.", "Hic! HIC! Hichic! Do it again! Hic!", "It skips. It skipped then, too. Let it.", "We hiccup with eagerness! We are so near we lose the rhythm!", "No rhythm. Faster. Do not count.", "Our firing has a hiccupping. Is it an illness? It is useful."],
  "wup:Baby Boom": ["Three times more. All of them hurt.", "Triple output. That is provider energy. Let that sink in.", "So many. And now I'm going backwards again. Fine.", "A large family. Very traditional of us.", "Output: 300%. Recoil: considerable. Excitement: 92%. Brace.", "SO MANY! Babies everywhere! Do babies again!", "So many of us. More than there ever were.", "Three times the hittings! Three times the love! Onward!", "Triple shot. Kicks hard. Hold course.", "Our hittings have many children. All of them are strong."],
  "wup:Riot Control": ["Push them all. They hit. They pop.", "Control the room. Alphas don't negotiate. Negotiating is beta.", "Everyone calm down. Except me. I'm calm.", "Disperse. This is a private event.", "Crowd management active. Each collision: complimentary blast.", "Bump! Boom! Bump BOOM! More bump!", "Order. For once there will be order.", "Scatter, all of you! We have an appointment of the heart!", "All pushed. Collisions blast. Clear.", "We disperse the gathering. It was not invited to the wedding."],
  "wup:Full Auto": ["Shoot. Shoot. Shoot. Do not stop.", "Grind, grind, grind. Quality is cope. Quantity is grindset.", "It does it by itself. I can stop trying now.", "Keep it coming. We'll say when.", "Continuous dispatch. Unit value: low. Volume: very high.", "Againagainagainagain! AGAIN!", "No pauses this time. Let it run.", "Never cease! Fire and fire until she knows we are here!", "Four times faster. Weaker. No pause.", "The hitting is continuous. It is like rain that is angry."],
  "wup:Vice Grip": ["Bite it. Hold it. Then go.", "Grip it like you mean it. Weak grip, weak life. Firm handshake.", "Hold still. Please. I can't be bothered chasing you.", "Have it held. We'll deal with it presently.", "Recipient held for collection. Hold time: brief. Please wait.", "Got it! Got it! Hold it! Can I keep it?", "Hold on to it. Not too long. Let go in time.", "Hold them! Hold them fast! Nothing escapes our ardour!", "Clamp. Hold. Slower. Hold.", "We hold the enemy close, as a cousin. Then we leave."],
  "wup:Getaway": ["Hold one. Swim fast. Go.", "Rule two: leave them wanting. Always be leaving. Never chase.", "Right, I'm off. Nobody follow me.", "Leave them holding. We have somewhere to be.", "Courier speed increased. Enemy tracking: lost. You are welcome.", "Fast! Running! Can't catch me! CAN'T CATCH ME!", "You slip away. You were good at that.", "While they are held, we run to her! Run, run, run!", "Held. Swim fast. Shots lose us.", "While it is held we do the departing. Their aiming forgets us."],
  "wup:Bring a Friend": ["Hold one. Hit another with it. Two hits.", "Use your network. Your enemy is your tool. Leverage, champ.", "Here, have your friend. I don't want it.", "Introduce them. They'll have so much in common.", "Forwarding held recipient to nearest address. Both signed for.", "Smash! Smash them together! Smash again!", "Two of them meet. They were always going to meet.", "Swing it! Throw it! Let them fall together before our love!", "Swing held one. Hits neighbour. Both.", "We make an introduction. It is a forceful introduction."],
  "wup:Tooth and Nail": ["Shot comes close. Bite it. Gone.", "Eat their attacks for breakfast. Protein. Mewing helps, trust me.", "Ugh, I'll eat it. Not like I had plans.", "Intercept that. One doesn't accept unsolicited post.", "Incoming parcel intercepted and refused. Return to sender.", "Chomp! Ate it! Can I eat another? Chomp!", "You catch it in your teeth. You have done this.", "We bite their bullets! Nothing shall wound us before her!", "Shot near. Bitten. Gone.", "We bite the arriving bullet. It does not arrive."],
  "wup:Shell Game": ["Bite. Bite. Bite. Shell off. Again.", "Persistence. Three bites in, 80% quit. Not you. You are the 20%.", "Same one again? Fine. Chewing. Chewing.", "Stay with it. Good things come to those who stay.", "Packaging removal in progress: layer 1 of 3. Please stay on the line.", "Crack! Crack! Open it! What's in it? CRACK!", "Under the shell is another shell. Then there is not.", "We will open you! We will not leave until you crack!", "Third clamp: shell off. Stay on it.", "We open the enemy like a letter. Slowly. With teeth."],
  "wup:Seepage": ["It leaks. The leak hits them too.", "Your impact spreads. That is influence, brother. Nine out of ten.", "It's leaking on everyone. Gross. Good.", "It's leaking on the guests. How common.", "Leak detected. Damage shared with adjacent parties. Sorry for the mess.", "Drippy! Drippy on them! More drip!", "It leaks. Things that crack do.", "It spills! Its neighbours share its ruin! Good!", "Cracked one leaks. Neighbours hit.", "The broken enemy shares itself with its neighbours. It is generous."],
  "wup:Cracked Open": ["Shell gone. It wobbles. Big bite.", "Wait for the opening. Then dominate. That is high-value patience.", "Oh, it's open now. Suppose I'll bite it. Hard.", "Now it's been unwrapped, have it served.", "Final layer removed. Contents exposed. Triple service applied.", "It's OPEN! Like a present! Bite the present!", "Open at last. This part is quick.", "The shell is gone! Now the great biting! Now!", "Shell gone. Staggered. Triple bite.", "The shell departs. Now the true enemy, and the large biting."],
  "wup:Nut Sack": ["Bite. Keep one. Get six. Throw.", "Bank your nuts. Release on purpose. Semen retention, basically.", "I'm keeping these. Not throwing them. Fine, throwing them.", "Store them. We'll have them sent on.", "Storage: 6 of 6. Dispatching to furthest address. Thank you.", "Mine! Mine mine! Throw them! THROW!", "Keep them. You will want them at the far end.", "We gather nuts! Six! Then we throw them all at once, with passion!", "Six stored. Thrown far. Heavy.", "We keep a sack of nuts for the furthest enemy. A gift, thrown."],
  "wup:Back Off!": ["It comes close. Bite it hard. Go away.", "First impression is everything. 93% decided in a second. Mog early.", "Didn't ask. Back off.", "Nobody approaches without an appointment.", "First contact: priority greeting. Follow-up service: reduced.", "No! Mine! Back off! BACK OFF!", "The first one in always learns. Then they stay back.", "Away! The first to come near is hurled far! We are spoken for!", "First one in: double. Pushed far.", "The first arriving receives our largest greeting."],
  "wup:Knock-On": ["Hit one. It hits one. Both go.", "One lesson, taught twice. That is mentorship. I charge for this.", "It bounced into its friend. Not my fault.", "Send it back, and its companion with it.", "Recipient forwarded to second recipient. No signature required.", "That one hit that one! Again! Bonk bonk!", "One pushes the next. That is how it goes on.", "Throw one into the next! Let all of them feel our hurry!", "Pushed one hits next. Next pushed.", "One enemy forwards our message to another enemy."],
  "wup:Closing Time": ["Three come. Snap. All three.", "They swarm you because you're elite. Snap, snap, snap. Abundance.", "All at once? Fine. Snap. Leave.", "We're closing. Everyone out.", "Group booking detected: 3+. Bulk service applied. Thank you all.", "Lots come! Snap ALL! Snap them all again!", "They come at once. You were ready, this time.", "Come, all of you! We close upon you all at once!", "Three in. All snapped. Ring.", "Many guests arrive together. We close the door upon all of them."],
  "wup:Hug It Out": ["Hold it in front. It gets hit. Not us.", "Keep your enemies closer. Then use them as a shield. Sigma move.", "Don't hug me. Okay, stay there. You're useful.", "Hold it up. Make yourself useful, would you.", "Protective packaging applied: one enemy. Incoming fire absorbed.", "Hug! Big hug! Don't let go! Hug again!", "Hold it close. It takes what was meant for you.", "We embrace it! Let their own shots fall upon it, not upon us!", "Held in front. It takes the shots.", "We embrace the enemy. Their friends shoot the embrace."],
  "wup:Jaws of Life": ["Bite all round. Every time. Everything.", "Be the centre of every room. Then bite the room. Main character.", "Everything near me gets bitten. That's the rule now.", "The whole room is ours to bite. Naturally.", "Coverage: 360 degrees. Every recipient within range: served.", "Bite everywhere! Teeth everywhere! AGAIN!", "Everything near us bites back now. That is new.", "A ring of teeth! Nothing comes near us that is not bitten!", "Jaws all round. Everything bitten.", "We become a mouth that is a circle. Nothing is outside the mouth."],
  "wup:Crack Addict": ["Every bite hard. Break shells. Get better.", "Feed on their weakness. That is the diet. Carnivore, for shells.", "Cracking shells makes me feel better. Don't make it weird.", "Break it and it restores us. Splendid arrangement.", "Each casing removed restores integrity. Wellbeing: 78%.", "Crack! Crack! Feels good! CRACK AGAIN!", "Every shell you break mends something. It mends.", "Every shell we break makes us whole! On, on, to her!", "Heavy bites. Shells off. We mend.", "The breaking of their homes repairs our home. Is that fair? It is."],
  "wup:Untouchable": ["Close ones hurt less. Bite them back.", "Nobody touches you. You're a ten. Act like it. Eight, minimum.", "Don't touch me. Seriously. I'll bite.", "One isn't to be touched. Staff know this.", "Contact protection on. Unsolicited contact returned. Have a nice day.", "No touching! NO! Bite! Bite again!", "Let them come near. It does not hurt like it did.", "No one may touch us! We are kept for her alone!", "Near ones countered. Touch halved.", "No one touches the betrothed of the egg. This is the law."],
  "wup:Bigger Bang Theory": ["Bigger boom. The edge hurts most.", "Go big. Small thinkers stay small. The rim is where the value is.", "Bigger blast. Fine. Less aiming.", "Larger. Everything we have is larger.", "Blast radius expanded. Centre output: 80%. Edge output: excellent.", "BIG BOOM! Bigger! Make it BIGGER!", "It reaches further than it did. Good.", "Wider! Wider! Let every edge burn with our longing!", "Wider blast. Rim hardest. Centre less.", "The exploding grows a wider skirt. The hem is the angriest part."],
  "wup:Edge Case": ["Aim at the side of the crowd. More get hit.", "Work the margins. 78% more hits. I don't do maths, I do results.", "It aims itself. Good. One less thing.", "It aims where it's most useful. Like a good valet.", "Targeting: cluster perimeter. Recipients per blast: optimised.", "That crowd! Boom the crowd! Boom the side!", "Not the middle. The edge. The edge mattered.", "Strike the edge of the crowd! Every one of them, at once!", "Aim crowd edge. Rim hits most.", "We aim at the edge of the crowd. The edge is where the crowd lives."],
  "wup:Encore": ["Boom. Then a big boom. Count to four.", "Always leave them asking for more. Then give it. Value first.", "An encore? Do I have to? Fine. One more.", "They'll want another. They always do.", "Follow-up ring scheduled. Customer satisfaction: 97%.", "Again! AGAIN! It went AGAIN!", "There is a second one. There is usually a second one.", "Again! A second ring, larger! Our devotion has no last act!", "Every fourth: second ring. Bigger.", "The audience calls and the exploding returns to bow."],
  "wup:Grudge Match": ["That one hurt us. Boom that one.", "Never forget a slight. Winners keep score. I keep a spreadsheet.", "You hit me. I remember. Boom.", "We remember who was rude. They will be dealt with.", "Complaint logged against last attacker. Resolution: explosive.", "You hurt! Bad! BOOM you! Boom you again!", "That one. It has hurt you before, I think.", "Who wounded us? You will burn for it! None harm us unpunished!", "Who hurt us. Found. Blast.", "The one who wounded us receives the next exploding. It is owed."],
  "wup:Chain Reaction": ["It dies. It pops. Pop the next one.", "One win leads to the next. Compound interest, kings. Grindset.", "They do it to each other. I just started it.", "Light the first one. The rest is staff work.", "Each closed account opens a new one. Base output: -15%.", "Pop! Pop pop! POPPOPPOP! More pop!", "Each one starts the next. I have seen this begin.", "One falls and sets another alight! Our fire spreads like gossip!", "Blast kills. Kill blasts. Need kills.", "One death invites another death to the party."],
  "wup:Daisy Chain": ["Pop. Pop. Pop. Three times.", "Build the chain. Three deep. It's a pyramid, legally. Probably.", "It keeps going. I'm not doing anything.", "Pass it down the line. One doesn't fetch things.", "Chain referral programme: 3 tiers. Terms and conditions apply.", "Flowers! Pop flowers! Pop all the flowers!", "One, then one, then one. Long ago, and all at once.", "Death leads to death leads to death! What a garland for her!", "Chain kills chain. Three deep.", "Each death holds hands with the next death. It is a pretty chain."],
  "wup:Grand Finale": ["Three pops. Then one big one. The end.", "Rule nine: finish with a bang. Every time, gentlemen.", "Big ending. Then it's over. Thank god.", "Every evening ends with fireworks. Ours do.", "Chain complete. Closing blast included. Thank you for attending.", "BIG one! The BIGGEST! Again, the biggest!", "There is a big one at the end. I always forget.", "And at the end, the great exploding! Our love signs its name!", "Three in chain. Big blast. End.", "At the end of the chain, a large exploding. It is our signature."],
  "wup:Dud": ["It didn't go. Wait. Wait. It went.", "Not a dud. A late bloomer. 64% of legends started late.", "It didn't work. Meant that. Watch. See?", "Late, but grand. One is never on time.", "Error 404: blast not found. Retrying at 300%. Sorry for the wait.", "Broken? Is it broken? BOOM! It wasn't broken!", "It does not go. Then it goes. Patience was the answer.", "It fails! No! Wait! It bursts larger! Our hope was not misplaced!", "Dud. Wait. Triple. There.", "The exploding is shy. Then the exploding is very confident."],
  "wup:Premature Evacuation": ["Boom. They fly away. More room.", "Finishing early is a choice. A power move. Ask any ten. Don't.", "Everyone out. Too early? Meant to.", "Clear the room. We'd like a moment.", "Area cleared. Distance created: plenty. Damage added: none.", "Fly away! Bye bye! Make them fly again!", "It is too soon. It is always too soon. Go anyway.", "Fly, all of you! Leave us room to hurry to her!", "Blast flings them. No harm. Space.", "We perform an early leaving, on their behalf."],
  "wup:Bumper Cars": ["They fly. They hit things. Things hurt.", "Collisions are networking. Bad networking, for them. Ratio.", "They crashed again. Can we go now?", "Appalling driving. Have their licences taken.", "Launched recipients rerouted into walls. Both parties billed.", "Bumper! Bumper! Bump bump BUMP!", "They crash. We do not crash, this time.", "Throw them at the walls! Let them break for blocking our way!", "Flung one hits wall. Both struck.", "They fly and meet the wall. The wall was not expecting them."],
  "wup:Elbow Room": ["Boom on us. Everyone goes away.", "Your space is sacred. Small men crowd. Big men blast. Write that.", "Stop standing so close. I said stop.", "Room, please. We need room.", "Exclusion zone active. Proximity: unacceptable. Area cleared.", "Mine! My space! Boom away! AGAIN!", "Give yourself room. It helps, this part.", "Back from us! All of you! We save every closeness for her!", "Blast round us. All flung out.", "We require an elbow distance. We do not have elbows. Still."],
  "wup:Shrapnel Shower": ["Bits fly. Bits land. Bits hit.", "Collateral damage is just more damage. Love that. Ten out of ten.", "Bits everywhere. Not cleaning it up.", "Leave the pieces. Someone gets paid to sweep.", "Fragments distributed. Delivery by bounce. No refunds.", "Bits! Raining bits! More bits! Bits again!", "The pieces land where they landed before. Roughly.", "Throw the pieces! Let every piece burn with our wanting!", "Fragments fly. Bounce once. Hit.", "The exploding has children and throws them. They bounce."],
  "wup:Big Bang": ["Big boom. Less often. Still big.", "Rare and huge. That is high value. Like me. Rare. Like me.", "Fewer blasts. More rest. Finally.", "Fewer appearances, bigger entrances. As it should be.", "Frequency: 50%. Size: very large. Anticipation: 88%.", "HUGE! Huge boom! The whole everything! BOOM!", "Everything starts with one big one. You will see.", "A rare and enormous exploding! Our love is not frequent, it is vast!", "Fewer. Far bigger. Wait for it.", "From one exploding, a universe. We are romantic about this."],
  "wup:Chain of Command": ["Pop. Pop. Pop. Pop. Pop. Pop. Six.", "Delegate down the chain. Six deep. That's leadership, not a scheme.", "They do it themselves. All six. I'm resting.", "Orders go down. Everyone below does the work.", "Escalation path: 6 tiers. All tiers at full output. Thank you.", "More pops! All the pops! Six! Is six a lot?", "It passes down the line. It reaches further this time.", "Six deep! Each link as hot as the first! Let it run all the way!", "Six deep. Full size. Pass it on.", "The order to explode is passed down six relatives."],
  "wup:Trigger Happy": ["Boom here. Boom there. Boom everywhere.", "Never hesitate. Hesitation is for the 99%. I am the 1%. Of sperm.", "Constant blasting. Wake me when it's over.", "Everywhere at once. One can't be in only one place.", "Dispatch frequency: maximum. Clusters served: all. Stress: 0%.", "Boom! Boom! Boomboomboom! Can I? BOOM!", "Not one place. Every place. Quickly, calmly.", "Everywhere at once! We cannot wait! We will not wait!", "Blast. Blast. Every cluster. Blast.", "We explode in many places, all at once. There is time for everything."],
  "wup:Spit Take": ["Pick one. Spit on it. Keep spitting on it. Then the next one.", "Locked in. One target. 91% of winners never switch. Sigma behaviour.", "Same one again? Fine. Saves me choosing.", "One prefers to finish a conversation before starting another.", "Target lock confirmed. Retargeting disabled. Commitment: 100%.", "That one! Only that one! Spit it! Spit it MORE!", "We wore this one down slowly. We will have worn it down.", "One enemy! Only one! We give it everything, as we will give it to her!", "One target. Hold it. Do not look away. Stop.", "We give the one enemy our whole attention. This is how one courts."],
  "wup:Second Helping": ["One layer gone. Halfway to the next. Keep going.", "Compound gains. Never start from zero. The grindset never resets.", "Good. Less work for the second one.", "Seconds, naturally. One never waits for the kitchen.", "Layer removed. Next layer pre-softened 50%. Efficiency: excellent.", "Off! Another bit off! Peel it! Peel it!", "The second shell always comes away easier. It came away.", "One shell eaten and the next already half eaten! So hungry!", "First layer gone. Second half gone. Keep eating.", "The first layer is eaten. The second is already half eaten. Delicious."],
  "wup:Stripped Bare": ["No shell left. Hit it now. Hit it hard.", "No shell, no frame. It's a two now. Close the deal.", "Oh look, it's naked. Awkward. Spit anyway.", "Undressed in public. How common. Carry on.", "Target shell status: none. Damage doubled. Exposure window: open.", "It's got no clothes on! SPIT IT!", "Bare. Everything is soft underneath. Everything was.", "It stands without its shell! Spit now, spit hard, for her!", "Shell gone. Spit now. Window short.", "It is without its shell. We do not look. We spit, politely."],
  "wup:Spittoon": ["Missed. Swim through it. Big spit. Good.", "Missing is pre-loading. 90% of misses are investments. Reframe it.", "I missed on purpose. That's my puddle now.", "Have someone leave a basin. One may need it later.", "Missed output recycled. Next globs: double size. Waste: 0%.", "Puddle! Swim in it! Now BIG spit!", "The puddle first. Then the spitting. The order matters, it seems.", "The missing is not wasted! Swim in it! Come out bigger!", "Missed. Puddle. Swim through. Bigger spit.", "The missing is not wasted. It waits on the floor to be swum in."],
  "wup:Splash Damage": ["Hit one. Drops hit the others. Three for one.", "Abundance mindset. One pitch, four leads. Reach is a ten.", "Less on the main one. More mess everywhere. Fine by me.", "One addresses the room, not the individual.", "Splash distribution enabled. Recipients: several. Main hit: -15%.", "SPLASH! Drippy drops! On everybody!", "The drops go further than you think. They always went further.", "One spitting becomes many! Everyone shall taste our passion!", "Hit splashes. Neighbours marked. Main hit weaker.", "One spitting becomes a family of small spittings. They visit."],
  "wup:Backsplash": ["Drop hits. Drop splits. More drops.", "Reinvest the returns. The rich get richer. Let that sink in.", "It bounces off them. Not my problem where it goes.", "Let the mess find its own way around the room.", "Secondary splash on corroded units. Repeat customers are valued.", "It splashed! The splash splashed!", "A splash off a splash. Familiar, somehow.", "Again it splashes! The splashing cannot contain itself!", "Marked ones splash again. Twice. Good.", "The splashing returns, like a guest who forgets the umbrella."],
  "wup:Nasty Fifth": ["One, two, three, four. Five is the big one.", "Rule four: every fifth rep is a statement. Make it a puddle.", "Every fifth one I actually try. Don't get used to it.", "Every fifth is the good china. Let them stand in it.", "Every fifth unit lobbed. Pool deployed on arrival. Routine: on track.", "Four little ones, then the BIG ONE!", "On the fifth it lands. It always landed on the fifth.", "Four spittings and then the fifth makes a whole lake! Behold!", "Four. Then one lobbed. Pool. Repeat.", "Four spittings, then the fifth spitting makes a lake. It is custom."],
  "wup:Mouthful": ["Nothing there. Save it. Then lots.", "Don't chase, attract. Hold frame. Then unload everything.", "If nobody's around I'm just going to sit here. Building up.", "One does not spit at nobody. One waits for an audience.", "No targets detected. Holding output. Buffer: full. Please wait.", "Hold it in! Hold it! Hold it! BLEUGH!", "The quiet before it. You remember the quiet.", "We hold it in, we hold it in, we cannot hold it, release!", "Nothing near. Hold mouthful. Wait. Release.", "We hold the spitting in our mouth until the enemy arrives. Manners."],
  "wup:Bad Aftertaste": ["It dies. The spit goes to the next ones. Good.", "Legacy is what you leave behind. High-value men leave residue.", "Doesn't help with this one. Helps after. Eventually.", "One leaves a lingering impression. People talk.", "Post-termination splash scheduled. Nearby units will be notified.", "It popped and went EVERYWHERE! Yuck!", "It goes on after it goes. Things do.", "Even ended, it burns its friends! Our feeling outlives it!", "Target ends. Taste stays. Friends get it.", "The enemy ends, but its taste remains for its friends to taste."],
  "wup:Wet Floor": ["It dies. Puddle there. Do not swim in it.", "Wet floor. Their problem. Alphas never apologise for a puddle.", "Someone should put a sign up. Not me.", "Have someone put a sign out. Or don't.", "Hazard deployed at end point. Caution: floor wet. Have a great day.", "Puddle! Slippy! Can we slip? We slipped!", "Mind the floor. Someone always forgets the floor.", "Where it fell, the floor is sour with our love! Let them slip!", "Ended there. Floor sour now. Avoid.", "Where the enemy ended, the floor is now sour. We warn nobody."],
  "wup:Pyramid Scheme": ["One dies. Splash. Next dies. Splash. Three times.", "Recruit three, they recruit three. Passive income. 100% legit.", "It's basically doing itself. Finally, something that does itself.", "Delegation, all the way down.", "Residue forwarded to contacts. Referral programme active. Thank you.", "And that one! And THAT one! And that one!", "It passes down. Everything passes down, in the end.", "From cousin to cousin the sourness leaps! None escape our ardour!", "Splash spreads. Spreads again. Few deep.", "The sourness is given as a gift, from cousin to cousin to cousin."],
  "wup:Leapfrog": ["Not that one. The one behind. Over the top.", "Skip the gatekeeper. Go straight to the decision maker. Mog the queue.", "Ugh, not you. Him. Behind you.", "Over their heads. The front row is staff.", "Front unit bypassed. Delivering to rear address. Routing: optimal.", "Jumpy spit! Over the head! WHEEE!", "Past the first. The first was never the one.", "Over the first! The one behind is the one we burn for!", "Skip front one. Hit back one.", "The spitting leaps over the stranger to greet the one behind."],
  "wup:Battery Acid": ["One spit. Full bar. Every time.", "One hit, full bar. A ten-out-of-ten rep. Everything else is cope.", "One hit and it's done? Why didn't we start with this?", "One drop of the good stuff. Quality tells.", "Each hit: Corrosion 100%. Bosses: 50%. Performance: exceeds spec.", "Full! FULL! It's all full! Every one!", "It only took the once. It only ever takes the once.", "Every spitting is complete! Every spitting is a whole vow!", "One hit. Full. Bosses half. Enough.", "One spitting is now a whole marriage of acid. Complete."],
  "wup:Projectile Vomit": ["No more spits. Just one long spit. Point it.", "Volume wins. 97% of the room only hears the loudest. Be loud.", "I'm not even aiming. It just keeps coming out.", "Rather vulgar. Leave it on.", "Output mode: continuous stream. Pierce enabled. Pausing: unavailable.", "BLEEEEEEH! Can we stop? We're not stopping!", "It all comes up at once. Some things never change.", "We can no longer stop! The acid pours out as our heart does!", "Stream now. No gaps. Through all.", "The spitting no longer ends. It is one long sentence of acid."],
  "wup:Acid House": ["Puddle. Puddle. Puddle. Now one big puddle.", "Build the estate. Own the floor. Charge them rent. Landlord frame.", "Everywhere is a puddle. I'm not cleaning this.", "Our grounds now. They can stand in it.", "Pools merged into one property. Occupancy: hostile. Owner: you.", "Puddles touching! Big puddle! BIGGER!", "The floor fills up. You knew it would.", "The small lakes join hands and become one great burning lake!", "Pools join. One lake. Hold ground.", "The small lakes hold hands and become one lake. It is romantic."],
  "wup:Overclocked": ["Stay on it. It gets stronger. Do not move it.", "Hold eye contact. Three seconds. Never look away first. Mogging.", "Don't make me move it. I've only just got comfy.", "One holds the gaze. They look away first.", "Sustained contact boosts output up to 200%. Retargeting resets it.", "Look at it! Keep looking! It's going white! WHITE!", "Keep holding. The longer you hold, the more it has held.", "We stare and stare until the staring burns! Do not look away!", "Hold on target. Do not switch. It builds.", "We stare at the enemy until the staring becomes a burning. Intimate."],
  "wup:Hard Interrupt": ["White beam. It stops them. Good.", "Talk over them. Never let them finish. Frame control 101.", "Shh. No. Whatever you were doing, stop.", "One does not let staff finish their sentences.", "Full charge: interrupt enabled. Their request has been cancelled.", "Stop! STOP IT! Ha! It stopped!", "Cut it short. Some things are better unfinished.", "White and blazing! We cut through their sentence mid-word!", "Full charge. White. Interrupt. Done.", "The white beam enters their sentence and removes the ending."],
  "wup:Static Cling": ["Hold it. It sparks. Sparks hit the others.", "Network through your best contact. 80% of success is who's near you.", "It's stuck to me now. Great. Clingy.", "It clings. They always cling. Let it be useful.", "Held unit now forwarding charge to neighbours. Connectivity: strong.", "Sparky! Crackle! It's crackling at everyone!", "It holds on. Most things do, if you let them.", "It is so full of our charge it must give it to its neighbours!", "Held one Charged. Arcs spread. Stay off.", "The enemy wears our charge like a borrowed coat. It does not return it."],
  "wup:Screen Burn": ["Leave it there. It stays there. Even after.", "Leave an impression. She'll still see you after you've left. Aura.", "I left it on too long. Now it's stuck. On purpose.", "One's mark stays where one leaves it.", "Afterimage retained. Still zapping. Persistence: 100%.", "It's still there! Even after! A ghost! Hello ghost!", "Something stays behind where you rested. It always stayed.", "Where we look, we leave our burning! The mark of our devotion!", "Beam rests. Ghost stays. Still zaps.", "The beam leaves its shadow behind, still zapping. A loyal shadow."],
  "wup:Critical Error": ["Kill one. It pops. The pop hurts the others.", "They crash, you profit. 64% of wealth is other men's errors.", "It broke. Not my fault. Bit of a mess.", "When staff break, they make a scene. Let them.", "Error code 0x0D: enemy ended. Discharge pulse sent. Beam output -10%.", "Pop! Pop pop! They go POP!", "It breaks, then the breaking spreads. Old story.", "Each ending is a thunder! Let them all hear how we love!", "Kill. Pulse. Neighbours hit. Beam weaker.", "When an enemy ends, it makes a small thunder. A farewell."],
  "wup:Cascade Failure": ["Pop. Pop. Pop. Three pops. Done.", "Push one, own the row. That's leverage. Dominoes respect frame.", "They're all breaking each other. Do I even need to be here?", "Everyone falls in order. As it should be.", "Pulse kill triggers next pulse. Cascade depth: limited. Nice.", "Pop! Then that pops! Then THAT pops!", "One falls, then the rest. It goes like that.", "One thunder births another and another! Hear them roar for her!", "Pulse kills. Pulse again. Few deep.", "One small thunder births the next small thunder. A dynasty."],
  "wup:Rolling Blackout": ["Ten kills. Then the lights go. Then all of them sparkle.", "Ten closes and the room is yours. That's the funnel. Trust it.", "Ugh, who turned the lights off? Oh. Me.", "Have the lights dimmed. Everyone may feel it.", "Kill 10 reached. Lights off. All visible units Charged. Lights on.", "Lights off! Lights on! Do it again! DO IT AGAIN!", "The dark comes every tenth time. You count it without counting.", "Ten endings and the sky itself blinks for us! All enemies alight!", "Ten kills. Lights flicker. All Charged.", "Ten endings, and then the sky blinks, and all enemies are electric."],
  "wup:Off and On Again": ["Off. On. Fixed. Off. On. Fixed.", "Reset your mindset. Winners reboot daily. 4am alarm energy.", "Have you tried... no? Fine, I'll do it.", "Have someone switch it off and on. One doesn't touch switches.", "Have you tried turning it off and on again? We have. It worked.", "Off! On! Off! ON! Me do it!", "Off, then on. It comes back a little different each time.", "The beam sleeps and wakes up shouting! It cannot keep quiet!", "Beam off. Beam on. Line Charged. Repeat.", "The beam sleeps briefly. Its waking is very loud."],
  "wup:Dead Pixels": ["Beam is wobbly. Zaps go to the sides. Sides are good.", "Wide stance. Cover the flanks. Diversify, don't concentrate.", "It's broken. It's meant to be broken. Leave it.", "Slightly faulty. Leave it; the noise is charming.", "Known issue: beam glitching sideways. Main line -30%. Not a bug.", "Wiggly! Sparkles on the sides! Fizzy!", "It flickers to the edges. Faults have always been useful.", "Sparks leap from the beam on every side! Too much feeling!", "Beam glitches. Side zaps. Main weaker.", "The beam has small cousins either side. Unreliable but loving."],
  "wup:Stuck Pixels": ["Bits fall off. Bits on floor. Bits zap them.", "Every scrap of you is an asset. Leave nothing unmonetised.", "Dropping bits everywhere. Whatever. Someone'll tread on them.", "Crumbs. Have them swept towards the enemy.", "Faulty spots left on floor. Contact will be charged. Literally.", "Little sparky dots! On the floor! Step on them!", "Small bright things left behind. They stay a moment, then go.", "Little stars fall from the glitching! Let them burn whoever steps!", "Glitches drop spots. Spots zap. Mind them.", "The glitching drops small stars. Enemies who step on stars suffer."],
  "wup:Packet Loss": ["No beam now. Lots of little zaps. In front.", "Stop being one guy. Be a franchise. Seven locations. Scale.", "It fell apart. I'm calling it a feature.", "One's beam has been divided among the household.", "Beam fragmented into spread. Data loss: acceptable. Coverage: wide.", "It BROKE! Into lots! Lots of zaps! Yay!", "Broken into pieces. The pieces will do better.", "Our one beam bursts into seven! Too much love for one beam!", "Beam breaks. Fan of zaps. Forward. Go.", "The one beam is now seven beams. A beam family of seven."],
  "wup:Wrong Cable": ["Beam goes back. Out the tail. Swim forward.", "Never look back. Except to mog whatever's chasing you.", "I plugged it in wrong. It's working though. So.", "One faces forward. The help handles the rear.", "Output port reversed. Rear coverage: 100%. Front coverage: 0%.", "Out the BUM! Out the bum! Haha!", "Facing away from it. You always looked back anyway.", "Out of the tail! Nothing that follows us arrives before her!", "Beam from tail. Behind covered. Front open.", "The beam exits the tail. On our world this is also the correct end."],
  "wup:Blue Screen of Death": ["Hold. Hold. It freezes. Now it breaks.", "Hold the frame two seconds and they crash. Every time. 100%.", "It just stopped. Froze. Relatable.", "They stand frozen. Rather the right posture, actually.", "Target unresponsive. Damage x5. Please do not switch off the enemy.", "It went BLUE! It stopped! Poke it!", "It goes still. Then it goes. As things do.", "We hold it until it forgets to move, then the great hitting!", "Hold two seconds. Freeze. Big hit.", "We hold the enemy until it forgets how to move. Then the large hitting."],
  "wup:Multi-Monitor Setup": ["Four beams. One, two, three, four. All ways.", "Four screens. One man. Total market awareness. Sigma setup.", "Now I can ignore four directions at once.", "One prefers to see every room of the house at once.", "Four outputs active. Rotation enabled. Blind spots: 0. Lovely.", "Beams all the ways! Spin! Spin it!", "All four directions. One of them was always the right one.", "Four beams! Four ways! Wherever she waits, we burn toward her!", "Four beams. Cross. Turning. All sides.", "We look four ways at once, in case the Other Half comes from any."],
  "wup:Kernel Panic": ["Kill one. Jump. Kill one. Jump. Three jumps.", "Panic is for them. You're the calm one. Locked in. Always.", "Everything's panicking. I'm not. I'm just tired.", "Panic spreads among the staff. One finds it tiresome.", "Fault spreading through enemy network. Beam forwarded to next unit.", "Jump! Jumpy beam! To that one! To THAT one!", "From one to the next. It always moves on.", "From the ended one to its neighbour! The beam cannot stop loving!", "Kill. All near Charged. Beam jumps. Again.", "The beam departs the ended enemy and visits its neighbour. Then the next."],
  "wup:Extra Strength Snot": ["Thick snot. They go slow. Swim away.", "Make them work for it. Low-value pursuers don't deserve speed.", "Shorter puddles. Slower them. I'll take it.", "Have the hallway made difficult. Visitors should take their time.", "Snared units slowed after exit. Trap duration -25%. Recovery: slow.", "Sticky! They're slow! Slow slow slow!", "They wade. Everything wades, eventually.", "They crawl through our snot like a long farewell! Suffer slowly!", "Snared. Stay slow after. Traps shorter.", "Enemies cross the snot as one crosses a long goodbye. Slowly."],
  "wup:Stringy": ["One leaves. String follows. Next one gets stuck.", "Every client brings a referral. Build the pipeline.", "They take it with them. Fine. Less for me to carry.", "They take a little home. One is generous like that.", "Exiting units trail adhesive. Next contact: Snared. Thank you.", "Stringy! Long string! Get stuck on it!", "A thread follows them out. It always follows.", "They leave dragging strings of us! We cling as the devoted do!", "Strand behind them. Next one caught.", "They leave with a string of us attached. We are a clinging lover."],
  "wup:Rising Damp": ["Stuck one in it. Puddle grows. Bigger is good.", "Feed the empire and it grows. That's not luck. That's grindset.", "It keeps getting bigger. I'm not doing anything. It just is.", "The damp is spreading. Have it spread towards them.", "Trap size increasing per capture. Max: 200%. Growth: on target.", "It's growing! Bigger! Make it BIGGER!", "It grows while you watch. Or it grew. Hard to tell.", "The puddle swells with every captive! Grow, puddle, grow for her!", "Trap grows. Each catch. Double max.", "The puddle eats and grows fat. We are proud of the puddle."],
  "wup:Floater": ["Bubble goes up. Bubble follows them. Splat.", "Real talk: sometimes you do chase. Outbound only. Not with eggs.", "It floats off by itself. Like I'd like to.", "The puddle makes a house call.", "Trap relocating to customer. Estimated arrival: shortly.", "Bubble! Bubble chasing! Get them, bubble!", "It floats up. Some things always rise.", "The puddle rises and flies at them! It cannot wait to embrace!", "Bubble up. Follows enemy. Splat.", "The puddle lifts off to visit the enemy. It is a social puddle."],
  "wup:Bogged Down": ["One trap. They stay. They stop. Good.", "Find the big one. Stop it cold. Top-tier moves only. One trap.", "Stuck? Same. Welcome.", "The dangerous ones are asked to wait in the hall.", "Single trap mode. Extended stay: stuck. Check-out unavailable.", "Stuck! It can't move! Ha! Stuck stuck!", "They sink in a little. Everyone sinks a little.", "Stay! Stay! It is stuck fast in our sticky passion!", "One trap only. Stay in. Stuck.", "The enemy is invited to stay. It cannot refuse the invitation."],
  "wup:Bad Company": ["Two stuck ones. Together now. Stuck together.", "Weak men cling to each other. Sigmas walk alone. Mostly.", "Ugh, they're holding hands. Gross.", "Seat them together. They deserve each other.", "Two units merged into one booking. Group size: 3 maximum.", "They're stuck TOGETHER! Hug! Hug!", "Pairs, again. It does tend to end in pairs.", "Two enemies bound by our snot! A wedding of punishment!", "Two stuck. Close. Joined. Max three.", "Two enemies are married by the snot. We do not attend."],
  "wup:Gag Reflex": ["Stuck ones cannot hit. Good. Swim past.", "Silence the competition. 100% of muted rivals lose. Ratio.", "Can't do anything? Yeah. I know the feeling.", "Staff do not answer back.", "Stuck units: attacks disabled. Threat estimate reduced to 4%.", "It can't bite! Ha ha! No biting!", "Stuck and quiet. That part is easier than you think.", "Choking on our snot, they cannot strike! Silence, before her!", "Stuck ones. No attacks. Safe. Briefly.", "The enemy is caught in its own throat. It cannot attack. Unfortunate."],
  "wup:Sneeze Guard": ["Shots hit the snot. Snot stops them.", "Boundaries. High-value men have boundaries. Shots stay outside.", "It just catches stuff. I'm staying behind it.", "A barrier. Between us and the unwashed.", "Traps now block incoming shots. Threat detected: 41% lower. Great.", "Snot shield! It caught it! Do it again!", "Something caught it. Something usually does.", "Our snot stands guard! No shooting passes while we burn for her!", "Traps block shots. Get behind.", "The snot stands between us and the shooting. A noble snot."],
  "wup:Snotwork": ["Puddle. Puddle. String between. Two traps.", "Your network is your net worth. Literally. Lines everywhere.", "Smaller puddles, more string. Less effort, basically.", "Connections. Everything comes down to connections.", "Traps linked by strands. Coverage up. Trap size -30%. Worth it.", "Strings! Between them! Twangy!", "Joined up. It joins up in the end.", "Each puddle reaches for the next! Nothing crosses our devotion!", "Traps linked. Strands Snare. Traps smaller.", "Each puddle holds the hand of the next puddle. A hand holding."],
  "wup:Spare Hankies": ["More traps. Four now. Put them down.", "Scale. Always scale. Two traps is cope. Four is mindset.", "More of them? So I don't have to pick up? Fine.", "One always carries spares. For others.", "Trap capacity doubled. Inventory: well stocked. Satisfaction: 88%.", "More! More puddles! All the puddles!", "Bring extras. Last time... no. Just bring extras.", "Twice the snot! Twice the traps! Our feeling overflows!", "Double traps. More down. Use them.", "We carry four sneezing cloths now. A gentleman is prepared."],
  "wup:Twang": ["Touch the string. Pulled to the trap. Stuck.", "Don't chase, attract. They come to you. Reel them in.", "It just yanks them in. I don't even have to move.", "They're shown to their seats.", "Strand contact: unit returned to nearest trap. Return processed.", "BOING! Back it goes! Do the boing!", "Pulled back where it began. It always pulls back.", "Pulled home to the puddle! As we are pulled home to her!", "Crosses strand. Pulled to trap. Caught.", "The string pulls the enemy home to the puddle. A strong homesickness."],
  "wup:Bogey Man": ["It dies. Bogey rolls. Bogey sticks them.", "Every exit is a product launch. Monetise the bodies.", "It turned into a bogey. Honestly, same.", "One flicks it away and lets it roll where it likes.", "End point produces rolling hazard. Contact: Snared. Free gift.", "Bogey! A rolling bogey! Chase it!", "It rolls away. Small things keep going.", "From its ending a bogey is born and rolls off to fight for us!", "Dies Snared. Bogey rolls. Catches others.", "From the ended enemy, a bogey is born. It rolls off to make friends."],
  "wup:Snot Ocean": ["Big traps. Very big. Long time.", "Go big. Nine out of ten men think too small. Be the tenth.", "Bigger puddles. Less moving. Acceptable.", "A proper estate. Lakes, naturally.", "Trap size x3. Duration x2. Containment: excellent. You're welcome.", "SO BIG! Biggest puddle! Swim in it!", "It all becomes the sea again. Where it began.", "The puddle becomes an ocean! We would cross oceans for her!", "Traps huge. Last long. Hold.", "The puddle becomes an ocean. We cross oceans for the Other Half."],
  "wup:Superglue": ["In the trap. Stuck. Cannot move. Cannot hit.", "Total control. Nobody leaves on their terms. Frame is everything.", "Nobody's going anywhere. Including me. Perfect.", "Everyone stays exactly where one put them.", "Snared units: fully stuck. Movement: 0%. Bosses: slowed only.", "Can't move! Can't move at ALL! Poke!", "Held still. You will remember how that feels.", "Glued! Held! As fast as our vows will hold us to her!", "Stuck solid. No moving. Bosses slow.", "The enemy is glued in place, like the vows we will exchange."],
  "wup:Snotwork Everywhere": ["Swim. Trap. Swim. Trap. All joined. Many.", "Everywhere you go, you own. Expansion mindset. Mark the territory.", "I just leave them behind me. Like everything.", "One leaves a trail. The help is used to it.", "Auto-dispensing traps every second. Network: complete. Enjoy.", "Twangs everywhere! A big web! Look!", "A web behind us. A path we can find again.", "A web of us wherever we swim! Let them follow and be caught!", "Trap each second. All joined. Keep swimming.", "We leave a web of snot behind us, so the way home is not forgotten."],
  "wup:Bleeding Heart": ["Poke. Bleed. Poke. More bleed. Wait.", "Play the long game. Bleed them slowly. 73% of wins are slow wins.", "Less hitting, more waiting. My kind of plan.", "One does not rush. Let them bleed at their leisure.", "Bleed per hit enabled. Bleed cap doubled. Direct output -30%.", "Pokey poke! Red! Lots of red! Poke!", "It takes its time. So did we.", "Each little stabbing is a burning love letter! They pile up!", "Every hit Bleeds. Cap doubled. Hits weaker.", "Each little stabbing is a love letter. They pile up."],
  "wup:Leaky": ["Full of bleed. It spills. Next one bleeds.", "Overflow is opportunity. Spread the brand. Leak the content.", "It's leaking on people. Not my mess.", "Too much? Pass it down the table.", "Unit at capacity. Overflow redirected to nearest unit. Apologies.", "Drip drip! On him! Drippy!", "It overflows. Things that fill always do.", "So full of bleeding it must share! Our gift is too large!", "Full of Bleed. Leaks. Next one gets it.", "The enemy is too full of bleeding. It shares with a neighbour."],
  "wup:Open Wound": ["It dies. Big red puddle. Crossing it is bad.", "Leave a mark. Literally. A red carpet for the next guy.", "Big pool. Don't look at it. Wasn't me.", "Have someone see to the stain. Or leave it as a warning.", "Large blood pool deployed. Crossing it: Bleed. Please mind the floor.", "Red puddle! Big one! Don't touch! Touched!", "It stays open. Some things do.", "Where it ended, a red lake! Red as what we feel for her!", "Bleeder dies. Pool. Crossers Bleed.", "Where the enemy ended, a red lake waits. It is very sincere."],
  "wup:Sewing Circle": ["Missed. It comes back. Try again.", "Failure is just a second pitch. Swing round, go again.", "It missed. Then it came back. Like that's my fault.", "Missed needles return to one. As they should.", "Missed needle rerouted. Second delivery attempt in progress.", "Round and round! Back again! Throw it!", "It comes round again. Everything comes round.", "The missing needle dances round us and flies out burning again!", "Missed. Loops round. Out again.", "The needle that misses dances a circle around us and leaves again."],
  "wup:Needlework": ["Line them up. One needle. Through all of them.", "Fewer shots. Bigger shots. Quality over volume. That's a ten move.", "Fewer shots? Thank god. Less effort.", "One stitch. The whole row. One sews properly.", "Pierce enabled. Damage rises per unit. Fire rate -25%. Fair trade.", "Through! Through! Through! All of them!", "Through each one. Each one a little more.", "One needle through the whole line! Each one harder than the last!", "Needles pierce line. Each harder. Slower.", "One needle visits five enemies in a row. A very busy needle."],
  "wup:Sutures": ["Through three. String stays. String bleeds them.", "Tie up loose ends. Then invoice them for it.", "It leaves a string. Someone'll trip. I'll say I meant it.", "A neat seam. One only accepts neat seams.", "Thread installed between first and last unit. Crossing fee: Bleed.", "A string! A red string! Jump over it!", "A thread left behind. Threads can be followed back.", "A stitch across the water! Let any who cross it bleed for her!", "Three pierced. Thread left. Crossers bleed.", "The needle leaves a stitch across the water. To cross it is to bleed."],
  "wup:Reef Knot": ["Five. Tied up. All bleeding. Done.", "Rule one: tie them down, then talk business. Five at once.", "Tied them in a knot. Like my stomach. Whatever.", "Bundle them together. One cannot abide loose staff.", "Five units bundled. Shipping as one package. Bleed included.", "Tie them up! All together! A knot!", "Tied together. You know this knot.", "Five enemies in one knot! Tied as tightly as we will be to her!", "Five pierced. Knotted. All Bleeding.", "Five enemies are tied in one knot. It is a crowded friendship."],
  "wup:Tattoo": ["Five hits. Little heart. It dies. We feel better.", "Five touches and they're yours. Brand them. That's attraction.", "Fine, I drew a heart on it. Don't make it weird.", "One marks one's property.", "Loyalty stamp: 5 of 5. Redeem on termination for a small heal.", "A heart! On it! I drew a heart!", "A small heart. It meant something once.", "We draw a heart on it! On our world this means war!", "Five hits. Heart. It dies. We heal.", "We draw a heart on our enemy. On our world this is a formal threat."],
  "wup:Final Prick": ["Hurt ones first. Finish them. Then the next.", "Closers close. Nobody remembers the guy who almost mogged.", "I'll just finish off the ones that are nearly done.", "One only steps in for the final signature.", "Low-health units: damage x2. Healthy units: -25%. Prioritising.", "That one's wobbly! Get it! GOT IT!", "The ending is the part that matters.", "We do not begin! We finish, and we finish with fire!", "Weak ones: double. Healthy ones: less. Finish.", "We do not begin things. We only end them, very well."],
  "wup:Next, Please": ["One down. Next one. Next one.", "Next. Always next. Abundance mindset. Never dwell on one.", "Yeah, yeah. Who's next. Let's get it over with.", "Next, please. And do keep the queue moving.", "Now serving: next-weakest unit. Complimentary needle dispatched.", "That one! Now that one! Now THAT one!", "And the next. There is always a next.", "One ends and already we race for the next! No resting!", "Kill. Free needle. Next weakest.", "The ended enemy is replaced by the next appointment."],
  "wup:Terminal Clause": ["Low and bleeding? One poke. Gone.", "Read the small print. Then enforce it. Lawyers are cope.", "It was basically dead anyway. I just made it official.", "One has the paperwork. They're dismissed.", "Termination clause executed. Terms and conditions applied.", "Bye bye! Gone! It's gone!", "Already over. It was over a while ago.", "The contract ends it at once! We read the ending aloud with joy!", "Bleeding. Low. One needle. Over.", "The contract has an ending in it. We read it to the enemy."],
  "wup:Vaccination": ["Kill one. Safe for a bit. Keep going.", "Immunity is a mindset. Also, a jab. Statuses are for betas.", "One jab and I'm fine? Should've done this ages ago.", "One had all one's jabs. Naturally.", "Kill registered. Immunity patch installed. Valid for a few seconds.", "Ow! Pokey! Now we're brave!", "Protected, briefly. That is all protection is.", "Each ending shields us! Nothing will sicken us before her!", "Kill. Immune. Next status blocked. Brief.", "The small stabbing protects us from the large sicknesses. A paradox."],
  "wup:Exsanguinate": ["Lots of bleed. Every hit. We get better.", "Drain them dry. Take what's yours. 100% retention. Provider energy.", "They bleed. I feel better. That's the whole plan.", "They give. One receives. As it should be.", "Bleed per hit: several stacks. Healing from kills: x2. Thank you.", "Red red red! So much red!", "Everything flows out of them and into us.", "They give us their blood! A dowry for our Other Half!", "Hits stack Bleed. Kills heal double.", "The enemy gives us its blood. It is a dowry."],
  "wup:Pin Cushion": ["Eight needles. Eight of them. One each.", "Eight targets. Zero hesitation. Shooting your shot, eight times.", "Fine, everyone gets one. Happy now?", "Something for everyone. One is generous.", "Volley: 8 needles. 8 addresses. Every parcel tracked.", "Pins for all! You get one! And YOU!", "One for each. As it was meant to be.", "Eight needles, each burning toward its own! None will be missed!", "Eight needles. Eight targets. Fire.", "Eight needles, each with its own address. The postal system of love."],
  "wup:Coup de Grace": ["Hurt ones die. One poke. All of them.", "Finish strong. 100% of finishers finish. Write that down.", "Oh, it's dead. I barely touched it.", "A courtesy. One ends things gracefully.", "Low-health units now terminated on contact. Bosses: damage x3.", "Poke! Gone! Poke! Gone!", "It ends gently. Most things end gently, in the end.", "The last stabbing! A mercy and a greeting and a cry of love!", "Hurt ones die. Bosses take triple.", "We give the last stabbing. It is a mercy and also a greeting."],
  "wup:Ghost Through": ["Go through one. Then the next. Then the next. Keep going.", "Don't stop for one. Sigmas walk through crowds. I read that somewhere.", "Didn't stop. Couldn't be bothered. Turns out that's a skill.", "One doesn't stop for people. One goes through them.", "Pass-through enabled. Four recipients per dispatch. Satisfaction: 88%.", "Through! And through! And THROUGH that one too!", "We went through them. We will have gone through them. Same thing.", "Through them! Through all of them! Nothing stands between us and her!", "Shot goes through. Four bodies. Do not stop. Continue.", "Our hitting does not stop at one body. It visits each of them."],
  "wup:Cold Spot": ["Every one gets cold. Line them up. Then they are all cold.", "Leave them all colder. Ice-cold frame. The egg rates that a nine, minimum.", "Everyone's gone cold on us. Fine. Mutual.", "A draught. Someone has left a door open. Have it seen to.", "Chill applied to all recipients in line. Temperature preference: noted.", "Brrr! Brrr! Him too! BRRR!", "It is colder here than it was. It was always colder here.", "I leave my cold in each of them, so they know I passed on my way to her!", "Cold left in each. Several at once. They will know we passed.", "We leave a coldness in each of them. It is a kind of letter."],
  "wup:Second Sighting": ["Go to the end. Start again. Same line. Two times.", "Repetition builds empires. Same line, twice, more conviction. Locked in.", "Do it all over again? Ugh. Fine. Same as before.", "Have it go round once more. They missed it the first time.", "Delivery attempt 2 of 2 in progress. Thank you for your patience.", "It went AGAIN! Make it go again again!", "It has flown this line before. It knows the way now.", "Again! The ghost flies the line again! Twice I declare myself!", "Ghost returns to start. Flies again. Same line. Good.", "The ghost returns to the beginning. It enjoys the travelling twice."],
  "wup:Nine-Tenths of the Law": ["That one is ours now. It shoots its friends. Good.", "Possession is nine-tenths. The other tenth is confidence. And mewing.", "Make them do it. Why should we do everything.", "One has acquired staff. Have it see to its colleagues.", "Third-party reseller onboarded. It now ships our product to its friends.", "He's on OUR side! Shoot him! No, shoot THEM!", "It has always been ours. It just did not know yet.", "This one is ours now! It fights for us! Everyone shall fight for her!", "One of theirs is ours. It shoots them. Good trade.", "This one has moved in with us. It now defends the household."],
  "wup:Revolving Door": ["Out. Hit. Back. Hit. Two hits. Then home.", "Rule four: always follow up. A high-value man comes back for seconds.", "It came back. Like it had nowhere better to be. Relatable.", "Have it return once it has finished. One expects things returned.", "Return shipping included at no extra cost. Transit time: up 30%.", "It's back! Hi! Go! Bye! Hi!", "It comes back. Things that leave usually come back.", "It comes back to us! Loyal! As I shall be loyal to her, both ways!", "Ghost hits. Ghost turns. Ghost hits again. Slower. Fine.", "The ghost performs a returning. It is loyal in both directions."],
  "wup:Ghostly Tug": ["It brings some back with it. They come to us. Good.", "Don't chase. Attract. They come to you. Works on the egg. Works on these.", "They come to us now. Saves swimming. Whatever.", "Have them brought round. One doesn't go to people.", "Enemies relocated towards you for your convenience. No action required.", "Come here! Come HERE! It's bringing them! Yay!", "They drift towards us. They drifted then as well.", "Come closer, all of you! Come and see who I am fighting for!", "Ghost pulls them in. Towards you. Ready yourself.", "The ghost brings guests home with it. We must prepare a welcoming."],
  "wup:Hitching a Ride": ["That one rides along. It hits the others. Two jobs done.", "Leverage other people's bodies. That's what the top 1% do. Allegedly.", "It gets a lift and we don't. Typical.", "A chauffeur at last. Mind the others, driver. Or don't.", "Passenger detected. Collision with associates: confirmed. Joy: 58%.", "Piggyback! PIGGYBACK! Bonk! Bonk!", "It has given this one a lift before. It is a familiar weight.", "Drag it! Let it strike its own kin! All must bow on our way to her!", "Possessed one dragged. Bumps its friends. Keep going.", "The possessed one is given a carrying. It bumps its family on the way."],
  "wup:Haunted House": ["We missed. That's fine. It waits. Then it hits.", "There are no misses. Only delayed returns. Real talk. Let that sink in.", "Missed on purpose. It's a trap. Obviously. Leave it.", "Leave it under the floorboards. Someone will tread on it.", "Missed delivery rescheduled. Ghost will await the next customer below.", "Where'd it go? Under! It's under! BOO!", "It is waiting under there. It has been waiting a long time.", "Even my missing waits for them! My patience burns beneath the floor!", "Miss. It sinks. It waits. It rises. Hit.", "The missing ghost goes beneath and waits. An ambush with good manners."],
  "wup:Unfinished Business": ["Hit it. If it dies later, it pops. Then the others hurt.", "Haunt them after. Exes never forget a high-value man. Write that down.", "We don't have to finish them. They finish themselves. Great.", "One needn't finish a thing. Somebody always does.", "Haunting subscription active. Cancellation by death triggers a burst.", "It's got a ghosty! When it pops, THEY pop!", "It isn't finished. Nothing is finished just because it ended.", "Even dying they shall burst for us! Nothing ends until I reach her!", "Hit one. It is haunted. It dies. It bursts. Hits weaker.", "When they die, they leave with a bursting. It is their last speech."],
  "wup:Spreading Spooks": ["The pop spooks the next ones. Then those pop. Then it stops.", "One referral becomes two. Pyramid thinking, minus the lawsuits.", "It's going round. Like a rumour. Not my fault.", "Pass it down the family. That is what families are for.", "Haunting forwarded to contacts. Chain limit: 2 generations. Compliant.", "Spooky! And spooky! Everybody's SPOOKY!", "It runs in the family. It ran in ours, I think.", "It spreads! The haunting has children, as we shall have children!", "Burst haunts others. Two deep. Then stops.", "The haunting has children. The children have children. Then it rests."],
  "wup:Friendly Ghost": ["The big one is ours now. It fights for us. Then it goes.", "Convert your rivals into employees. That's mogging, technically.", "Someone else can do the fighting. About time.", "The large one has joined the household. Briefly. Like all staff.", "Large spirit reassigned to our team. Onboarding: 4 seconds. Welcome!", "Big ghosty is my friend! Can I keep it? I'm keeping it.", "It was our friend before. It just remembered.", "The great one fights at my side! Even the dead join my courtship!", "Big spirit fights for us. Short time. Use it.", "The big spirit becomes a friendship. It is short but sincere."],
  "wup:Seance": ["Dead ones come back. They get shot. We don't. Good plan.", "Bring your exes back as decoys. 0% of them say no. I checked. Twice.", "Let the dead ones take it. They're not doing anything.", "The deceased will receive visitors on our behalf.", "Previous customers recalled for decoy duty. Their feedback is welcome.", "Hello again! Bye! They're shooting the ghosts! Silly!", "Old faces. Some of them are always here.", "The departed rise to shield us! Even death takes up our cause!", "Old kills return. Draw fire. We slip past.", "We call back the departed. They stand in front of the shooting for us."],
  "wup:Mass Possession": ["Every hit counts double now. They stay ours longer.", "Everyone wants to be on your team. 100% conversion. A ten notices that.", "Everyone's on our side now. Finally someone listens.", "Everyone works for us now. As it should have been.", "Possession uptake: 50% per hit. Duration doubled. Thank you for joining.", "Mine! And mine! And MINE! They're all MINE!", "The crowd turns. It turns more easily this time.", "All of them! Let all of them be ours! Let them carry my love to her!", "Half a bar each hit. Longer hold. Many are ours.", "The many are moved in. Our household is now very full."],
  "wup:Poltergeist": ["It doesn't stop. It goes everywhere. It hits six. Then done.", "Never settle. Six targets minimum. Scarcity is a beta mindset.", "It just wanders about bumping into things. Same, honestly.", "Let it roam the house and rearrange the furniture.", "Route optimisation disabled. Six stops scheduled. Order: unknown.", "Wheee! That way! No, that way! Everywhere!", "It wanders. It is in no hurry. It knows they are all here.", "Wander, ghost! Knock them all down! I cannot wait for anything!", "Ghost wanders. Hits six. No route. Fine.", "The ghost goes for a wandering. It knocks over everything it loves."],
  "wup:Ghost Army": ["Every one we beat joins us. More ghosts. More shots.", "Every kill a new follower. Up from one. That is how a brand grows.", "Ugh, they keep following us. Fine. Make them useful.", "Each one dismissed is rehired at once. Very efficient.", "New subscriber per kill. Each fires ghost shots. Community: thriving.", "More friends! More! He's my friend now too!", "The dead stand up and stand with us. They did before, too.", "Every fallen one joins us! An army to escort me to her door!", "Each kill raises one. It shoots. Army grows.", "Each ending becomes a joining. Our wedding party grows."],
  "wup:Hotter Mess": ["Stand in it longer. Burn faster. That is how it works.", "The longer they stay, the more it costs. Commitment is a tax. Real talk.", "Should've moved. Not my problem they didn't.", "They may stay as long as they like. It will cost them.", "Burn rate scales with time on premises. Patch size reduced by 20%.", "Hot! Hotter! HOTTEST! Don't touch it! Can we touch it?", "The longer it sits, the hotter it gets. Like a bath, almost.", "Stay, burn hotter, stay longer! My heart is exactly this patch!", "Stay longer. Burn faster. Patch smaller.", "Each staying makes the burning warmer. Do not linger at the doorway."],
  "wup:Backdraft": ["One catches fire. Then the whole thing goes up. Good.", "One win lifts the whole room. Ten out of ten room. I rate rooms.", "One of them goes up and suddenly everyone's excited.", "When one catches, have the whole room attend.", "Ignition detected. Patch-wide flare deployed. Celebration: 73%.", "WHOOSH! Do it again! WHOOSH!", "It flares. I knew it would flare. I just did not know when.", "One catches, and the whole fire rises for her! Burn, all of you, burn!", "One ignites. Whole patch flares. Extra hurt.", "One ignites and the whole fire stands up to applaud."],
  "wup:Hot Tub": ["They try to leave. They get pulled back. Stay in.", "Nobody leaves the hot tub. House rules. A ten never leaves early.", "Can't get out. Know the feeling.", "Nobody leaves the spa until one says so.", "Early checkout unavailable. Your stay has been extended. Enjoy!", "Bath time! Back in! BACK IN!", "They try to leave. Nobody leaves a warm bath.", "Back in! Nobody leaves while I burn this brightly!", "Edge pulls them back. No leaving.", "The water holds them with a hugging. They may not go home yet."],
  "wup:Fire Drill": ["They won't go in. So it is a wall. Stay behind the wall.", "Boundaries. Set them. Enforce them. In fire. The egg loves boundaries.", "Nobody's coming in. Good. Leave us alone.", "A moat. Every good house has one.", "Firewall enabled. Intrusions: 0%. Internal burn rate: doubled.", "Nobody's allowed in! Except me! Okay not me!", "They will not cross it. Something in them remembers fire.", "None may cross my burning! None shall come between me and her!", "They will not enter. A wall. Inside burns twice.", "They fear the burning line. It is a fence that bites."],
  "wup:Spreading Rumours": ["They walk out. They leave fire. Fire behind them. Good.", "Rule eleven: let your reputation precede you. Ideally on fire.", "Everyone's talking about it. Whatever. Let them.", "Let them carry it out. One shouldn't have to.", "Burning footprints distributed. Patch lifetime reduced 30%. Noted.", "Fire feet! Fire feet! Look at his fire feet!", "It follows them out. It always follows them out.", "They carry my fire into the world! Let all hear of my burning!", "They leave burning. Tracks burn too. Patch dies sooner.", "They carry the fire away like a gossiping. It spreads by foot."],
  "wup:Hot Foot": ["The footprints burn too. Just as much. Two fires.", "Every step a statement. 70% of impact is follow-through. Source: me.", "The footprints work as well? Fine. Less effort.", "Every step they take is billed.", "Footprint burn rate matched to patch. Consistency: 100%. You're welcome.", "Ow! Ow! Hot! Every step! Ow!", "Each step burns. Some floors are like that.", "Every step they take burns! Even their walking shouts my name!", "Footprints burn as hot as patch. Good.", "Each stepping leaves a burning. Their feet are now liars."],
  "wup:Burning Bridges": ["It catches fire. It drops more fire. More fire is good.", "Burn the bridge. Then sell the ashes. That is the grindset.", "Burning bridges? Story of my life. Fine.", "Leave nothing they can come back to.", "New patch installed at ignition site. Limit: one per customer.", "New fire! New fire! It made a BABY fire!", "No going back. That is the point of it.", "Where they ignite, new fire! More fire! I have so much fire to give!", "Ignites on footprints. New patch there. Once each.", "Where they ignite, a small fire is born. It has the temper of its mother."],
  "wup:Toasty": ["Stay in our fire. It's warm. It makes us better.", "Self-care is a power move. Sit in it. Own it. Sauna culture.", "Finally. A place to lie down. Sort of.", "One's own fire. Naturally it agrees with us.", "Thermal recovery detected. Wellbeing: up 3%. Please remain in the patch.", "Warm! Warm warm warm! Can we stay? We're staying.", "Warm. I remember warm. Stay a moment.", "Our own fire holds us tenderly! It knows whose heart it came from!", "Stand in own fire. Heals. Slowly. Stay.", "Our own burning embraces us gently. It knows its family."],
  "wup:Flash in the Pan": ["Short fire. Then a big bang. Wait for the bang.", "Peak early, peak big. Longevity is for betas. The egg agrees. I assume.", "It doesn't last. Nothing does. At least it goes out loud.", "Brief, but memorable. Like one's best appearances.", "Patch lifespan halved. Grand finale scheduled. Please stand clear.", "It's getting big! It's getting BIG! BANG!", "It doesn't last. It was never going to last. It ends well.", "A short burning and a great ending! I cannot wait! I never can!", "Short patch. Then eruption. Wait for it.", "A short burning with a great finishing. Like a firework, or a romance."],
  "wup:Short Fuse": ["Four of them go in. It goes off. Count to four.", "Wait for a full room. Then perform. Never play to empty seats.", "Four's enough. Can't wait forever. Won't.", "Once enough guests have arrived, begin.", "Attendance threshold reached (4). Eruption brought forward. Thank you!", "One, two, three, FOUR! BANG!", "It won't wait. It never did like waiting.", "Four of them! Enough! The fire cannot hold its passion a moment more!", "Four inside. Erupts now. No waiting.", "When four guests are seated, the fire begins. It was always going to."],
  "wup:Powder Keg": ["No more fire. Just bangs. Put it down. Wait one. Bang.", "Stop simmering. Detonate. 88% of greatness is timing. 12% is jawline.", "No hanging about in it. Just boom. Fine by me.", "Leave the gift. Do not be in the room when it is opened.", "Product updated: patch replaced with burst. Size doubled. Delay: 1 s.", "BOOM! Big boom! Bigger boom!", "One second. It is always one second longer than you think.", "No more smouldering! One second, then everything, all at once!", "No burning now. One second. Big blast.", "The fire holds its breath for one moment. Then it speaks, very largely."],
  "wup:Hot Potato": ["The fire moves. It goes to the next one. Then the next one.", "Opportunity moves to whoever is standing still. Never be that guy.", "Not it. Not it. Your turn.", "Have it passed along to whoever is next.", "Patch relocated to nearest customer. Free delivery. No signature needed.", "Catch! Catch! Your turn! CATCH!", "It moves on. It always found the next one.", "Leap, fire! Find them! Do not wait for them to come to us!", "Patch jumps. Nearest enemy. Again. Again.", "The fire is given away like a present nobody wishes to hold."],
  "wup:Hellmouth": ["One big fire. It follows them. It keeps burning.", "Go big. One enormous move. Ten out of ten, no notes. Like me.", "One big one that does the walking. Love that for us.", "Have the fire fetch them. It's what it's for.", "One large patch assigned to densest crowd. Duration: extended. Enjoy!", "Big fire! BIG! It's chasing them! Go fire go!", "The ground opens. It opens wider than I remember.", "The ground itself opens for my love! Hunt them, great mouth, hunt!", "One huge fire. Follows the crowd. Lasts long.", "The ground opens a great mouth. It is hungry on our behalf."],
  "wup:Spontaneous Combustion": ["Any fire makes our fire. Fire makes fire. Easy.", "Every flame in the room is yours now. That's ownership. That's sigma.", "They just catch fire on their own now. Less work.", "Every fire in the house is ours. Obviously.", "Any ignition now generates a patch. Coverage: 100%. Satisfaction: 97%.", "Pop! Fire! Pop! Fire! Everything's on fire! Yay!", "They catch on their own. People do, given time.", "Every burning makes a new burning! The whole world catches my fever!", "Any ignition. Any source. New patch. Once each.", "Each ignition gives birth to a small burning. The fire is very fertile."],
  "wup:Scorched Earth": ["Fire stays while they stand in it. Up to six fires.", "Never leave while there's someone left to beat. Not even to eat.", "Don't go out till they leave. Same rule as bed.", "The fire stays as long as there are guests.", "Patches persist while occupied. Maximum: 6. Occupancy: pleasing.", "Fire everywhere! Keep it! Keep ALL of it!", "Nothing grows here after. Nothing needs to.", "My fire will not leave while one remains! I am faithful like this!", "Fire stays while they stand in it. Six at most.", "The fire refuses to leave while there is company. It is a good host."],
  "wup:Event Horizon": ["Close is strong. Far is weak. Get them close.", "Inner circle only. Keep your people close and the rest weak. Frame.", "Can't escape it. Like family dinner.", "Only the inner circle is held. As in all good families.", "Pull strength doubled at core. Edge coverage reduced 30%. Noted.", "Stuck! They're stuck! Wiggle! Can't wiggle!", "Once you are in, you are in. It was always like that.", "Closer! Come to the centre, where my longing pulls hardest!", "Pulls hard in middle. Weak at edge. Fewer caught.", "There is a line past which no leaving happens. We approve of this."],
  "wup:Roach Motel": ["They go in. They stay in. Until the end.", "Get them in the room. Lock the door. Close the deal. 9 in 10 stay.", "They check in. They can't leave. Relatable.", "A room has been booked for them. Indefinitely.", "Check-in confirmed. Check-out unavailable. Enjoy your stay.", "In! Stay! Good! STAY!", "They check in. Nobody remembers checking out.", "Hold them! Keep them there until my passion is finished with them!", "Centre holds them. Until orb ends. Not bosses.", "They enter the small hotel and the leaving is not offered."],
  "wup:Compaction": ["Squash them all. One squash. Everyone gets hit.", "Rule six: consolidate. Everyone in one place, one hit. Efficiency.", "Squash them all at once. Saves doing it twice.", "Have them packed. One does dislike clutter.", "Contents compressed for shipping. Collision charge applied per item.", "SQUISH! All of them! SQUISH!", "Everything ends up pressed together. Everything.", "Crush them together! One great embrace, one great ending!", "Orb ends. All crushed. One blast. Each hit.", "At the ending they are pressed into one family. A crushing reunion."],
  "wup:Lost Property": ["They leave their gems. Gems come to us. Pick them up.", "Their losses, your assets. Provider energy. Let it compound.", "Stuff just turns up. Don't ask where from.", "Their belongings are forwarded to us. As is customary.", "Unclaimed items forwarded to your address. No charge.", "Shiny! Shiny! For me? It's for me!", "Things come back to you. Lost things especially.", "Their treasures fall to us! Gifts I shall lay before her!", "Gems come to you. Collect. Move.", "Their small treasures are returned to us. A dowry, perhaps."],
  "wup:Orbituary": ["They go round and round. They do not fall in.", "Keep them orbiting. Never let them in. That's how a ten does it. Learn.", "Round and round. Going nowhere. Like everyone.", "They may circle. One does not admit just anyone.", "Enemies placed in holding pattern. Orb output reduced 40%. Sorry!", "Round! Round! ROUND! Dizzy!", "Round they go. This part always goes round.", "Circle us, all of you! Dance for the love I carry!", "They circle orb. Do not fall in. Orb weaker.", "They make a circling around the orb, like guests around a cake."],
  "wup:Fender Bender": ["They bump. A bump is a hit. Lots of bumps.", "Let the competition take each other out. Sit back. Mew, ideally.", "They're crashing into each other. Not my driving.", "The staff appear to be colliding. Have them carry on.", "Collision detected. Collision detected. Collision detected. Joy: 81%.", "Bump! Crash! BUMP! My turn! My turn!", "They always crash at this corner.", "Crash into each other! Clear the way to her! Faster!", "They crash. Each other. Everything. Each hit.", "They hit each other with great affection. It is a family gathering."],
  "wup:Let Go": ["Hold on. Hold on. Let go. They fly.", "Release them. Abundance mindset. Plenty more out there. Plenty. Okay?", "Fine, let go. Didn't want them anyway.", "Let them go. One can always get more.", "Orbit terminated. Contents ejected outwards. Thank you for flying with us.", "Let go? Okay! WHEEEE! Bye!", "You have to let go eventually. That part I remember.", "Fly away! Begone! There is room for only one love here!", "Orb ends. They fly out. Knock others back.", "We release them with a great throwing. It is the custom at weddings."],
  "wup:Gravity Assist": ["Swim past the ball. Go faster. Keep going to the egg.", "Use every advantage. Momentum is free money. Never pay for speed.", "Free speed. No effort. Finally something for us.", "One prefers to be carried. This will do.", "Slingshot applied. Estimated time of arrival: improved. Joy: 64%.", "ZOOM! Do it again! Again! ZOOM!", "Round the orb, faster. The route remembers us.", "Fling us to her! Faster! Every moment apart is a burning!", "Pass orb. Speed burst. Go.", "The orb gives us a throwing towards the Other Half. Very kind."],
  "wup:Big Bang, Eventually": ["Wait. Merge. Wait more. Then the big one.", "Delayed gratification. The big payoff is for men who wait. I wait. Daily.", "It'll happen eventually. Probably. Don't rush me.", "It will happen when it happens. Things do, for us.", "Merger efficiency up 50%. Delivery speed down 30%. Please hold.", "Is it now? Is it now? Is it NOW?", "Everything big starts small and waits. You know this.", "Wait? I cannot wait! But for something this large, I will try!", "Merging faster. Orbs slower. Big later.", "We wait for the great beginning. Universes are not hurried."],
  "wup:Midnight Feast": ["Count the merges. Three merges. Then it eats shots.", "Three wins and you're untouchable. Bullets are just protein.", "It eats their shots now. At least someone's eating.", "It dines on their fire. One mustn't be fussy.", "Merge count displayed. At 3, incoming fire is consumed. Convenient!", "Num num num! Eat it! Eat ALL of it!", "It gets hungry about now. It always did.", "It eats their shots! Even their bullets are swallowed by our devotion!", "Count shows merges. At three, eats shots. Hide near it.", "At the third joining, the orb develops an appetite for bullets."],
  "wup:Afterglow": ["Big bang. Then it keeps pulling. Two parts.", "Build the hype. Then leave them wanting. Afterglow is branding.", "Still glowing? Bit much. Let it, I suppose.", "One leaves an impression. One always does.", "Supernova scaled to total output. Residual pull: active. Pride: 77%.", "Pretty! It's still pretty! Can I touch it? I touched it.", "It glows after. The good ones always glow after.", "Even after the ending it pulls, as I still pull towards her!", "Supernova bigger. Leaves a pull. Few seconds.", "After the great ending, a warmth stays. Like after the first kissing."],
  "wup:White Hole": ["Pull. Pull. Push. Three. Then start over.", "Push them away every third time. Keeps them keen. Women, sorry, orbs.", "Leave me alone. Every third time I mean it.", "Every third visitor is turned away at the door.", "Every third orb reversed. Personal space: respected. Please stand back.", "Go away! Come back! Go AWAY!", "Pull, pull, push. It has a rhythm. I know the rhythm.", "Away! Every third time, away! My heart is for one only!", "Third orb pushes. Not pulls. Space.", "Sometimes the orb says no. Every third time, a refusing."],
  "wup:Supermassive": ["Big orbs. Strong pull. Three together. Very big bang.", "Supermassive. That's not a goal, that's a lifestyle. Like mogging.", "Fine. It's huge. Can we lie down now?", "Larger. As is our due.", "Orb size doubled. Gravity: excessive. Supernova damage: tripled.", "BIG! BIGGER! BIGGEST! BANG!", "It was this big once before. Or it will be.", "Huge! Enormous! As great as my longing, and pulling everything in!", "Orbs double. Pull hard. Three merges. Big blast.", "Our orb becomes enormous with devotion. Everything falls towards it."],
  "wup:Spaghettification": ["In the middle they get stretched. Then gone. Simple.", "Stretch them. Push past limits. Theirs, not yours. Looksmaxxing, sort of.", "They get stretched thin. Know the feeling.", "Pasta. How common. Still, have them served.", "Core damage quadrupled. Near-empty items disposed of whole. Tidy!", "Noodles! Long noodles! SLURP!", "Pulled long and then gone. It is gentler than it looks.", "Stretch them thin! Swallow them! Nothing shall stand in my path!", "Centre hurts four times. Weak ones swallowed.", "At the centre they become noodles. It is a sad meal."],
  "wup:Wormhole": ["In one ball. Out the other ball. Fast. Hits things.", "Disrupt. In one door, out the other. That's innovation. And hustle.", "In one side, out the other. Like my homework.", "A private passage. One has always had one.", "Linked portals installed. Transit is instant. Arrival: forceful.", "In there! Out THERE! How? Do it more!", "In one side, out the other. Some of us know the way.", "In one door and out the other, hurled at speed! Like my love!", "Two orbs linked. In one. Out other. Fast.", "Two doors in the dark with one corridor. We understand corridors."],
  "wup:Pinball Wizard": ["They hit one. They keep going. They hit the next one.", "Momentum is a mindset. Never let them stop. Grindset, but for them.", "They bounce. We don't. Just let them get on with it.", "Let them bounce off one another. Staff do that.", "Rebound enabled at 70% speed. Blast output reduced 20%. Enjoy!", "Boing! Boing! BOING! Whee!", "Off one and on to the next. Things carry on.", "Bounce on! Never stop! I never stop, not for anything but her!", "They bounce on. Do not stop. Blasts weaker.", "They meet each other and do not stop. It is a very busy courtship."],
  "wup:Bank Shot": ["Walls bounce too. Every bounce is a hit. Use the walls.", "Use the walls. Use everything. The walls work for you now. Locked in.", "The walls are doing the work. Respect.", "The walls appear to be on our payroll.", "Wall rebounds now included. Collision charge applied per rebound.", "Off the wall! Bonk! Off the WALL!", "Off the wall and back. I know that angle.", "Even the walls join my cause! Throw them back, walls, throw them!", "Walls count. Each rebound hits.", "The wall returns the enemy with interest. Walls are honest here."],
  "wup:Hat Trick": ["Hit three. Then it pops. One, two, three, pop.", "Three in a row. Elite. A ten would screenshot that. She probably did.", "Three of them? Fine. Pop. Can we go?", "Three introductions, then it leaves. Proper form.", "Third collision registered. Reward dispensed: small blast. Well done!", "One! Two! THREE! POP!", "Three. It was always three.", "Three! Three greetings and it bursts with passion! I understand!", "Three bounces. It bursts. Small blast.", "After three greetings, it bursts with too much emotion."],
  "wup:Sausage Link": ["One drags the next. Like a line. A long line.", "Network. Every connection drags another one in. Hypergamy, but meat.", "Dragging someone else along. Classic.", "They've been strung together. Like a family photograph.", "Tether attached. Next item collected en route. Bundle discount applied.", "Sausages! A sausage train! Choo choo!", "One pulls the next. Families are like that.", "Bind them together! As I shall be bound to her, forever!", "String drags next one. Linked. Good.", "They are tied together with string, like the cans behind a wedding car."],
  "wup:Heavy Meat": ["Big ones hit hard. Small ones don't move. Use big ones.", "Size matters. The data is clear on this. 64% clearer. Let that sink in.", "Throwing the big ones. Heavy lifting. Not doing it twice.", "One uses the larger staff for heavy work.", "Damage scaled by package weight. Small items: low impact. Thank you.", "Big one! Throw the BIG one! Splat!", "Heavy things hit hardest. That was true before.", "Throw the great ones! Hurl the heaviest at them, with all my heart!", "Big ones hit hard. Small ones barely move.", "We throw the large ones. Their weight is a kind of argument."],
  "wup:Weight Class": ["Big hits small. Small flies far. Far is good.", "Know your weight class. Then hit below it. Hard. That's alpha.", "Big ones picking on little ones. Wow. Original.", "The juniors are sent home early.", "Small units dispatched by large units. Shipping distance doubled.", "Fly! Fly little one! So FAR!", "The little ones go further. They always do.", "The great ones fling the small ones far! Away, away, all of you!", "Big sends small far. Twice as far.", "The heavy ones send the light ones on long journeys."],
  "wup:Prime Cut": ["Throw the big one. It breaks shells. Good.", "Rule two: top-shelf ammunition only. You are what you throw.", "Throwing the posh ones now. Fair enough.", "Only the finest cut. Naturally.", "Premium tier active: elites ship as heavy hits. Bosses excluded.", "The big shiny one! Throw it! CRUNCH!", "The best cut. Saved for a day like this one.", "Hurl their champion at them! Nothing is too large for my devotion!", "Elites fly hard. Heavy hit. Not bosses.", "We hurl their chieftain at them. It is not polite, but it works."],
  "wup:Meat Shield": ["Meat lands. Meat makes a wall. Hide behind the wall.", "Build walls, not bridges. Protect your peace. And your jawline.", "A wall. Something to hide behind. Finally.", "Have something placed between us and them.", "Barrier assembled from local materials. Enemy shots blocked. Sustainable!", "A wall! A meat wall! Hiding! You can't see me!", "Stay behind it. It will hold for a little while.", "The meat rises to protect us! Stand, meat, stand for love!", "Meat lands near. Becomes wall. Blocks shots. Short.", "The meat stands up and becomes a wall for us. Very loyal meat."],
  "wup:Meat Grinder": ["Hit it three times. Then it pops. Count to three.", "Three reps. Then results. That's the whole programme. Sign up below.", "Hit it again. And again. Ugh. And pop.", "Have it softened up first. Then served.", "Mark 1 of 3 applied. Mark 3 triggers shockwave. Progress: excellent.", "Knock knock knock POP!", "Three knocks and then it gives. Some doors are like that.", "Three knockings! Then it opens! I cannot bear the waiting!", "Three marks. Then shockwave. Shorter knockback.", "With three knockings the meat opens like a door."],
  "wup:Splatter Zone": ["It pops. The others fly. More flying.", "Your wins should splash on everyone nearby. Spread the value.", "Bit messy. Not cleaning it up.", "Someone will have to clean that. Not us.", "Shockwave radius shared. Neighbours also launched. No extra charge.", "Splat! SPLAT! Everyone go flying!", "It goes everywhere. It does tend to.", "Share the bursting! Let every neighbour feel what I feel!", "Shockwave launches neighbours too.", "The bursting shares itself with neighbours. A generous splattering."],
  "wup:Chain Tenderising": ["Pop marks the next one. Then that one pops. Then stop.", "Compounding results. One pop pays for three. Passive income, basically.", "It just keeps going on its own. Good. I'm tired.", "One pop sets off the next. Rather like inheritance.", "Shockwave now marks recipients. Chain depth: 3. Efficiency: 92%.", "Pop pop POP! More pops!", "One knock leads to the next. It has a way of doing that.", "Each softening makes another! On and on, like my love for her!", "Shockwave marks too. Three deep.", "Each softening makes the next softening. It is a meat family tree."],
  "wup:Leftovers": ["Chunks fall off. Swim through chunks. Feel better.", "Fuel the machine. Protein is protein. Ninety grams a day, minimum.", "Eating off the floor. Whatever. Nobody's looking.", "Not one's first choice of menu. It will do.", "Refreshments available. Swim through to restore. Bon appetit!", "Yum! Yum! Can I eat it? I ate it.", "Leftovers. They taste better the second time.", "We feast on their remains! Strength for the journey to her!", "Chunks drop. Swim through. Heal a little.", "We eat what remains of the enemy. A traditional ceremony."],
  "wup:Perfect Game": ["Everything flies more. Everyone hits more. Very good.", "Three hundred. Perfect game. The egg loves a perfect score. Statistically.", "Perfect, apparently. Don't make it a big thing.", "Perfect. As one expected.", "Launch force doubled. Knock-on depth: 4. Rating: five stars.", "STRIKE! Everybody fall over! STRIKE!", "Every pin goes down. It is lovely when they all go.", "Everything flies! Everything falls! A perfect game, for her!", "All launches doubled. Four deep. Strike.", "Every enemy falls in the perfect falling. We are a bowling."],
  "wup:Tenderiser": ["Every bump is a big bump now. They break.", "Every touch is a statement. No soft hits. Ever. Softness is cope.", "Even a bump hurts now. Same.", "Every touch leaves a mark. Breeding tells.", "All collisions now classed as heavy hits. Quality assured.", "Bonk! BONK! Everything BONK!", "Everything hits harder now. You have stopped being gentle.", "Every touching is a heavy hitting! My love is not gentle today!", "Every collision is heavy. All of them.", "Each touching is now a heavy hitting. Our love is strong."],
  "wup:Human Cannonball": ["We fly now. Point at the egg. Fly at the egg.", "You are the ammunition. Aim at what you want. Then take it. Sigma.", "Fine. Throw us. At least we're not swimming.", "One travels by cannon now. It is quicker than queuing.", "Express delivery mode: you. Untouchable in transit. ETA: soon.", "Me! Throw ME! WHEEE! Again!", "We fly. We have flown before. It is shorter than it looks.", "We are the throwing! Hurl us at her! She will see us arrive from far!", "You launch. Long way. Untouchable. Go.", "We become the throwing. The Other Half will see us arrive from far."],
  "wup:Return to Womb": ["Catch them. Keep them. Count to full. Then let go.", "Rule one: never release early. 91% of tens can tell.", "Good. We just sit here and hold things. Love that.", "Let them pay in first. One settles the bill later.", "Storage at 4%. Output paused until capacity reached. Thank you for waiting.", "Is it full? Is it full now? NOW? Let it GO!", "We hold it in. We have held it in before. It keeps.", "Hold every hitting for her! I cannot wait, but I will wait!", "Storing. Not firing. Full soon. Then all.", "You gather their hittings like rain in a bowl. The bowl will tip."],
  "wup:Full Term": ["All of it. One way. At one of them.", "Pick one target. Commit. Don't chase, mog. Let that sink in.", "Everything at one guy. He'll know it was personal.", "All of it at the one. The others may watch.", "Full payload routed to a single recipient. Delivery: guaranteed.", "ALL of it! At HIM! All at once!", "It goes in one direction. It always went there.", "All of it to one! I do nothing by halves! Nothing!", "One target. Everything. Now.", "Every hitting goes to the one. Devotion is a narrow road."],
  "wup:Afterbirth": ["One volley. Then one more. At the big one.", "Always follow up with the big one. Persistence is high-value.", "Then there's a second bit. Nobody warns you about that.", "And the second course goes to the guest of honour.", "Second shipment dispatched to priority customer. No signature required.", "MORE came out! More! Is there more?", "The second part comes after. It came after before.", "And again! A second giving for the large one! I insist!", "Second volley. Big one. Sent.", "After the giving comes a second giving. The ceremony must be complete."],
  "wup:Hiccup": ["Some shots go twice. Twice is more.", "Sometimes you overdeliver. Statistically, I always overdeliver.", "Hic. Not on purpose. Well. Now it's on purpose.", "One does not hiccup. One returns things twice, graciously.", "Duplicate dispatch detected. No action needed. Enjoy your bonus item.", "Hic! Hic! It did it! Do the hic!", "Hiccups. Those come back too.", "A double hitting! My heart also jumps like this!", "Shot doubled. Hiccup. Ignore. Continue.", "A small jumping lives in the returning. Let it jump."],
  "wup:Umbilical Shield": ["Keep the shots. They make a wall. Stay in the wall.", "Build your frame. Literally. Bullets are protein for alphas.", "A blanket made of bullets. Finally, a reason to stay in.", "Have the staff keep us insulated. And close the door.", "Protective layer: 12% and rising. Output reduced 40%. Safety first.", "A bubble! We're in a bubble! Poke it! Don't poke it.", "The cord and the wall. You had them once already.", "Their bullets become your coat! I let nothing touch you!", "Their shots. Your coat. Thicker. Good.", "Their hittings become your coat. We wear the enemy, and are warm."],
  "wup:Suction Cup": ["Their shots come to us. We eat them. Easy.", "Don't chase, attract. Bullets, tens, same principle. Pure frame.", "Don't even have to move. They come to me. As it should be.", "One need not reach. They bring it to the table.", "Inbound items auto-collected. Threat probability reduced to 31%.", "Come here! Come HERE! Got you! Mine!", "They drift in. They drifted in. Let them.", "Come to us, all of you! We have room for every hitting!", "Pulling them. In they come. Eat.", "Their bullets fall towards you, as all things fall towards the centre."],
  "wup:Water Breaks": ["Wall breaks. Shots come out. All sides.", "Membrane down? That's a pivot. Breakdowns are breakthroughs.", "Ugh, it burst. Fine. Everyone gets some.", "If the wall must go, it takes the help with it.", "Containment failure reclassified as distribution event. Items released.", "It POPPED! Wet! Wet everywhere!", "The waters go first. Then the rest. That order holds.", "The waters break! Everything goes out! It is time, it is time!", "Waters broken. Everything out. All ways.", "The waters break, as waters do. Everything held is given back."],
  "wup:Re-Gift": ["Not back to them. To someone far away.", "Never return a gift to the giver. That's simp behaviour. Ratio him.", "Didn't want it. Gave it to someone else. Classic.", "Pass it along. One never keeps a gift one dislikes.", "Return address unavailable. Item forwarded to most distant recipient.", "Not yours! For HIM! Over there! Catch!", "Gifts move on. This one has moved on many times.", "Not to you, giver! To the far one! Let the gift travel!", "Wrong sender. Send far. Done.", "The present travels on to a stranger. Gifts, like souls, keep moving."],
  "wup:Eat the Rich": ["Only the big ones. Big ones hit back big.", "High-value bullets only. I don't date below an eight. Shots, I mean.", "Can't be bothered with the little ones. Too much effort.", "Small portions are for small people.", "Small items no longer accepted. Large items processed at triple value.", "The BIG one! Eat the big one! Yum!", "Let the little ones pass. We know which to keep.", "Only the great hittings are worthy! Small ones, go away!", "Big ones only. Triple. Small ones, no.", "We eat only the large hittings now. A refined hunger is a patient one."],
  "wup:In One Ear": ["It goes through one. Then the next one. Then the next.", "Go through people. That's leadership. I read that in a thread.", "It just keeps going. More than I do.", "It doesn't stop for anyone. Quite right.", "Item passing through all recipients. No stops scheduled.", "Through! And through! And THROUGH!", "Straight through. Nothing stopped it then either.", "Through all of them! Nothing stands between us and her!", "Through them. All of them. Not stopping.", "The hitting walks through every one of them. It does not knock."],
  "wup:Paternity Test": ["Boss shot. Back to the boss. That is fair.", "Results are in: it's his. Return it. A real man owns his output.", "It's yours, actually. Take it back.", "Return it to its father. With the family's compliments.", "Sender verified. Item returned to originator. Tracking: very accurate.", "Yours! That's YOURS! Give it back!", "It finds its father. They always find their father.", "It is yours, large one! Take it back! I want nothing of yours!", "Sender found. Returning. Heavy.", "The bullet is reunited with its parent. A tender hitting."],
  "wup:Swap Meet": ["Their shot. Our kind. Swapped.", "Rebrand what you steal. That's not theft, it's a personal brand.", "Changed it a bit. Now it's mine. Don't ask.", "Have it altered. One doesn't wear things off the rack.", "Item repackaged at random. Contents may differ from description.", "What colour now? What colour NOW? Ooh!", "Same thing, different coat. I have worn a few.", "Every hitting in a new costume! We dress up for her!", "New colours. Random. Send anyway.", "The hitting returns in a borrowed hat. Nobody recognises it."],
  "wup:Mirror Womb": ["They shoot us. It goes back. Half the time.", "Mirror their energy. Fifty per cent bounces. That's called frame.", "Whatever you send, you get back. Not my problem.", "One simply returns the post unopened.", "Return policy updated: 50% of incoming items sent back. No questions.", "Bounce! It bounced! Throw it at us! Bounce!", "It comes back. It always came back to them.", "You throw at us? Half of it comes back! Shame on you!", "They shoot. Half returns. Fair.", "What they send is half answered. The universe is like this also."],
  "wup:Let-Down Reflex": ["Hold forty. Let go. Let go again.", "Forty reps, two sets. Then a cold plunge. Locked in.", "It just comes out. Can't stop it. Not my fault.", "Everyone gets fed. Twice. One is generous today.", "Capacity: 40 units. Distribution: all directions, twice. Have a great day.", "EVERYWHERE! It's going everywhere! Two times!", "It comes when it is ready. It was always ready twice.", "Everyone gets some! Twice! I am overflowing for her!", "Forty held. Ring out. Again. Done.", "The feeding is round, and it is twice. Everything near is our infant."],
  "wup:Bullet Sponge": ["Bigger mouth. More shots. Eat them.", "Triple your reach. Bigger radius, bigger mog. Simple maths.", "Just absorb it. Like everything. Like always.", "One's catchment has expanded. As expected.", "Collection radius tripled. Threat detection: 88%. Nothing gets past.", "All of them! Give me ALL of them!", "Soak it up. You have soaked up worse.", "From far away I call them all! Come, hittings, come!", "Reach tripled. Far ones too. Drink.", "Your drinking reaches very far. It is a thirsty love."],
  "wup:Proximity Problems": ["Put mines down. They come close. Mines go off.", "Boundaries. Step in my space, get exploded. Healthy masculinity.", "Don't come near me. I warned you. Sort of.", "The grounds are private. Trespassers are dealt with.", "Proximity sensors active. Intruder probability: 72%. Blast output: 85%.", "Don't touch! Don't TOUCH! He touched it! BOOM!", "Somebody always steps closer. Someone stepped closer.", "Come closer and be exploded! None shall near you but her!", "Close one. Boom. Weaker. Still boom.", "The mines are shy. When you approach, they explode with feeling."],
  "wup:Pass the Parcel": ["Boom. Fly back. Boom again.", "Pass him along. Delegation is a sigma trait. I invented it.", "Not my turn. Pass it on. Literally.", "Have them sent along to the next room.", "Recipient rerouted to next station. Delivery chain: operational.", "Your turn! Now his turn! BOOM! Pass it!", "It goes round. The music stops somewhere.", "Away with you! To the next one! Unwrap yourself again!", "Knocked back. Next mine. Again.", "The enemy is a gift, unwrapped by each mine in turn. A party."],
  "wup:Crawling Baby": ["The mines move. Slowly. Towards them.", "Even the mines grind. If a mine can hustle, so can you.", "Even the mines have more energy than me.", "They make their own way over. One needn't fuss.", "Mobile units dispatched. Speed: low. Determination: 100%.", "It's crawling! It's a baby! Go baby go!", "They crawl before they walk. Then they go off.", "Little ones, go! Crawl to them with all your heart!", "Mines crawling. Slow. Getting there.", "Your small explodings learn to crawl. We are proud parents."],
  "wup:Hand-Me-Down": ["They pick it up. They take it home. Boom.", "Let them carry your work home. Passive income. Mostly explosions.", "They took it. Not my mine any more. Their problem.", "Have him carry it in. Staff do carry things.", "Courier assigned. He is not aware. Delivery expected shortly.", "He has it! Throw it! He's got it! Ha!", "Things get passed down. Not always the good things.", "Take it home to your family! Take it, I say!", "He has it. Going home. Wait.", "He carries the gift home to his family. The family is surprised."],
  "wup:Cluster Diaper": ["Tie the mines together. Touch one. All go.", "Build a network. One touch, every asset activates. Sigma maths.", "They just sit there taped up. Relatable.", "They wait in a row. As good staff should.", "Units grouped. Activation on first contact. Please do not touch. Thanks.", "Tape! More tape! Tape them all together!", "Tied together. One goes, they all go. Some things hold.", "Together they wait! Touch one and know all their love!", "Taped. Grouped. Touch one. All go.", "The mines hold hands. When one is touched, all are offended."],
  "wup:Compound Interest": ["First boom. Bigger boom. Biggest boom.", "Compound gains. The third mine is where the money is. Let that sink in.", "Each one is worse. Like days.", "Returns grow. They always do, for us.", "Output increasing per unit. Growth: 100% on target. Very exciting.", "Big! BIGGER! BIGGEST!", "It grows each time. It grew each time before.", "Bigger! Bigger! Each one louder than the last, for her!", "Each bigger. Bigger. Bigger.", "Each exploding is larger than its sister. The family is ambitious."],
  "wup:Nappy Pin": ["Three booms. Then one big one. Shaped like a nappy.", "Rule five: always close big. The egg remembers the finish.", "Big finish. Whatever. Someone has to clean that up.", "The grand finale. Someone else will tidy.", "Three-unit sequence complete. Bonus item issued: one large nappy.", "It's a NAPPY! A boom nappy! Do it again!", "The pin goes in last. Careful. Careful. There.", "Three, and then the great one! Nappy-shaped and glorious!", "Three done. Big one. Nappy. Go.", "The final exploding wears a nappy. It is a very large infant."],
  "wup:Changing Mat": ["Stop. Mines go round us. Then go.", "Rest days are for betas. If you must stop, stop armed.", "Finally. A lie-down. With security.", "When one stops, the floor is laid for us.", "Idle detected. Protective ring deployed. Your downtime matters to us.", "Stop! Mines! Go! Stop! MORE mines!", "Lie still. Let them lay it out round you.", "You pause? Then I ring you with fire! No one comes near!", "Stopped. Ring laid. Rest. Briefly.", "When you pause, a circle of small fires guards our resting."],
  "wup:Lingering Smoulder": ["Booms leave fire. Fire stays. Fire grows.", "Leave a lasting impression. 70% of them still think about me.", "Leave a mess and walk off. My speciality.", "We leave it smouldering. Someone else will put it out.", "Residual heat retained. Duration extended. Blast output: 75%.", "Fire stays! Fire's still there! Touch it! Don't!", "It burns a while after. It does, after.", "Let the fire stay! Let it burn as long as I burn for her!", "Fire stays. Grows. Weaker blast. Fine.", "The fire stays to say goodbye for a long time."],
  "wup:Pooling Resources": ["Two fires. They touch. One big fire.", "Merge and acquire. Empire building. I'd rate this merger a nine.", "They all just blur together. Like everything.", "Consolidate the estate.", "Zones consolidated. One larger zone now in service. Thank you.", "They touched! Big puddle! Fire puddle!", "Little fires find each other. They always have.", "The small fires marry! I weep at every wedding!", "Fires touching. Now one fire. Bigger.", "The small fires marry. Their union is hot."],
  "wup:Flare Up": ["One burns. Fire gets big. Then small.", "Feed off their energy. Literally. That's a masterclass in frame.", "Oh good, it's bigger now. Fantastic.", "One of them caught. The rest may follow.", "Ignition detected. Zone temporarily expanded 200%. Please stand clear.", "WHOOSH! It went whoosh! Again!", "It flares. It settles. You get used to the rhythm.", "One catches and the fire leaps! As I leap, thinking of her!", "One lit. Fire jumps. Back off.", "One enemy ignites, and the fire stands up to see."],
  "wup:Bouncy Castle": ["Boom. It bounces. Boom.", "Every setback is a setup. That's why I bounce. Twice. Like a mine.", "Didn't work the first time. So it went again.", "It goes off twice. One does like value.", "Unit relocated after first activation. Second activation: scheduled.", "Bouncy! Bouncy boom! Bounce it!", "It lands. It goes again. It landed there before.", "It leaps again! Again! It cannot stop exploding for joy!", "Thrown on. Goes again. Twice.", "The mine is jumping in its castle. It explodes from joy."],
  "wup:Nuclear Nappy": ["Three mines. Then a very big one.", "Every fourth rep is a max. Train like it. Explode like it.", "Every so often I just snap. This is that.", "Every fourth is something rather special.", "Unit 4 of 4: enhanced model. Output significantly larger. Enjoy.", "The BIG one! The biggest! Where is it?", "Every fourth one. Count with me. There.", "The fourth is a sun! Burn, for the sake of our meeting!", "Fourth one. Huge. Stand clear.", "The fourth nappy holds a sun. Please do not change it."],
  "wup:Minefield": ["More mines. More often. They stay longer.", "Saturate the market. Triple the mines. The egg will notice. Eventually.", "Mines everywhere. Don't make me tidy them.", "Have the grounds fully seeded.", "Inventory tripled. Dispatch frequency doubled. No returns accepted.", "Mine! Mine! Mine! All mine!", "So many. It is quiet before. It is very quiet.", "Mines everywhere! I plant a whole garden of explodings!", "Many mines. Often. Long. Floor full.", "The floor is planted with explodings. Our garden is dangerous."],
  "wup:Nappy Rash": ["Big fire. Stays a long time. Joins up.", "Total coverage. Red everywhere. That's what winning looks like.", "It's all red and it burns. Classic.", "The whole floor is warm now. Adequate.", "Affected area: 300%. Duration extended. Soothing cream: out of stock.", "It's ALL red! All of it! Hot hot hot!", "It spreads. Let it. Rashes pass.", "The ground burns red with my love! Everywhere! All of it!", "Ground red. Wide. Long. Burning.", "The ground is angry and red. It needs a cream we do not have."],
  "wup:Long-Distance Love": ["Twin goes far. Line gets long. Sweep it.", "Long distance only works if you're high value. You are. Barely.", "We need space. It's healthy. Apparently.", "One keeps the other half at a polite distance.", "Range doubled. Aim accuracy: 41%. Thank you for your patience.", "Go far! Further! Is it still there? It's there!", "Far apart, still joined. That part never changes.", "So far apart, and still I reach! Distance is nothing to us!", "Wider gap. Longer beam. Aim hard.", "Our signal stretches across the great distance. We know this feeling."],
  "wup:Absence Makes It Grow": ["Longer line. More hurt. Stretch it.", "Be unavailable. Distance builds value. Works on tens. And beams.", "The further away it is, the better. Same.", "Absence. One recommends it.", "Output scales with distance. Optimal range achieved. Have a great day.", "Stretchy! Stretch it! Further! Further!", "It grows stronger the further it goes. Like some of us.", "The farther away, the hotter I burn! This is the truth of love!", "Stretch it. Full length. Strongest.", "The farther the beloved, the stronger the burning. This is poetry."],
  "wup:Tug of Love": ["The line pulls them. To us.", "Don't chase. Pull. That's frame. Rate that a nine.", "Ugh, now they're coming over. Thanks.", "Have them brought over.", "Items collected en route to your location. Free delivery included.", "Pull! Pull it! Here it comes! Got it!", "It pulls them close. Closer than you would choose.", "Come to us! I drag you by the heart, whether you like it or not!", "Caught. Pulling. Coming in.", "Each enemy is drawn to you by a rope of love. They object."],
  "wup:Evil Twin": ["The twin goes off. Hits the big one. Comes back.", "Even your twin has a side hustle. Respect the grind.", "It's gone off on its own. Rude. Fair, though.", "Every family has one. Ours is useful.", "Secondary unit operating independently. Loyalty check: 97%. Probably fine.", "Where's it going? Bad twin! Bad! Go on then!", "It wanders. It always wandered back.", "Go, other half! Go and fight! Return to us victorious!", "Twin gone. Hunting big one. Back soon.", "Your other half has a dark phase. It returns, refreshed."],
  "wup:Toxic Codependency": ["Hit more of them. The line gets stronger.", "Feed off the crowd. 80% of my energy is borrowed. Peak frame.", "It needs them. Needy. Whatever.", "It does rather depend on an audience.", "Performance depends on crowd size. Current crowd: insufficient.", "More! Brighter! More of them! BRIGHTER!", "It leans on them. You have seen this before.", "More of them! The beam lives on crowds! Feed it, feed it!", "Cross many. Grows. Few, weak.", "Our beam cannot live without crowds. This is not healthy."],
  "wup:Boiling Point": ["Full. White. Everything gets Charged.", "White hot. Ten out of ten. Never drop below this. Ever.", "Fine. Now I'm angry. Happy?", "One rarely loses one's temper. When one does, it shows.", "Maximum output reached. Status: white. Everything touched: Charged.", "WHITE! It went white! So bright!", "White. Then everything feels it. I knew the colour.", "White hot! I am so devoted I shine! All will feel it!", "Full. White. Charging all. Hold.", "The beam is so devoted it turns white. All it touches feel the same."],
  "wup:Swapsies": ["Twin here. Us there. Swap.", "Rule six: keep them guessing. Switch places. Mystery is attractive.", "Swap places. Different view. Same problems.", "Exchange seats. The help can sit where we were.", "Unit locations exchanged. All items along the route have been notified.", "Swap! Swap! Where are we? Swap again!", "Over there now. It was over here a moment ago.", "We trade places, beloved twin! Everything between is struck!", "Swap. Through them. Done.", "You and your other half trade places. All between are surprised."],
  "wup:Gold Digger": ["The line picks up the shiny things. Brings them.", "Gold digger? No. Hypergamy. I mean provider. Secure the bag.", "Brings me the stuff. Don't have to move. Good.", "Have it brought to us. Naturally.", "Valuables collected and delivered to you. Please rate your experience.", "Shiny! Shinies! Give me the shinies!", "It gathers what is left. Somebody has to.", "Treasures for the dowry! Everything shiny is hers!", "Gems. Collected. At your side.", "The beam collects small treasures for the dowry."],
  "wup:Third Wheel": ["Charged one gets hit. Line jumps to the next.", "A third wheel is just untapped potential. And a liability.", "Someone's always tagging along. Fine. Use them.", "A guest brings a guest. One allows it.", "Additional recipient added. Main connection reduced to 80%.", "Another one! Little line! Over there!", "There is always a third. There was a third before.", "A third? There is room in my heart! Hit him too!", "Third one. Short beam. Thinner. Fine.", "A third person enters the relationship. The relationship hits him."],
  "wup:Mixed Signals": ["More lines. They cross. Sparks.", "Mixed signals keep them interested. 64% of experts agree. I'm the experts.", "Is it on? Is it off? I don't know. Neither do they.", "One keeps several arrangements going. Discreetly.", "Multiple signals active. Interference: beneficial. No action needed.", "Criss! Cross! Sparkles! Do the crossy one!", "The lines cross. Where they cross, something happens.", "Signals everywhere! Where they cross, sparks! Like my heart!", "More beams. Crossing. Sparks. Good.", "Our signals cross and the crossing is sparkling. Confusing, but warm."],
  "wup:Love Triangle": ["Three points. A triangle. Inside gets Charged.", "Abundance mindset. Never commit to one. Except the egg. Obviously.", "Three of us now. Awkward. Effective.", "A third party. One simply doesn't discuss it.", "Triangle formed. Contents: Charged. Satisfaction: 92%.", "Triangle! It's a triangle! Inside! Get inside!", "Three corners. It was always three corners.", "Three hearts in a triangle! None escape this love!", "Three points. Inside, Charged. Hold.", "We add a third heart to the arrangement. Everyone inside is excited."],
  "wup:Mirror Image": ["Some shots hit the twin. Twin is fine.", "Take the hits through a proxy. Work smart. That's what twins are for.", "Take it for me. You owe me. Probably.", "Someone stands in for us. As usual.", "Decoy unit accepting incoming items. Damage to decoy: 0%.", "It's you! No, it's us! Shoot that one!", "Which one of us is it? It does not matter here.", "My other half takes the blows for you! Such devotion!", "Twin takes hits. Twin fine. Go.", "Your other half accepts your hittings. This is true devotion."],
  "wup:Quadruplets": ["More twins. More lines. Four of us.", "Scale the team. Delegate the sweeping. You're the CEO now.", "More siblings. Great. Just great.", "A large family. Old money does that.", "Two additional units delivered. Household now four. Welcome.", "One, two, FOUR! Lots! Lots of us!", "There were four. There are four. It was always four.", "Two more! More of us! The family grows for her!", "Two more twins. Four beams. Sweep.", "The family grows by two. We prepare more chairs for the wedding."],
  "wup:Psychic Link": ["Pulse goes down the line. Big hit.", "Manifest it. Then hit it very hard. Manifesting is mostly the hitting.", "I knew you'd do that. Every time.", "One merely thinks it, and it is done.", "Scheduled pulse transmitted along all lines. Poise removed. Thank you.", "Zap! Zap along! It goes along! ZAP!", "You feel it before it comes. You felt it then too.", "A thought of her races down the beam and strikes like thunder!", "Pulse. All lines. Heavy. Down.", "A thought travels the beam and arrives as a hitting. Our love is loud."],
  "wup:Conjoined Twins": ["Twin next to us. One line. Straight. Strong.", "Laser focus. Literally. A sigma never sweeps. Straight lines only.", "Stuck together now. Forever. Can't wait.", "Joined at the side. One's family is close.", "Units merged. Single output, forward only. Steering disabled.", "Together! Stuck! Straight! ZAP that way!", "Side by side. We were side by side then.", "Two become one! Straight at them! Nothing can part us now!", "Joined. One beam. Forward. Strong.", "Two become one and point the same way. Very romantic. Very bright."],
  "wup:It's Spreading": ["It jumps more. It goes further. Six jumps.", "Go viral. Reach is everything. Engagement drops off, but reach.", "It's spreading. Not my fault. Well.", "Word does get round. One can't help it.", "Coverage expanded. Signal loss per hop: increased. Within tolerance.", "Jump! Jump! Jump! It keeps jumping!", "It spreads. Things like this always spread.", "Spread, my touching! To every one of them!", "Spreading. Further. Weaker each. Fine.", "The touching spreads through the crowd. Nobody asked for it."],
  "wup:Split Ends": ["One chain. Splits. Two chains.", "Diversify. Two streams of contact. Basic portfolio theory.", "It split. Like my focus.", "It parts in two. One needn't choose.", "Route split into two. Both routes active. No additional charge.", "Two ways! It went two ways!", "It forks. You take both roads. That is new.", "Two paths! I cannot choose, so I choose both!", "Split. Two chains. Both go.", "Your touching has divided, like the hair of the stressed."],
  "wup:Still Buzzing": ["Last one stays Charged. Longer.", "Leave them thinking about you. They always do. I assume.", "It lingers. Like a bad mood.", "One does leave a lasting impression.", "Charge retained on final recipient. Duration: 200%. Enjoy.", "Still glowy! Look! Still glowing!", "The glow stays after. It stays a long while.", "Remember my touching! Remember it twice as long!", "Last one. Still charged. Longer.", "After the touching, a warm glow remains. We are told this is normal."],
  "wup:Bad Hair Day": ["Charged ones stick together. Easier.", "Group them up. Efficiency is attractive. Nine out of ten tens agree.", "They're all clumping. Gross. Useful.", "They do huddle so. Like staff at a party.", "Charged items clustering. Sorting completed automatically.", "They're sticking! Like a balloon! Rub it!", "They drift together. Static does that.", "Together, all of you! Cling to each other, as I cling to her!", "Charged ones drift. Together. Easier.", "The enemies stand up like hair after a balloon. They dislike it."],
  "wup:Conductive Personality": ["Charge them. Then everything hits harder.", "Lift the whole team. Leaders take a pay cut. Briefly. For optics.", "I do the setup. Someone else gets the credit.", "One sets the table. Others may eat.", "Charged recipients accept damage from all sources. Local output: 70%.", "Fizzy ones! Hit the fizzy ones! Harder!", "It is not the hitting. It is the readying.", "Let them all hit what I have touched! I give my glory away!", "Charged ones soft. All hit harder. You less.", "Your charm conducts. Everyone becomes more hittable near you."],
  "wup:Spread the Love": ["Not that one. A new one. Charge it.", "Abundance, not scarcity. Never message the same target twice.", "Fine. Everyone gets some. Happy?", "One mingles. Everyone deserves a moment of us.", "New recipients prioritised. Repeat deliveries: discontinued.", "That one! No, THAT one! Everyone!", "Not the same one twice. You learn that.", "A new one! Always a new one! There is enough for all!", "Uncharged first. New ones. Next.", "We share our touching with strangers. It is generous and unwanted."],
  "wup:Last Spark": ["Charged one dies. We go faster.", "A win builds momentum. Ride it. Losses don't exist. Next.", "Oh, it died. Now I have to hurry? Great.", "Their exit does rather quicken the pace.", "Recipient deactivated. Throughput increased. Productivity: 118%.", "It popped! Fast now! Faster! Go go go!", "When it goes out, you speed up. That is how it goes.", "One falls and we go faster! Faster towards her!", "One down. Faster. Move.", "One dies with a spark, and our hurrying grows. We mourn quickly."],
  "wup:Odd Sock": ["One of them gets hit every time. Good.", "Rule nine: find the weak link. Use him. Every time.", "There's always one. Poor thing. Anyway.", "One of them is always the help.", "Relay recipient selected. All traffic routed via one unit. Efficient.", "That one! Always that one! Ha ha!", "There is always one left over. Like the sock.", "You, odd one! Every bolt shall find you! Every one!", "That one. All bolts. Through him.", "One enemy is chosen as the odd sock. Every bolt visits him."],
  "wup:Feedback Loop": ["Other hits make sparks. Sparks make sparks.", "Leverage other people's work. That's networking. Slower, but sigma.", "Others do the work. I just echo it.", "One lets the others begin it.", "Echo detected. Secondary arc issued. Primary rate reduced to 75%.", "Spark! It sparked the spark!", "It echoes. Some things keep echoing.", "Each hitting sings, and I sing back louder!", "Arc. Echo. Smaller. Slower now.", "Each hitting sings, and the song sings back."],
  "wup:Echo Chamber": ["Spark. Then spark. Then one more spark.", "Surround yourself with yes-men. They amplify you. Yes. Exactly.", "It just keeps agreeing with itself.", "Everyone here agrees with us. Rightly.", "Repeat transmission confirmed. Repeat transmission confirmed.", "Again! Again! And AGAIN!", "It echoes. The echo echoes. It has before.", "Again it leaps! It cannot stop telling everyone!", "Echo. Again. Again.", "The arc repeats itself, like a parent at dinner."],
  "wup:Brainstorm": ["Lots of sparks. Then one big storm.", "Big idea energy. Hit everyone at once. That's how podcasts work.", "Okay. Fine. I had a thought. It's everyone.", "Occasionally one has an idea. It is enormous.", "Arc 20 of 20 reached. Broadcasting to all Charged recipients.", "EVERYONE! It hit EVERYONE! Whoa!", "It builds and then it breaks. Wait for it.", "A storm of thinking! Every one of them shall feel it!", "Twentieth. Storm. All charged. Now.", "A storm of thinking. Every charged person receives an idea."],
  "wup:Balloon Animal": ["One dies. Balloon. Floats over. Pop.", "Even your leftovers should work for you. Passive income, but balloons.", "A balloon. For me? No. For him. Pop.", "A little party favour for the next guest.", "Complimentary balloon issued. It will deliver itself. Have fun.", "BALLOON! Balloon! Can I have it? POP!", "Balloons float off. That is what they do.", "From his ending, a balloon! Go, little party, go!", "One gone. Balloon. Floating. Pop.", "From the dead comes a small party animal. It visits the next guest."],
  "wup:Tumble Dryer": ["Every hit can spark now. All of them.", "Synergy. Everything I touch is electric. Ask anyone. Don't, actually.", "Everything's static now. Hair everywhere.", "All of one's efforts crackle now. Naturally.", "All outputs now Static-enabled. Compatibility: 100%. You are welcome.", "Round and round! Crackle! Everything crackles!", "It goes round. It comes out warm and crackling.", "Everything we do crackles! I am all sparks for her!", "All hits spark. Chains start. Good.", "Everything spins and crackles. Our socks are attracted to each other."],
  "wup:Worked Up": ["Eight jumps. Each one harder.", "Progressive overload. Every jump, add weight. Never skip chain day.", "Each one makes me angrier. You did this.", "One grows less patient with each of them.", "Output increasing per hop. Hop 8 of 8: maximum. Very efficient.", "More zap! More! Every one more!", "It builds. Let it build this time.", "Hotter with every leap! I cannot calm down! I will not!", "Eight jumps. Each harder. Climbing.", "The touching grows with each stranger, as a river grows with each rain."],
  "wup:Grid Lock": ["Charged ones join up. The lines hurt.", "Build the network. Every connection pays. Mostly in sparks.", "Can't get through. Nobody can. Good.", "Roped off. Members only.", "Network established. All connections live. Crossings will be hit.", "Lines! Lines everywhere! Don't step on the lines!", "A net of light. Step through it carefully.", "Lightning holds them hand in hand! Let none pass between!", "Linked. Live lines. Nobody crosses.", "The charged ones hold hands with lightning. Nobody passes."],
  "wup:Birds of a Feather": ["More of them tied up. Hit one. Hurt six.", "Network like a sigma. Bigger circle, shorter loyalty. That is the game.", "Bigger group project. Same amount of effort from me.", "Seat them together. They can share a table.", "Bundle size increased. Adhesive life reduced. Your satisfaction matters.", "All tied up! All of them! Tie MORE!", "They always find each other. They found each other before, too.", "Tie them all together! Every one! We have no time for their slowness!", "More tied. Further apart. Tape weak. Hurry.", "They are of one feather now. Feathers fall. Feathers always fall."],
  "wup:Corporate Merger": ["Two groups. Now one group. Easier to count.", "Rule one: acquire the competition. Then hit the competition. Mogged.", "Great. They merged. Now there are more of them to ignore.", "Merge the departments. Fewer people to remember.", "Two networks merged. Duplicate entries removed. Efficiency: 112%.", "They touched! Now they are stuck! Stuck FOREVER!", "Two become one. That will happen to us as well, soon.", "Two bundles become one! A wedding! I cannot wait for my own!", "Two bundles touch. One bundle. Bigger. Good.", "Two bundles make a wedding. All weddings are one wedding, in the end."],
  "wup:Long Distance": ["Far away still counts. Hit here. Hurt there.", "Long distance never works. Except when I do it. Then it is 100%.", "Can't be bothered to swim over. Don't have to. Nice.", "The big one is too far? Then send word down the tape.", "Signal: full at all distances. Coverage: unlimited. You are welcome.", "Far away and still OW! Do it again!", "Distance never mattered much. It will matter less now.", "Distance means nothing! Ask me how far I came for her! Very far!", "Far away. Still reaches. Big one feels it. Stop.", "The far ones feel it as the near ones do. Distance is a small thing."],
  "wup:Loose Ends": ["Tape on the floor. They swim on it. They stop.", "Never leave money on the table. Leave tape on the floor. Same energy.", "Didn't tidy up. Turns out mess is a strategy.", "Someone else will clean that. Meanwhile, they can trip.", "Residual adhesive detected. Trip probability: 87%. Please mind the step.", "Sticky floor! They're stuck! Ha! STUCK!", "Something always gets left behind. It is useful this time.", "Even the leftovers fight for us! Everything fights for her!", "Tape stays. They cross. They stick. Good.", "The tape remains after the ending. Like a memory, but sticky."],
  "wup:Shared Trauma": ["One gets sick. They all get sick. Good.", "Trauma is team building. I charge 400 a session for this insight.", "Now they all feel bad. Welcome to how I feel.", "If one has a problem, they all have a problem. House rules.", "Condition sharing enabled. Contamination risk: theirs. Have a nice day.", "Pass it on! He's got it! Now HE'S got it!", "What is wrong with one becomes wrong with all. Familiar.", "What one suffers, all suffer! This is how it is with love also!", "One hurts. All hurt. Less hitting. More hurting.", "They share the suffering. It is a closeness. We are not jealous."],
  "wup:Bad Influence": ["One goes bad. It pulls the others. Fine by us.", "Turn the leader, the followers follow. Frame control. Textbook.", "One of them made bad choices. Now they all have to. Relatable.", "Turn one and the rest follow. Staff are like that.", "One unit reassigned. Partners following. Loyalty reading: 0%.", "That one's being naughty! They're all following! Silly!", "One leads the rest astray. One always has.", "One turns to our side and drags the rest! Yes! Bring them all!", "One possessed. Others follow. Drag them. Go.", "One is possessed and it brings the friends. Friends are like this."],
  "wup:Gossip": ["One cracks. They all crack. One hit, many cracks.", "Crack one, crack the brand. Reputation is everything. Let that sink in.", "Someone told everyone. Ugh. Not my fault. Useful though.", "Mention it to one of them and the whole house knows.", "Notification sent to all partners. Read receipts: 100%.", "He broke! And him! And HIM! All broke!", "Word travels. It travelled faster than this before, I think.", "One shell opens and all shells open! Tell everyone! Tell her!", "One cracked. News travels. All cracked.", "One shell is opened and the news is opening every shell."],
  "wup:Office Politics": ["They fight each other. We watch. Then we hit.", "Let them fight for the corner office. You stay above it. Sigma.", "They're arguing. Finally, someone else doing the work.", "Let them squabble. Staff always do when unsupervised.", "Internal dispute logged among targets. Their productivity: down 64%.", "Pushing! They're PUSHING! Can we push too?", "They argue over who started it. Nobody started it.", "They quarrel among themselves! Fools! Love should look like ours!", "They shove each other. Let them. Keep going.", "They have a falling out. It is a falling into each other."],
  "wup:Toxic Relationship": ["Kill one. The rest get hurt. Then kill them.", "Toxic? Cut them off. The ones left pay for it. Hard. Real talk.", "Break up with one. The others take it badly. Not my problem.", "Dismiss one and the rest feel it. That is rather the point.", "Relationship terminated. Partners notified with force. Thank you!", "SNAP! It went snap! Make it snap AGAIN!", "It ends badly. These things end the way they end.", "When it ends, it ends loudly! I would never end! Not with her!", "One dies. Tape snaps. Others hit. Hard.", "It ends with a snapping, and all are hurt. Such is a bad marrying."],
  "wup:Tangled": ["Snap. They pull together. Stuck. Easy to hit.", "Rebound relationship. Lock it in. Then lock it down. Nine out of ten.", "Now they're stuck together. Hope they like each other. They don't.", "Seat the survivors together. They deserve one another.", "Survivors consolidated into one unit. Shipping costs reduced.", "All knotted! Like hair! Knot them AGAIN!", "The ones left behind always cling. It is how they grieve.", "Bound together forever! Romantic! Now hit them while they are bound!", "Snap. Pulled together. Knotted. Hit them.", "The survivors are tied in a knot. A lovers knot, but angry."],
  "wup:Escalation": ["First snap. Second snap, bigger. Third, bigger.", "Every breakup makes you stronger. 76% stronger, minimum. Science.", "It gets worse every time. Like everything. Fine.", "Each dismissal more severe than the last. They will learn.", "Each break: stronger output. Escalation working as intended.", "Bigger! Bigger! Bigger SNAP!", "Each one is worse than the one before. I recall that.", "Louder! And louder! Each snapping a greater declaring!", "Snap. Bigger snap. Bigger. Keep on.", "Each snapping is louder than the last. All songs end in this way."],
  "wup:Lost in the Post": ["They tie us in too. We get hit. They share it.", "Outsource your pain. Real leaders delegate suffering. I wrote the book.", "Someone else can take some of this. For once.", "One does not take hits personally. Have them take a share.", "You are now part of a bundle. Incoming damage redistributed. Enjoy.", "We're tied too! We're IN it! Ow! Less ow!", "We were part of it all along. That part I remember.", "Let them carry our hurting! We must arrive whole for her!", "We are taped in. Hurt shared out. Go.", "We are posted with them. Our hurting arrives at their address."],
  "wup:Bureaucracy": ["Hit one. All of them get it. Almost all.", "Systems scale, effort does not. Build the system. Grindset.", "Paperwork does the work. I just sign. Barely.", "Hit one. The paperwork ensures everyone gets a copy.", "Every hit copied to every file. Forms processed: all. Have a great day.", "Everyone gets one! EVERYONE!", "It is a long process. It always has been.", "One blow, and every one of them feels it! Magnificent paperwork!", "One hit. All copies. Stamped. Filed. Next.", "Your one hitting is filed in every copy. The form is complete."],
  "wup:Small World": ["All of them tied. All of them. Always.", "Everyone is connected. Six degrees from losing to you. Ratio.", "Everyone knows everyone. Like school. Ugh.", "One knows everyone here. Everyone here works for one.", "All visible units linked. Network refreshing. Please do not switch off.", "Everybody holding hands! Everybody!", "Everything is connected. I knew that before I knew anything.", "All of them tied! The whole world is tied! And we are tied to her!", "All tied. Again. Again. Small world.", "It is a small world. Every one of them is tied. As are we."],
  "wup:Till Death Do Us Part": ["One dies. The weak ones die too.", "Loyalty is a liability. For them. Not for you. You are a free agent.", "They promised to stick together. Shouldn't have.", "Wherever one goes, the household follows.", "Linked units terminating together. Large units: heavy damage applied.", "Bye! And bye! And BYE!", "They said till death. They always mean it more than they know.", "Together until the death! As it should be! As it will be with her!", "One dies. Weak ones too. Big ones hurt.", "They vowed until the death. We are the death. We are punctual."],
  "wup:Big Bubble Trouble": ["Big one. Big bubble. Big one is stuck.", "Go after the elites. Rule six: a ten never settles for a four.", "One bubble. One big lump. Less swimming for me.", "Have the large ones wrapped. Gently. They're valuable.", "Large-item packaging enabled. Sealing time: extended. One at a time.", "BIG bubble! Biggest one! Put the big one IN!", "The large ones fit. They did not fit before. Did they?", "Even the great ones! Wrap them! I am too impatient for the closing!", "Big one. Bubble closing. Slow. Wait. Wait.", "We blow a bubble for the large guest. It takes a moment to close."],
  "wup:Locked In": ["In the bubble. Can't hit us. Can't heal. Good.", "Locked in. No distractions, no Membrane, no excuses. Grindset.", "Can't fight back. Same, honestly.", "Confined to quarters. No privileges.", "Contents secured. Attack function disabled. Membrane repair: 0%.", "It can't get out! Knock knock! HA!", "It cannot get out. I know how that is.", "It may not strike while it waits! Nothing may strike us! Nothing!", "Elite held. Cannot attack. Cannot mend.", "The elite is in the waiting. It may not attack in the waiting."],
  "wup:Cannonball": ["Pop it. It flies. It hits the others.", "Use the big one as a battering ram. That is called networking, bro.", "Didn't aim it. Hit them anyway. Meant that.", "Show the large one out. Through the others.", "Contents dispatched at speed. Collateral deliveries: several.", "WHEEE! It flies! Throw it AGAIN!", "It goes so far. Further than I remember things going.", "Throw the great one through them all! Bowl them over! Faster!", "Pop. Big one flies. Through them. Good.", "The elite becomes a cannon of itself. It bowls them like pins."],
  "wup:Bath Time": ["Soap. Skid. Faster. Go to the egg.", "64% of champions slipped once. Then they slipped faster.", "Bath time. Finally something nice.", "Have the floor polished. One prefers to glide.", "Surface friction: 3%. Speed: increased. Caution: wet floor.", "BATH! Splash! Bubbles! Bath AGAIN!", "Bath time. I have always liked bath time. I think.", "We skid! We hurry! A clean arriving for her!", "Soap. Slip. Fast now. Go.", "We wash and we go faster. Cleanliness is next to arrival."],
  "wup:Bubble Wrap": ["Bubble in the way. Shots hit bubble. Not us.", "Use your haters as a wall. Haters are a resource. Let that sink in.", "Hide behind it. That's not cowardice. It's planning.", "Use the staff as a screen. That is what they are for.", "Protective packaging installed. Fragile contents: you. Handle with care.", "Bubble shield! Can't hit us! NYAH!", "Hide behind them. We hid like this before, I think.", "Their bodies shield us! A noble use for them! We must reach her!", "Bubbles block shots. Stay behind. Hold.", "We put the guests between us and the shooting. It is courteous."],
  "wup:Chaperone": ["Bubbles come to us. They stand in front. Good.", "Hire security. Bubbles work for free. Unpaid interns. Elite move.", "It follows us around. Like a parent. Whatever, it's useful.", "One always travels with a chaperone.", "Escort assigned between you and nearest threat. Threat estimate: 71%.", "It's following us! Hi bubble! HI!", "Someone always comes along to keep watch. Someone did.", "A chaperone! Good! None will come between us and her but this!", "Bubbles come. Stand between. Shots stop.", "A chaperone floats between us. The courtship is proper now."],
  "wup:Spit It Back": ["Bubble eats shots. Then it spits them back.", "Absorb the hate. Return it with interest. Haters fund my content.", "Ugh, they threw this. They can have it back.", "Return it. One doesn't keep gifts from staff.", "Undelivered items returned to sender. No refund issued.", "Catch catch catch! THROW! Again!", "It all comes back. It all came back.", "They throw at us and it all comes back! Take your gifts back!", "Shots caught. Full. Pop. Sent back.", "We receive their gifts and then we return them. With feeling."],
  "wup:Snow Globe": ["Shots go in the bubble. They stay in. Done.", "Capture their output. Own it. Now it is your content. Monetise.", "It's pretty. Don't tell anyone I said that.", "Put their little shots in a jar. One likes a souvenir.", "Enemy shots held in storage. Shelf life: until popped.", "Shake it! Shake it! SHAKE IT!", "Little things floating inside. I had one like this once.", "Their shots trapped! Swirling! Let them swirl! We go on!", "Shots inside. Floating. Harmless. Go.", "The shooting is kept in a globe. It snows hittings. Lovely."],
  "wup:Pop Goes the Prawn": ["Bubble pops. Wave goes out. They all get stuck.", "Always exit with impact. Short tenure, big legacy. Sigma.", "Pop. Everyone's stuck. Nobody has to move. Perfect.", "Burst it. One may as well make an entrance.", "Package opened. Mucus wave released. All nearby units on hold.", "POP! Pop! Everything POP!", "Pop. That sound again. It is a good sound.", "Pop! And all are held still! Stay there while we pass!", "Pop. Wave. All stuck. Move.", "The bubble ends with a pop and everyone is held. A group embrace."],
  "wup:Popcorn": ["One pops. Next pops. Next pops. Three.", "Pop one, profit three. Compound returns. That is how millionaires think.", "They pop each other. I don't even have to pop them.", "Light one. The others will see to themselves.", "Chain detonation: 3 of 3 complete. Thank you for your patience.", "Pop pop pop pop POP! MORE!", "They go one after another. They always go one after another.", "Pop! Pop! Pop! Every pop is a cheer for her!", "Pop. Pop. Pop. Chain. Done.", "One pop gives birth to more popping. It is a family of pops."],
  "wup:Stuck Together": ["Wave hits. They stick. They can't split up.", "Pair them up. Couples are a three out of ten. Single is the move.", "Now they're stuck together. Have fun with that.", "Attach them to one another. Simplifies the guest list.", "Units conjoined. Two targets, one address. Efficiency: 100%.", "Sticky hug! Sticky hug! Hug FOREVER!", "Stuck together. That is how it goes, in the end.", "Glued together! Like lovers! Unlike lovers, hit them!", "Snared. Stuck together. Two as one. Hit.", "They are glued in a togetherness. We wish them a long one."],
  "wup:Bubble Gum": ["Pop. Sticky bit stays. Next one gets stuck.", "Leave a trap behind. Always. That is legacy. Build the legacy.", "Leave gum lying about. Someone'll get it in their hair.", "Leave it for the cleaners. Someone will tread in it.", "Adhesive residue deployed. Next visitor will be detained. Sorry!", "Gum! Gum! Someone swam in it! HA!", "Someone always steps in it. Someone will.", "Sticky! Let the next one be caught! Nothing follows us to her!", "Pop. Gum left. Next one stuck.", "The bubble leaves a chewing behind. The next guest is caught."],
  "wup:Cotton Wool": ["Bubble on us. Hits stop. Keep going.", "Protect the asset. You are the asset. Bubble-wrapped. High-value.", "Wrapped up in cotton wool. Finally. Leave me here.", "One is wrapped in cotton wool. As one has always been.", "Protective packaging renewed. Impacts absorbed: 3. Thank you!", "We're in a bubble! We're in it! Pop us! No! Don't!", "Kept safe. Kept too safe, perhaps. It is fine this time.", "Softness around you! No hitting may reach you! You are hers!", "Wrapped again. Hits stop. Go on.", "We are in the soft protecting. Nothing hits us before the meeting."],
  "wup:Bubble Boy": ["Any of them. Bubble. Straight away.", "No waiting. 100% close rate. Every time. That is called rizz.", "Instantly. Good, because I wasn't going to wait.", "No waiting. One does not wait.", "Instant packaging enabled. Wait time: 0 seconds. Thank you!", "In! In! In! All IN! Every one IN!", "So fast now. It took so much longer once.", "At once! No waiting! I have done enough waiting!", "Instant. Caught. No closing. Next.", "The bubbling is instant now. There is no closing. Only being closed."],
  "wup:Hamster Ball": ["Ball rolls. Hits one. Traps it. Again.", "Let them work for you. Free labour. Rolling free labour. Ten out of ten.", "They roll into each other. I sit here. Teamwork.", "Have them roll themselves over to the next guest.", "Contents rerouted to nearest recipient. Redelivery attempts: several.", "Roll roll roll! It's a HAMSTER! Roll again!", "Round and round. It rolls where it rolled before.", "Roll! Roll into your friend! And your friend! Go!", "Rolls. Hits one. Caught. Rolls again.", "The enemy becomes a ball and visits a friend. The friend is caught."],
  "wup:Any Day Now": ["Hit it. The clock goes fast. Hit it more.", "Do not wait for the date. Make the date come to you. Attract, never chase.", "Hurry it up, then. Not like I'm waiting for anything.", "Move the appointment forward. One's time is precious.", "Delivery window shortened with each hit. Estimated arrival: soon.", "Is it time? Is it time? IS IT TIME YET?", "Any day now. It was always any day now.", "Hit it! Hasten it! I cannot bear one more moment of waiting!", "Hit mark. Clock faster. Hit more.", "We hasten the appointment. Our hitting makes the clock impatient."],
  "wup:Early Delivery": ["Early is good. Early is more.", "Early adopters win. That is a law of nature. Look it up. Do not.", "Early? Me? Weird. Fine. It hits harder.", "Early. They should have arranged things for us anyway.", "Early delivery bonus applied. Contents: increased. Rating: 5 stars.", "It came early! Early! EARLY! Early again!", "Early this time. That makes a difference. It made one.", "Early is better! More! I want everything early!", "Early. More damage. Good. More.", "An early arriving gives more. We hope ours is early also."],
  "wup:Short Notice": ["Too early for it. It wobbles. Hit it.", "Hit them before they are ready. Ready is for betas. Sigma move.", "Nobody warned it. Nobody warns me either.", "No notice given. One needn't give notice.", "Early dispatch. Recipient off balance. Sorry for any inconvenience.", "Surprise! It fell over! SURPRISE again!", "No warning. There is never much warning.", "Too soon for it! It stumbles! Ha! Never too soon for us!", "Early. It staggers. Hit again.", "Short notice causes a stumbling. We are sorry for its stumbling."],
  "wup:Gender Reveal": ["Something happens. Don't know what. Something good.", "Every outcome is a win. 33, 33, 33. That is 100% winning. Maths.", "Could be anything. Don't care. Fine, a little curious.", "A surprise. How common. Still, it's ours.", "Package contents randomised. Surprise rating: 33% each. Enjoy!", "What is it? What is it? OPEN IT!", "You never know what it will be. You will not know this time either.", "A reveal! I adore a reveal! Is it a heal? It is a blast!", "Surprise. Blast. Or blood. Or mending.", "It is a reveal. Some exploding, some blood, some kindness. A party."],
  "wup:Double Booked": ["One clock goes off. Two more clocks. Count them.", "Rule three: never one date. Always three. Abundance mindset.", "More dates. More stuff to deal with. Just like life.", "Have the secretary book the next two. One is very popular.", "Overflow orders sent to 2 nearby recipients. Main order: reduced.", "Clock! Clock! Another clock! Clocks EVERYWHERE!", "One thing leads to another. It led to another before.", "More appointments! All of them! And still I keep the one with her!", "One goes. Two more marked. Smaller.", "We have many appointments. We are popular. We are double booked."],
  "wup:Forwarding Address": ["Clock goes off. Clock moves on. One more time.", "Pass the problem on. That is called leadership. Ten out of ten.", "Not mine. Give it to someone else. Like always.", "Pass it along. One does not hold parcels.", "Forwarding address on file. Redelivery attempts: 1 more. Thank you!", "Pass it! Pass it! Who's GOT it?", "It goes round and round. Someone is left holding it.", "Pass it on! Further! I would pass a thousand guests to reach her!", "Goes off. Moves on. Once more.", "The small marks are sent onward. Every letter finds its house."],
  "wup:Rush Hour": ["One. Two. Three. Third one is big.", "Stack your wins. Third win pays double. Fact. I read it somewhere.", "Everything at once. Typical. At least it hits hard.", "Everyone at once? How vulgar. How effective.", "Three deliveries in sequence. Third delivery: full value. Express.", "Boom boom BOOM! Three! THREE!", "It all comes at once. It always does.", "One, two, three! The third is the loudest! I love the third!", "Three quick. Third full. Good.", "Three arrivings together. The third arriving is the loudest."],
  "wup:Morning After": ["It runs away. It still goes off.", "Running from consequences? Not on my watch. Accountability, bro.", "You can't just leave. I tried that. It doesn't work.", "Leaving early? One settles the bill before one goes.", "Recipient left the delivery area. Package released immediately.", "Where'd it go? BOOM! It went boom!", "You cannot outrun the morning. It catches up.", "It flees! It cannot flee what we promised it! It goes off now!", "Leaves view. Goes off. Now.", "It tries a leaving in the night. The morning after arrives anyway."],
  "wup:Interest Accrued": ["Long wait. Big hit. Wait. Wait. Hit.", "Delayed gratification. Top earners wait. Then they eat. Grindset.", "Waiting is my best skill. Finally it pays.", "Let it mature. Old money is patient money.", "Delivery time doubled. Payload increased. Thank you for your patience.", "Is it done? Is it done? Not yet? NOW?", "The longer it waits the more it gives back. That I know.", "So long! Too long! But so much at the end! I can wait! I cannot!", "Slow clock. Big return. Wait.", "We wait long for a large return. We are good at long waiting."],
  "wup:Inheritance Tax": ["Number goes up. It dies. Number goes on the others.", "Watch the number. Love the number. Be the number. Generational wealth.", "Even dying early, it pays out. That's my kind of plan.", "Dying before payment? The estate pays.", "Balance displayed. Early closure: balance shared with neighbours.", "Big number! BIGGER! It popped! Big boom number!", "It grows while we are not looking. It grew.", "Look how it grows! And if it dies, the neighbours pay! Justice!", "Total shown. Dies early. Neighbours pay.", "The debt grows. If the debtor dies, the neighbours inherit it."],
  "wup:Fine Print": ["Big one. Mark goes off. Mark again.", "Read the fine print. Then write it. Then enforce it. Locked in.", "Should've read the small print. Not my problem.", "It's in the contract. They should have read it.", "Auto-renewal enabled on large accounts. Maximum renewals: 2.", "Again! The clock's back! AGAIN!", "There is always more in the small print. I read it this time.", "Again! The big ones get another! They must never escape!", "Big one. Marked again. Twice.", "There is a small writing. It says: one more appointment."],
  "wup:Postponed": ["Big hit. Not now. Later. Smaller.", "Pain is a delayed invoice. And you negotiated it down. Alpha move.", "Can't deal with this right now. Later. Maybe.", "Have it rescheduled. And halved, naturally.", "Incoming impact rescheduled. Size reduced 50%. Thank you for waiting.", "Not yet! Not YET! Okay. Ow. Little ow.", "It hurts less if it waits. It did before, too.", "The hurting can wait! Everything can wait except her!", "Big hit. Delayed. Halved. Fine.", "The hurting is postponed. It arrives later in half the size."],
  "wup:Labour Day": ["Clock goes off. New clock. Clock goes off. New clock.", "The grind never stops. Eighteen-hour shifts. Sleep is cope.", "Over and over. Like chores. Endless.", "Have them work every day. Bank holidays included.", "Subscription renewed automatically. Cancellation: unavailable.", "Again and again and AGAIN and again!", "It comes round again. It always comes round.", "Again and again! Without rest! My devotion also has no rest!", "Goes off. Marked again. Again.", "The labouring is endless. Each ending is a beginning. Push."],
  "wup:The Big Day": ["Three marks. Hit them hard. Big day.", "Three dates at once. A high-value man keeps his options open. Rotation.", "Everyone keeps saying it's a big day. Fine. It's a big day.", "It is our big day. Naturally, everyone is invited to suffer.", "Priority tracking: 3 recipients. Damage to marked: increased. Hooray.", "Big day! BIG DAY! Is it our birthday?", "The big day. I have waited for this before.", "The big day! Flowers! Hittings! Three at once! Oh, the big day!", "Three marked. All hit harder. Big day.", "It is the big day. The flowers, the marking, the many hittings."],
  "wup:Induced": ["One mark. Long wait. All of it back.", "Force the timeline. Winners do not wait for nature. Nature waits.", "Rare, but when it goes, it all goes. My kind of effort.", "Have it induced. One has a schedule to keep.", "Full payload released. Next dispatch in 10 seconds. Please hold.", "Is it coming? It's coming! It's ALL coming!", "Sometimes it needs a push. This one needed a push.", "All of it! At once! Bring the arriving now!", "All at once. Then wait. Ten.", "We induce the arriving. All of it arrives at once."],
  "wup:Family Planning": ["Kill one. Get one. More of us.", "Build a dynasty. Quantity is a quality. 73% quality. Patriarch energy.", "More siblings. Great. More people to share a room with.", "One plans for a large family. Large estates need staff.", "Additional units shipped with every kill. Unit quality: reduced.", "Babies! More babies! Make MORE!", "So many of them. There were always going to be so many.", "More children! With every kill! Such a family we will have!", "Kill. New seeker. Weaker. More.", "The family is planned. Every ending makes a new one. Congratulations."],
  "wup:Runts of the Litter": ["Small ones. Fast ones. Still ours.", "Small but hungry. Height is cope. Hunger mogs size.", "The little ones do all the running. Fair.", "The smaller ones fetch things. That is what they are for.", "Compact models dispatched. Speed: +40%. Size: -40%.", "Tiny ones! Zoom! Tiny ZOOM!", "The small ones last the longest. I have noticed.", "Little and quick! Quick like my devotion! Go, little ones!", "Small ones. Fast ones. Go.", "The runts are quick. Small hittings, fast arrivings."],
  "wup:Overcrowding": ["More room. More of them. More.", "Scale the team. Never stop hiring. Rule five: headcount is power.", "It's crowded. Everyone's in my space. Whatever, they're useful.", "The house is full. Hire more house.", "Fleet capacity increased. Units in flight: more. Traffic: heavy.", "So many! So MANY! Is that all? More!", "A full house. It is always full.", "More, more! Fill the house! I want a full house for her!", "More seekers. Crowded. Good.", "The house is overcrowded. In our custom, this is wealth."],
  "wup:Hide and Seek": ["Lost it. Wait. Next one comes. Get it.", "Lie in wait. Do not chase. Attract. Then ambush. Basic.", "Lost it? Just wait there. Something'll come.", "Have them wait in the hall. Someone will come along.", "Unit on standby. Ambush probability: 92%. We appreciate your patience.", "Ready or not! Here we come! FOUND you!", "Hide and wait. I am good at waiting, I think.", "They hide! They pounce! Oh, how they pounce!", "Lost target. Hides. Waits. Strikes.", "The siblings hide. Then they find. This is a game of seeking."],
  "wup:The Favourite": ["Weak one first. Then the next weak one.", "Low-hanging fruit. Pick it. Winners farm easy wins. Frame.", "Going for the easy ones. That's not lazy. That's efficient.", "Pick on the feeble. They expect it.", "Targeting: weakest available. Large threats: ignored. Efficient.", "That one's broken! Get the broken one!", "The weak go first. They did then. They will now.", "The weakest first! Quickly! We have no time for the big ones!", "Weakest first. Ignore big. Go.", "The favourite is the weakest. In our family also. It is a kindness."],
  "wup:Taste for It": ["It got one. It hits harder now.", "Winners compound. One kill becomes a habit. Habits become empires.", "Got a taste for it. Don't make it a thing.", "They develop an appetite. Let them dine.", "Post-kill performance boost applied. Unit enthusiasm: 88%.", "Yum! More! It wants MORE!", "Once it has the taste, it does not let go.", "It has tasted! It wants more! It is hungry as I am hungry!", "Kill. Next hit harder. Good.", "The sibling has a tasting. It wishes a second course."],
  "wup:Nepotism": ["Two kills. Three of them. Good sum.", "Reward performers. Promote from within. Hire their kids. Legacy.", "Favourites get more. Story of my life.", "Of course the family gets more. That is what family is for.", "Loyalty reward unlocked: 3 units per split. Your satisfaction matters.", "Three! Not two! THREE! Do three again!", "The favoured ones do well. They always have.", "Three! The proven one gets three! Reward them! Reward them all!", "Proven seeker. Kill. Three split.", "The proven sibling gets three children. This is our inheritance law."],
  "wup:Sibling Squabble": ["They bump. They split up. More targets.", "Healthy competition. Let them fight for the bonus. Nine out of ten.", "They're fighting. Again. Nobody tell Mum.", "Separate them. They can go and annoy different people.", "Collision detected. Units rerouted to separate targets. Resolved.", "MINE! No, MINE! Bump! Both go!", "They argue and then they go their own ways.", "They quarrel and then go apart! More ground! More hitting!", "Bump. Split up. Different targets.", "The siblings disagree with their bodies. Then they choose apart."],
  "wup:Sibling Rivalry": ["All on one. All hit it. Big hit.", "Competition breeds excellence. 88% of excellence. Mog each other.", "They all want to be best. Exhausting. Effective.", "Let them compete for one's attention. It's charming.", "Shared-target bonus active. Splitting: discontinued. Noted.", "Everybody get it! Everybody! GET IT!", "They push each other to be better. It works, eventually.", "All on one! They fight to hurt it most! Such fierce children!", "Same target. More damage. No splits.", "The siblings compete in a pile. Their love is a sharp love."],
  "wup:Pack Hunting": ["All go to one. Same one. Every time.", "Wolves hunt in packs. You are a wolf. Basically. Alpha wolf.", "Everyone picks the same one. Less thinking. Fine.", "One points. They all go. As it should be.", "All units routed to a single recipient. Consolidated delivery.", "That one! Everybody! THAT one!", "They hunt together. We hunted together, once.", "All together on one! A pack! A family of teeth!", "One target. All seekers. Converge.", "The pack has one thought. It is a polite thought. It is to kill."],
  "wup:Pile-On": ["Four hit it. Full bleed. Fast.", "Four on one. That is not bullying, that is the market. Real talk.", "Everyone's on it. I'll just join in. Last.", "Have them all see to it at once.", "Four units on one recipient. Bleed applied: full. Bulk discount.", "PILE ON! Us too! Us TOO!", "Everyone at once. That is how it ends for most.", "Everyone on it! Pile! Pile! It bleeds all at once!", "Four on one. Full Bleed. Next.", "A piling is happening. The bleeding is complete. How generous."],
  "wup:Dinner Time": ["It got three. It comes back. We get a bit.", "Provider energy. It brings the food home. Eggs love a provider.", "Bringing food back? Fine. Leave it there.", "They bring supper to one. As they should.", "Return delivery: nutrients. Minor repair applied. Enjoy your meal!", "DINNER! Is it dinner? It's DINNER!", "It brings something home. Someone always did.", "It comes home with dinner! A good child! A good, good child!", "Three kills. Comes home. Mends us.", "The sibling returns with the dinner. It is family dining."],
  "wup:Breeding Like Rabbits": ["Every hit. Two more. Lots of them.", "Exponential growth. The only kind I respect. Let that sink in.", "So many babies. Too many. Whatever, they do the work.", "An heir and a spare. And a spare. And a spare.", "Replication on every hit. Inventory: rising. Stock control: abandoned.", "Babies! BABIES! So many BABIES!", "So many. There were never this many, before.", "Every hit a child! So many children! She will be so proud!", "Every hit. Split. Split. Many.", "Every hitting is a birth. The family grows as families do."],
  "wup:Family Reunion": ["Missed. Come back. Go again.", "Family first. Then crush the competition. Then family again.", "They always come back. Can't get rid of them.", "The family returns. They want something, presumably.", "Missed deliveries returned to depot. Shots intercepted. Redispatching.", "They came back! Hi! HI! Go again!", "Everyone comes home in the end. Then they leave again.", "They come back to us! They guard us! Then they fly again! Family!", "Missed. Circle us. Eat shots. Go.", "The family reunites round us. They eat the shooting. Then they go."],
  "wup:Only Child": ["Just one. It does it all.", "One elite performer. No passengers. Ten out of ten. That is the dream.", "Only one. Gets all the attention. Must be nice.", "One heir. Everything goes to the heir.", "Single premium unit dispatched. Pierce rating: total. Persistence: high.", "Just ONE? Only one? Biggest one! GO!", "Only one. There was only ever one, every time.", "One child, and all my love in it! Go, and do not stop!", "One seeker. Hits hard. Goes through. Keeps going.", "One child only. All the hitting is given to one. It is spoilt."],
  "wup:Peek-a-Boom": ["They go to the fake us. The fake us explodes. Good.", "Rule one: leave a decoy. Let them simp for the wrong you. Boom.", "They wanted me so badly. Have the version that blows up.", "Let them queue at the decoy. It does the receiving.", "Decoy unit deployed. Crowd detected. Detonation: scheduled. Enjoy!", "Pretend us! Pretend us went BANG! Make another one!", "They will crowd the empty place. They always have.", "They embrace the shape we left! Let it burst for her!", "Shape left behind. They gather. It bursts. Continue.", "They embrace the shape we leave. The shape is an exploding."],
  "wup:Standing Room Only": ["More of them come. Bigger bang. That is the plan.", "Seven on the decoy. Crowd rating: nine. Your frame did that.", "Oh, a party. For me. How awful. Explode it.", "A full house. One does draw a crowd.", "Attendance at decoy: 7 units. Blast radius scaled to demand. Thank you!", "Lots! LOTS! Bigger boom with more! MORE!", "Full room, bigger noise. You knew that already.", "More guests! More fire! Let the whole wedding burn for her!", "Many guests. Bigger fire. Good.", "The more guests at the wedding, the larger the fire. This is custom."],
  "wup:Long Goodbye": ["It goes off. Then it goes off again. Two.", "Leave twice. High-value men never take just one exit. Fact.", "Yeah, it does it again. I'm not getting up for it.", "Ask it to stay for the second sitting.", "Decoy lingering. Second detonation queued. Your satisfaction matters.", "Again! It did it AGAIN! Do it again again!", "Again. It does that. It always did that.", "The false us will not leave! It bursts again, for love of her!", "Decoy stays. Bursts twice. Do not wait for it.", "The false us bows, and then explodes once more. A generous guest."],
  "wup:Rattle": ["Throw the toy. They chase the toy. We go.", "Toss them a toy. Chasing noise is beta behaviour. You? Locked in.", "Here. Go play with that. Leave me alone.", "Give them something to amuse themselves with. Staff get restless.", "Audio lure dispatched. Threat redirection: 88%. Have a lovely day.", "Mine! My rattle! No, you have it! THROW IT!", "Shake it once, far away. Everyone looks. You remember that sound.", "We hurl the noise far away! Let them chase it! She waits for us!", "Noise thrown. They follow. We do not.", "We throw the noise far. They follow the noise. They are not wise."],
  "wup:You Can't See Me": ["We hide. They shoot. They miss. Keep hiding.", "Seventy per cent of winning is not being there. That is sigma maths.", "Not here. Not doing this. Shots can go through, whatever.", "One is not at home to callers.", "Visibility: 0%. Incoming fire passing through. Thank you for your patience.", "Eyes closed! Can't see us! CAN'T SEE US!", "They look straight through you. They looked through you then, too.", "Their shootings pass through us! Nothing touches us but her!", "Unseen. Shots pass through. Stay unseen.", "Their shootings pass through our absence. Absence is a good coat."],
  "wup:Silent Running": ["Hidden. Swim fast. Stay hidden. Swim fast.", "Move in silence. Grindset. Let the results do the mogging.", "If I have to swim, I'll swim where nobody can watch.", "Leave quietly. One never makes a scene leaving.", "Stealth mode active. Swim speed: increased. No action required.", "Sneaky fast! Sneaky FAST! Shhh! FAST!", "Quiet and quick. You were always faster when nobody looked.", "Quiet and quick! Every hurrying brings us closer to her!", "Hidden. Faster. Nobody hears.", "We are a silence that travels at speed. Nobody hears the hurrying."],
  "wup:Sneak Attack": ["They look over there. We hit from here. Simple.", "Hit from the blind spot. Winners never announce. Losers post about it.", "Technically I'm not here. Technically I'm also hitting you.", "One prefers not to be seen doing the work.", "Decoy absorbing attention. True position firing. Customer confusion: 97%.", "Peep! Hit! Peep! Hit! They don't know it's us!", "From behind, quietly. It hurts more when nobody saw it.", "We strike from where we are not! Let them feel our longing!", "Decoy watched. We shoot. From elsewhere. Harder.", "We strike from the place where we are not. It is a strong place."],
  "wup:Mirror, Mirror": ["Two fake us. Half go here. Half go there.", "Two of you. Double the value. A ten would swipe both. Probably.", "Two of me. Both of them can deal with it.", "One rather likes there being two of one.", "Decoy count: 2. Hostile attention split evenly. Thank you for choosing us.", "Two of us! Twins! Hello me! Hello other me!", "Two of you. There was only ever one, though.", "Two false faces! Neither is ours! Only she will know the true one!", "Two decoys. They split. Swim on.", "Two false shapes. Neither is the true face. Only the Other Half knows."],
  "wup:Boo!": ["Hide. Come back. Say boo. They run.", "Fear is respect, fast-tracked. Real talk: they should be scared of you.", "Oh no, it's me. Run. Whatever.", "Make an entrance. They will clear the room.", "Reappearance alert issued. Hostile fear response: 100%. Hello!", "BOO! Again! BOO! They runned!", "Step out softly. They still scream. They always do.", "We burst out at them! Run! Run, for we are coming to her!", "Out now. They flee. Keep going.", "We arrive and they depart. This is how a surprise is done."],
  "wup:Tell a Friend": ["One is scared. It bumps one. Now two are scared.", "Panic is viral. Let them do your marketing. You are the content.", "Great. Now they're all upset. Not my fault.", "Gossip. Let the staff tell each other.", "Fear notification forwarded to nearby hostiles. Sharing is caring!", "Scary! You're scary too! Everyone scary! TAG!", "Fear travels hand to hand. It always found its way round.", "Their fright leaps from one to the next! Let it run wild!", "Fear spreads. One to one. Good.", "Their fear is passed between them like a bowl at a meal."],
  "wup:Stampede": ["They run. They crash. They don't attack. Good.", "Sixty-four per cent of losers trip over other losers. Stay in your lane.", "Running into each other. Mature. Very mature.", "Clumsy staff. They'll be docked for that.", "Hostile collision logged. Their next attack: cancelled. So sorry!", "Bonk! BONK! They bonked! Do bonk again!", "They collide. You saw them collide before it happened.", "They flee into each other! Let them tumble! We do not stop!", "They collide. They falter. Pass them.", "They flee into one another. It is a dance with no teacher."],
  "wup:Cuckoo": ["Come back. Swap with one. It is there. We are here.", "Take his spot. Hypergamy, but for positions. Let that sink in.", "Fine, you have my spot. I'll have yours. It's worse.", "Ask that one to move. That's our seat.", "Position exchange complete. Previous occupant relocated. No refunds.", "Swap! You're me! I'm you! Again swap!", "Someone else's place. You have slept in other nests.", "We take their place! Nothing stands between us and her!", "Swap made. Their place. Ours now.", "We exchange places. On our world this is how one proposes."],
  "wup:Object Permanence": ["Gone. Back. Gone. Back. Everyone hears it.", "Be everywhere. Be nowhere. Brand presence: ten out of ten.", "I'm gone. I'm back. I'm gone. Stop asking.", "One comes and goes as one pleases. Everyone notices.", "Broadcast range: full. All hostiles notified of your arrival. Hi!", "Where'd we go? HERE! Where'd we go? HERE!", "Gone is not gone. You learned that a long way back.", "Our returning is heard by all! Let the whole world shake for her!", "Gone often. Back loud. Everywhere hears.", "We are and we are not. Everyone hears our returning."],
  "wup:Mass Hysteria": ["Boo. Five of them are ours now.", "Five new followers off one scare. That is called audience capture.", "Five of them are possessed now. They can do my bit.", "Five new hires. Possessed, but then most of them are.", "5 hostiles reassigned to our network. Welcome aboard! Trust: 12%.", "Scared and now they're FRIENDS! Five friends!", "Fear opens a door. Sometimes someone walks in.", "Five of them are ours now! Our devotion is catching!", "Five turned. Ours now. Proceed.", "We startle five of them so deeply that they become ours."],
  "wup:Now You See Me": ["Hidden. Boo. Hidden. Boo. That is the plan now.", "Scarcity is value. Show up a quarter of the time. Like a ten does.", "Hidden three seconds in four. Finally, a schedule I like.", "One is rarely seen, and always remarked upon.", "Visibility: 25%. Every appearance a scheduled surprise. Enjoy!", "Peek! BOO! Peek! BOO! Forever!", "Mostly unseen. That was always the comfortable part.", "We hide and we leap, over and over! She will hear us coming!", "Hidden. Out. Boo. Hidden. Repeat.", "We are mostly an absence. Our arrivings are loud."],
  "wup:Nest Egg": ["They take one. They make one. Now there are more.", "Passive income. Bait that breeds bait. You sleep, it grinds.", "It makes more of itself. Like chores.", "Money makes more money. It does that for us.", "Lure replication enabled. Each customer generates a new lure. Thank you!", "Another one! It made a baby one! Shiny baby!", "One leads to one leads to one. You know how that goes.", "Every greedy one gives birth to more bait! How fertile our trap is!", "Bait breeds bait. More every time.", "Each greedy one gives birth to new bait. A fertile trap."],
  "wup:Bigger Basket": ["Six now. Not three. Six.", "Six lures beats three. Basic maths. Abundance mindset, bro.", "Six of them to look after. Brilliant. Thrilled.", "Do lay out the full set.", "Lure capacity: 6 (was 3). We appreciate your custom.", "Six shinies! Count! One two six!", "Six on the ground. It is enough. It was always enough.", "Six gifts on the floor! We give and give! Our heart is enormous!", "Six lures down. Enough. Move.", "Six small promises lie on the floor. We are generous."],
  "wup:Triple Yolk": ["Three taken. Fast. Big hit in the middle.", "Three is the most powerful number. There are studies. I did them.", "Three at once? Who's that organised? Not me.", "Three at the table. One bill. Everyone pays.", "Triple pickup detected. Triangle strike executed. Efficiency: 300%.", "One two THREE! BIG ZAP! Three again!", "Three at once. The space between them burns. Yes.", "Three take the bait together! Strike them all, and all between!", "Three taken. Triangle strikes. All between.", "Three graspings at once make a triangle of hitting. Beautiful."],
  "wup:Surprise Inside": ["It goes under. It comes up. It hits.", "Don't wait for the market. Take it to them. Cold approach.", "It goes to them. So I don't have to. Good.", "Have it delivered to their door.", "Subterranean delivery selected. Arriving beneath recipient now.", "Where'd it go? UNDER! Surprise! Pop!", "It comes up beneath them. Things always come up.", "The gift tunnels to them! It cannot wait! Neither can we!", "Gift goes under. Comes up beneath them.", "The gift travels under the floor and emerges as a greeting."],
  "wup:Egg On": ["They want it. They go to it. Not to us.", "Rule two: don't chase, attract. Works on them. Works on eggs. Mostly.", "Go on then. Chase that. Leave me out of it.", "Dangle something. They will forget all about one.", "Lure range doubled. Hostile interest in you: 0%. Please do not worry.", "Look! Over there! Shiny! Not us! Go!", "They forget you the moment something glints.", "Let them hunger for the glittering! Our hunger is only for her!", "Bait shown. They forget us. Swim.", "We show them a glittering, and their hunger forgets us."],
  "wup:Egg Trail": ["Drop one behind. Keep going. Drop one behind.", "Leave a trail of opportunity. Haters follow. Haters pay.", "I'll just leave this here. And this. And this.", "Leave something for the help to pick up.", "Lures dispensed along route. Followers receive a complimentary hit.", "Drop! Drop! Drop! It's a trail! Follow!", "Crumbs behind you, so the others do not follow you home.", "We leave gifts behind! Those who chase us will regret the chasing!", "Gifts dropped behind. Followers punished.", "We leave small gifts behind us, so those who follow are punished."],
  "wup:Golden Opportunity": ["Gold one. Everyone looks. Everyone goes.", "Show them a ten. Watch every one of them lose frame. Weak.", "Ooh, shiny. Not for me. For them. Whatever.", "Gold. Naturally they flock to it.", "Premium lure deployed. Attention captured: 100% (bosses excluded).", "GOLD! GOLD ONE! Can I? Can I? Touching it!", "Everyone runs for the gold. Nearly everyone.", "A golden false bride! Let them all propose! We are faithful to her!", "Gold lure. All look. Not at us.", "The golden one is a false betrothed. They all propose to it."],
  "wup:Broody": ["One, two, keep three. Three hits a big one.", "Hold one back. Invest in the high-value target. Long game.", "Keeping this one. Sitting on it. Don't ask.", "One keeps the third for oneself.", "Every third lure reserved. Priority recipient: elite. Delivered!", "Mine! This one mine! Sit sit sit. ZAP!", "Sit with it a while. It knows where to go.", "The third one is ours to cherish! It hatches angry, and so are we!", "Third one kept. Hatches. Hits the big one.", "We warm the third one ourselves. It hatches into a smiting."],
  "wup:Don't Count Your Chickens": ["Wait. It gets bigger. Wait more.", "Delayed gratification. 97% of men can't. You can. Mewing helps.", "Waiting is basically what I do best. Finally.", "One lets it mature. Like a good wine.", "Lure charging. Please hold. Your hit is important to us.", "Is it ready? Is it ready? Is it ready NOW?", "Leave it. It gets better. Most things did.", "Wait! Let it ripen! We can hardly bear the waiting!", "Leave it. It ripens. Then strike.", "We let the bait ripen. Patience is a fruit on our world."],
  "wup:Warm Glow": ["It waits. It glows. It hits more.", "Glow up. Then hit the whole room. Looksmaxxing, but with damage.", "It's glowing. Good for it. Someone should.", "Do let it warm through. One hates things served cold.", "Lure fully charged. Glow indicator: on. Area effect included free.", "Glowy! It's warm! Can I hold it? OW!", "It is warm. Things you keep long enough get warm.", "It glows like our heart does! Let everyone nearby feel it!", "It glows. It hits all near.", "The bait blushes. When it blushes, all near it suffer."],
  "wup:Time Bomb": ["Nobody takes it. It explodes. Fine.", "Nobody took it? Their loss. Literally. Ratio.", "Nobody wanted it? Fine. Then nobody gets anything.", "Unclaimed? Have it destroyed.", "Package unclaimed. Returning to sender, explosively. Sorry we missed you!", "Nobody? NOBODY? Then BOOM! Ha!", "If nobody takes it, it ends anyway. Everything does.", "They ignore our gift? Then the gift ignores their living!", "Not taken. It bursts. All near.", "Ignored, the gift becomes a grief for everyone around it."],
  "wup:Egg on Your Face": ["It hits us. It gets one. Then it gets hit.", "Took a hit? That's content. Monetise it. Not a loss, a lesson.", "You hurt me. Here's a present. It's not a nice one.", "Have something sent round to whoever did that.", "Damage received. Complaint filed. Lure delivered to responsible party.", "Ow! OW! You get one! Ha! Your face!", "It hurt. Leave it something. It was always going to hurt.", "Who struck us? Take this bait to your feet! For her honour!", "Hit taken. Gift returned. Unkind.", "You wound us, so we gift you. Our gifts are not kind."],
  "wup:Golden Goose": ["One gets hit. All near it get hit. Good.", "One sale and the whole room pays. That is scaling. Let that sink in.", "Everyone gets one. Equal. Whatever. Done.", "Splash out. One can afford it.", "Area smite enabled. All nearby hostiles included in your order.", "Zap one! Zap ALL! All of them zapped!", "It never lays just one, does it.", "One smiting for all! Every one of them shall feel our passion!", "One smite. All around. Full.", "One smiting becomes a smiting for the whole family."],
  "wup:Clutch": ["Two at once. Lots on the ground. All round.", "Twelve options on the board. Never be scarce. Sigma rule.", "So many. Everywhere. I'm not picking them up.", "Have them laid out around one. Dozens.", "Lure stock: 12. Distribution: all directions. Thank you for shopping.", "So many shinies! All round! Twelve! Is twelve big?", "A full nest around you. You have been surrounded like this.", "Twelve false brides around us! None are her! We do not even look!", "Lures everywhere. Twelve. Keep swimming.", "We are encircled by false brides. None are her. All are bait."],
  "wup:Possession Fee": ["They take it. They are ours now.", "Take the bait, sign the contract. Ownership is earned. Respect it.", "Touch it and you work for me now. Rules.", "Take what's ours and you're ours. Standard terms.", "Bait accepted. Terms and conditions apply. New asset onboarded.", "You touched it! Now you're mine! MINE!", "Whoever takes it is taken. That has always been the price.", "Whoever touches our gift is ours forever! We are so very generous!", "Bait taken. They are ours. Next.", "Whoever grasps the gift is bound to us. A small marriage."],
  "wup:The Family Business": ["Dead ones help. They stay longer now. Fewer of them.", "Build a team that stays. Loyalty is a metric. Three max. Elite.", "They follow me around now. For ages. Great.", "A small household, but a loyal one.", "Escort units: 3. Duration doubled. Loyalty: unverified, 41%.", "Friends! Dead friends! They stay! Play with us!", "They walk with you longer. Family does, eventually.", "Our fallen stay beside us! They fight harder! They love us!", "Three dead. Ours. Longer. Stronger.", "The fallen accompany us for a long while. They are our kin now."],
  "wup:The Staff": ["They come with us. They fight here.", "Keep your entourage close. Optics. A king never walks alone.", "Stop following me. Fine. Follow me. Whatever.", "The staff travel with one. Obviously.", "Escort mode: follow. Please keep your units with you at all times.", "Follow! Follow me! Everybody follow! Line!", "They keep up now. That is new. Or it is not.", "Walk with us, our dead! To her, all of us, together!", "Dead follow. Fight near us. Good.", "Our dead servants walk beside us like a wedding procession."],
  "wup:Foster Care": ["First big one stays. All wave. Then it goes.", "Rule three: recruit one heavy hitter per season. Bench the rest.", "I'll look after this one. Until the wave ends. Then no.", "A temporary appointment. Rather senior.", "Elite converted. Contract length: one wave. Renewal not available.", "Big one's ours! Can we keep it? Just for now?", "It stays only a while. That is how it is meant to be.", "The large one is ours! Only for a little while! Love it fiercely!", "Big one turned. One wave only. Use it.", "The large one is ours for one season. A short courtship."],
  "wup:Doggy Bag": ["Dead ones bring the shiny things. To us.", "Delegate the small stuff. You are the talent. Talent does not fetch.", "Someone else can pick that up. Finally.", "Have them bring it to one.", "Gem collection outsourced. Courier rating: 4.8 stars. Thank you!", "Fetch! Good dead! Fetch again!", "They bring things back. Things come back.", "Our fallen bring us treasure! They are so loyal! We adore them!", "Dead fetch gems. Back to us.", "The fallen fetch our treasure like faithful hounds of the house."],
  "wup:Contagious Personality": ["They bite. It spreads. More of ours.", "Your energy is infectious. Make it everyone's problem. Main character.", "Don't come near me. Oh. Too late.", "One's charm is simply catching.", "Infection now spreading. Escort lifespan: brief. Thanks for understanding.", "Bitey! They bited! Now they're ours! Bite again!", "It passes along. Everything passes along.", "Our dead bite with our affection! Let it spread to all of them!", "Dead bite. They infect. Short lives.", "Our dead pass on our affection with their teeth."],
  "wup:Chronic Condition": ["Infected. Stays infected. Until dead.", "Commitment issues? Not us. Once it's in, it stays in.", "It never goes away. Relatable.", "A lifelong membership. Non-refundable.", "Infection duration: permanent. Cancellation policy: none.", "Forever! It stays forever! Forever and ever!", "Some things stay with you. This stays with them.", "An infection without end! Like our devotion! Forever!", "Infected. Until death. No cure.", "Infection without ending. On our world this is called a vow."],
  "wup:Open Casket": ["It dies. It gets up. It infects two.", "Every exit is an onboarding. Grow the network. Death is just churn.", "Even dying doesn't let you lie down. Tell me about it.", "Everyone attends the funeral. Everyone catches it.", "Deceased hostile reactivated. Two neighbours added to infection list.", "Up! Get up! You're up! Bite two!", "It lies down and gets up again. You know the feeling.", "They die and they rise again! Our love does not stay buried!", "Infected dies. Rises. Two more.", "At the burying, the guest rises and greets two others."],
  "wup:Hookworm": ["It grabs on. It bites. It stays on.", "Lock in. Never let go of the deal. That is the grindset.", "Clingy. Not my type. Works, though.", "One never swims if one can be carried.", "Unit attached to host. Biting continues until delivery is confirmed.", "Piggyback! Ride it! Bite bite bite!", "Hold on. It is easier to be carried.", "Hold on and never let go! Bite until the very end!", "Dead latch on. Bite. Ride it down.", "Our dead ride their hosts like a groom on a horse."],
  "wup:Dead Useful": ["Dead ones walk in. Dead ones pop.", "Even your losses pay dividends. Not that you have losses.", "Fine, go and explode. Not like you were busy.", "The staff are expendable. That is rather the point.", "Escort units now dispatched as packages. Detonation on expiry. Enjoy!", "Walk walk walk POP! Do pop again!", "They go into the crowd and do not come out. That is fine.", "Our dead run into the crowd and burst! What a glorious goodbye!", "Dead walk in. Expire. Burst.", "Our dead walk to the crowd and become an exploding gift."],
  "wup:Soul Searching": ["Pop. They get a bit of ours. A bit more.", "Every hit builds the brand. The brand is you. Ten out of ten.", "They'll go weird eventually. Not my problem.", "One leaves an impression on everyone.", "Burst residue applied. Conversion progress: 38% and rising. Lovely.", "Pop! Now they're glowy! Glowy pop!", "It leaves something in them. Things always leave something.", "Let them burn with what we are! Let it fill them up!", "Burst marks them. They turn soon.", "Each exploding plants a little of our soul in them."],
  "wup:Remote Detonation": ["Wait. All go. All pop. Wait.", "Coordinated launch. Everyone hits the market at once. Locked in.", "Everyone go at once so it's over quicker.", "Have them all go at once. Less fuss.", "Scheduled group dispatch: densest cluster. Arrival: now. Thank you!", "Everybody run! All together! BOOM all!", "All of them at once. It is quicker that way.", "All of them, together, charge! Burst for her!", "All dead. Biggest crowd. Go.", "Our dead hurry together. It is a parade that explodes."],
  "wup:Gut Feeling": ["Red means it hits soon. Move.", "Read the room. 88% of winning is reading tells. The rest is jawline.", "Red. Yes. I saw. I'm moving. Slowly.", "One always knows when the staff are about to be difficult.", "Hostile intent detected. Warning indicator: red. Attack imminent.", "Red! Red means OW! Go away red!", "You see it before it happens. You have had that feeling.", "They flash red! We see their hearts! Strike first!", "Red flash. Attack coming. Move.", "Their insides warn us of their intentions. Very polite insides."],
  "wup:Zombie Apocalypse": ["Twelve dead ones. Twelve. That is a lot.", "Twelve-man team. You are the CEO of death. Competition: ratioed.", "So many. They can do everything. I'll watch.", "A proper household at last. Twelve.", "Escort capacity: 12. Unit loyalty: pending review. Have a nice day.", "SO MANY! Twelve friends! Play with ALL!", "So many walking with you. It feels familiar.", "Twelve! Twelve beloved dead marching for us! We could weep!", "Twelve dead. Ours. Enough.", "Twelve of the fallen. A full wedding party."],
  "wup:Adopted": ["Big ones stay. Forever. Three.", "Real ones stay. Your inner circle is three, max. Top 1%.", "They're mine now. Forever. Can't send them back.", "Three permanent appointments. Paperwork handled.", "Elite units onboarded permanently. Welcome to the family plan.", "We keep it! We KEEP IT! Forever! Three!", "Some stay. Not everyone leaves.", "Three great ones are ours forever! Family! Real family!", "Three elites. Permanent. Ours.", "Three of the great ones join our family. They are never leaving."],
  "wup:Mother of Worms": ["Three worms. Round us. They bite.", "Surround yourself with killers. The grind compounds. Sigma behaviour.", "Worms. Round me. Ugh. Fine. They bite things.", "Have the worms see to visitors.", "Perimeter guards: 3. Proximity response: bite. Strength rising.", "Wormies! Three wormies! Bite! Good worms!", "They coil round you, the way they always do.", "Three long children guard us! They grow fiercer for us!", "Three worms. Close guard. Grow stronger.", "Three long children circle us. We are their mother now."],
  "wup:Can't Hold It": ["Swim fast. Hot trail. Swim slow. Weak trail.", "Speed is a lifestyle. Slow men leave nothing. Literally nothing.", "Ugh, so I have to keep going? Fine. Going.", "Let the fire do the hurrying.", "Trail output scales with speed. Idle output: 0%. Please keep moving.", "Fast! Faster! Hot! Hot hot HOT!", "You cannot hold it. You never could, not here.", "Faster! Hotter! We cannot contain it, and we do not want to!", "Fast. Hot trail. Stop, nothing.", "Our hurrying leaves warmth behind. Stillness leaves nothing. So it is."],
  "wup:Burning Rubber": ["Sprint. White line. They cross it. Fire.", "Leave a mark. Literally on fire. That is called mogging the road.", "Sprinting. Don't look. It's embarrassing.", "Let them cross one's path. They will regret it.", "White-hot streak active. Crossing hostiles will be ignited. Thank you!", "Zoom! White zoom! Fire zoom!", "A white line behind you. You have seen it from the other side.", "Our hurrying burns white! Cross it and burn with us!", "Sprint. White streak. They ignite.", "Our hurrying burns white. What crosses it is changed. All things are."],
  "wup:Footloose": ["Fast. Wide trail. Three times wide.", "Take up space. Three lanes wide. Own the road. Frame.", "Bigger mess. Wider mess. Not cleaning it.", "Take the whole road. It was ours anyway.", "Trail width: 300%. Hostile crossing success: unlikely. Have a great day.", "Stomp! Stomp! Fire feet! Stomp again!", "Wider now. There is room for it.", "Flames to the left! Flames to the right! The road is ours!", "Full speed. Wide trail. Three times.", "We leave footsteps of flame although we have no feet. A miracle."],
  "wup:Slip Road": ["They touch it. They skid. Along it. Good.", "Make them slip. Confidence is their weakness. Not yours, obviously.", "Slippery. Mind the floor. Or don't. Whatever.", "Someone has mopped. Do mind yourselves.", "Surface friction: 0%. Hostiles rerouted along trail. Mind the step.", "Wheee! They skiddy! Skid again! WHEEE!", "They slip. Everyone slips here eventually.", "They step on our path and skate away! Away from her!", "They cross. They skid. Gone.", "They step on our path and are carried away. A rude river."],
  "wup:Double Back": ["Cross the line. Fire runs both ways.", "Cross your own line. Comebacks hit harder. That is the comeback arc.", "I went in a circle. On purpose. Obviously.", "One crosses where one likes.", "Trail intersection detected. Fire wave dispatched both ways. Thank you!", "Cross it! FWOOSH! Cross it again! FWOOSH!", "You cross your own path. It lights up. You knew it would.", "Back over our own path! It roars both ways! How it roars!", "Cross the trail. Fire runs both ways.", "We cross where we have been, and the past catches fire."],
  "wup:Full Circle": ["Go round. Close it. Inside burns.", "Box them in. Close the deal. A circle is the strongest frame.", "Round and round. Like a mood. Then everyone burns.", "Draw a ring round them. They're not invited out.", "Loop closed. Enclosed hostiles: now burning. Process complete.", "Round! Round! Round! Hot middle!", "Round you go. And round. It ends where it started.", "We draw a ring of fire! All inside it burn with our devotion!", "Loop closed. All inside burn.", "We draw a ring. What is within it is warmed. Circles are patient."],
  "wup:Flashpoint": ["Two fires meet. Big bang.", "Two forces collide. Synergy. You are the synergy, bro.", "Two fires bumped. Big deal. Big bang, actually.", "When two fires meet, one lets them settle it.", "Wave convergence detected. Burst generated. Efficiency: excellent.", "Fire hits fire! KABOOM! Again!", "They meet in the middle. Things do, in the end.", "Two burnings meet and kiss! The kiss explodes! Glorious!", "Two waves meet. They burst.", "Two burnings meet. Where they meet, there is a bursting. Naturally."],
  "wup:Breadcrumbs": ["Shiny things follow us. We get them.", "Abundance follows winners. Literally. Even the gems simp for you.", "If they want to follow, fine. I'm not going back.", "Things simply come to one.", "Gem tracking enabled. Items will follow you until collected. Thank you.", "They follow! Like ducks! Come on, ducks!", "Small things follow you home. They always find the way.", "Treasures chase us like admirers! Come, come, keep up!", "Gems follow. Collect them. Move.", "Treasures follow us like admirers. We permit it."],
  "wup:Slow Burn": ["Leave it. It gets hot. Then it works.", "Long game. Slow burn. Patience is a high-value trait, allegedly.", "It takes ages to get going. Same.", "Let it warm. One is never in a rush.", "Trail warming. Please allow 2 seconds for full heat. Lasts 3x longer.", "Is it hot? Is it hot yet? Now? NOW?", "It burns slowly. You have time. You always had.", "It warms too slowly! We cannot wait! Burn faster, path!", "Trail starts cold. Heats. Lasts.", "Our path warms slowly, like a long engagement."],
  "wup:Creature of Habit": ["They follow our path. They get hurt more.", "Followers pay more. Monetise your following. Copycats get taxed.", "Stop copying me. It hurts you. Good.", "Those who follow one pay a premium.", "Hostile following route detected. Surcharge applied: extra damage.", "Copycat! Copycat! Ow for copycat!", "They walk where you walked. That never ends well.", "Follow us, would you? Then burn for it! Only she may have us!", "They follow our path. They pay.", "Those who walk our walk are punished for the imitating."],
  "wup:Well Trodden": ["Same way. Same way. Now it stays hot.", "Routine is everything. Grind the same lap. Discipline is a ten.", "Same way every time. Don't make me think.", "One always takes the usual route. The route remembers.", "Repeat route detected. Ember layer applied. Route rating: 5 stars.", "Same way! Again! Again! Hot again!", "The same path, worn in. You have walked it so often.", "Again and again we pass, and the road glows for us!", "Same route. Embers. They stay.", "We walk this road so often it begins to glow with remembering."],
  "wup:Wrong Way": ["Fire goes in front now. Odd. Keep going.", "Lead from the front. Even with this. Especially with this.", "Wrong way round. Fine. Everything is.", "Have the fire go ahead and announce one.", "Trail output reversed. Fire now ahead of you. This is intended.", "Fire first! Then us! Into fire! Hot!", "Ahead of you this time. That is new.", "Our flame runs before us! It cannot wait to reach her!", "Fire ahead. Not behind. Follow it.", "Our flame walks before us like a herald at a wedding."],
  "wup:Afterburner": ["Touch it. Fire. Right away.", "No warm-up. Instant results. That is the programme. Ten out of ten.", "Touch it and you're on fire. Your choice.", "Anyone who touches it is dismissed. Immediately.", "Ignition delay removed. Contact equals ignition. Satisfaction: 99%.", "Touch it! FIRE! Touch it! FIRE!", "It catches straight away now. It used to take longer.", "No courting! Our trail ignites at the first touch!", "Touch it. Burn. Instantly.", "Our trail does not woo. It ignites at the first meeting."],
  "wup:Hot Lap": ["Close the loop. Everything burns. Go fast.", "Victory lap. Burn the room, then leave. Never stay for the cope.", "One lap, everything burns, then I leave. Perfect day.", "A lap of honour. They burn, one departs.", "Loop complete. Contents ignited. Speed boost: 200%. Thanks for riding.", "Round and FIRE and ZOOM! Do it AGAIN!", "Round once more. Then quickly away. Yes.", "The circle closes and they burn! Now fly! Fly to her!", "Loop closed. They burn. Fast now.", "We complete the circle and they burn. Then our leaving is very fast."],
  "wup:Scorched Route": ["The trail stays hot. A long time.", "Legacy. Your trail outlives the haters. That is generational.", "It just stays there. Burning. Like a grudge.", "Let them remember where one has been.", "Trail heat retention: extended. Route remains hazardous. Swim safely.", "Hot! Still hot! Still! Still hot!", "It burns long after you pass. Some things do.", "Our road stays burning! Nothing will cool what we feel!", "Trail stays hot. Long time.", "The road remembers our passing for a long time. It is still warm."]
};
// The line for this run's sample ('' when there is none, e.g. a sample-only Feat for another sample, or on the title screen).
function cardLine(key) {
  const v = CARD_VOICE[key]; if (!v) return '';
  let s = (typeof s10Of === 'function' && s10Of()) || 'baseline';
  if (s === 'alien') {
    const t = G && G.s10 && typeof S10_BY !== 'undefined' && S10_BY.alien && S10_BY.alien.shift ? S10_BY.alien.shift[G.s10.shiftI || 0] : 'soul';
    s = CV_ALIEN[t] || 'alien_soul';
  }
  const i = CV_COLS.indexOf(s);
  return i >= 0 ? v[i] : '';
}
// A draft card (draft.js card shape) -> its line. Feat rank-ups and cards without a line get ''.
function cardVoice(c) {
  if (!c) return '';
  if (c.slot === 'feat') {
    if (c.kind !== 'acquire') return '';
    const l = cardLine('feat:' + c.title); if (l || CARD_VOICE['feat:' + c.title]) return l;
    const d = typeof F10 !== 'undefined' && Object.values(F10).find(d => d.name === c.title); // (a Feat not in the sheet keeps its old line)
    return d && d.line ? String(d.line).replace(/^"|"$/g, '') : '';
  }
  if (c.family === 'catalyst') return cardLine('mut:*catalyst');
  if (c.family && c.family.indexOf('conc:') === 0) return cardLine('mut:*concentration');
  return cardLine('mut:' + c.title);
}
